import React, { useState, useEffect } from 'react';
import { useApp } from '../context';
import { Button, Input } from '../components/UI';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { Role } from '../types';
import { LOGO_URL } from '../constants';

export const Login: React.FC = () => {
    const { login } = useApp();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        const result = await login(email, password);

        setIsLoading(false);
        if (result.success) {
            const role = result.role;
            // DYNAMIC PERSPECTIVE REDIRECT
            if (role === 'admin') navigate('/admin/dashboard');
            else if (role === 'vendor') navigate('/vendor/dashboard');
            else if (role === 'courier') navigate('/delivery/dashboard');
            else navigate('/buyer/dashboard');
        } else {
            setError(result.error || 'Login failed');
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
            <div className="absolute top-[-10%] right-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl opacity-50"></div>
            <div className="absolute bottom-[-10%] left-[-10%] w-80 h-80 bg-secondary/10 rounded-full blur-3xl opacity-50"></div>

            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-fade-in">
                <div className="mb-8 text-center">
                    <div className="mb-6 inline-block">
                        <img 
                          src={LOGO_URL} 
                          alt="LYNQED" 
                          className="h-48 w-48 rounded-full object-cover border-4 border-primary/20 dark:border-primary/10 mx-auto bg-white dark:bg-darkSurface shadow-2xl p-1" 
                        />
                    </div>
                    <h1 className="text-4xl font-display font-extrabold text-gray-900 dark:text-white tracking-tight">Welcome Back</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium">Sign in to continue to LYNQED</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm p-3 rounded-xl mb-4 flex items-center">
                        <i className="fa-solid fa-circle-exclamation mr-2"></i>
                        {error}
                    </div>
                )}

                <form onSubmit={handleLogin} className="space-y-6">
                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email"
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />

                    <div>
                        <Input 
                            label="Password" 
                            icon="lock" 
                            type="password"
                            placeholder="••••••••" 
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                        />
                        <div className="flex justify-end -mt-3 mb-2">
                            <Link 
                                to="/forgot-password"
                                className="text-xs font-bold text-primary dark:text-primaryLight hover:text-primaryDark transition-colors"
                            >
                                Forgot Password?
                            </Link>
                        </div>
                    </div>

                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                        className="shadow-xl shadow-primary/30"
                    >
                        {isLoading ? 'Signing in...' : 'Sign In'}
                    </Button>
                </form>

                <div className="mt-8 text-center text-sm text-gray-500 dark:text-gray-400">
                    Don't have an account? <Link to="/register" className="font-bold text-primary dark:text-primaryLight hover:text-primaryDark transition-colors">Create Account</Link>
                </div>
            </div>
        </div>
    );
};

export const ForgotPassword: React.FC = () => {
    const { resetPassword, showToast } = useApp();
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [sent, setSent] = useState(false);
    const [timer, setTimer] = useState(0);

    useEffect(() => {
        let interval: any;
        if (timer > 0) {
            interval = setInterval(() => {
                setTimer((prev) => prev - 1);
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [timer]);

    const handleReset = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();
        if (timer > 0) return;

        setError('');
        setIsLoading(true);

        const result = await resetPassword(email);
        setIsLoading(false);

        if (result.success) {
            setSent(true);
            setTimer(60); // 1 minute cooldown
            if (!e) showToast("Reset link sent again!", "success");
        } else {
            setError(result.error || 'Failed to send reset email.');
        }
    };

    if (sent) {
        return (
            <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
                <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full text-center animate-fade-in">
                    <div className="w-20 h-20 bg-green-50 dark:bg-green-900/20 text-green-500 rounded-full flex items-center justify-center mx-auto mb-6 border border-green-100 dark:border-green-800 shadow-lg">
                        <i className="fa-solid fa-paper-plane text-3xl"></i>
                    </div>
                    <h1 className="text-2xl font-display font-extrabold text-gray-900 dark:text-white">Check Your Inbox</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-3 text-sm leading-relaxed px-4">
                        We've sent a secure password reset link to <br /><span className="font-bold text-gray-900 dark:text-white">{email}</span>.
                    </p>

                    <div className="mt-10 p-6 bg-gray-50 dark:bg-darkSurface rounded-3xl border border-gray-100 dark:border-gray-800">
                        <p className="text-xs text-gray-400 dark:text-gray-500 mb-4">
                            Didn't receive the email?
                        </p>
                        <button 
                            onClick={() => handleReset()}
                            disabled={timer > 0 || isLoading}
                            className={`text-sm font-bold transition-all ${timer > 0 ? 'text-gray-300 cursor-not-allowed' : 'text-primary hover:text-primaryDark active:scale-95'}`}
                        >
                            {timer > 0 ? `Resend available in ${timer}s` : 'Resend Link Now'}
                        </button>
                    </div>

                    <Link to="/login" className="mt-8 inline-block text-sm font-bold text-gray-400 dark:text-gray-500 hover:text-gray-900 dark:hover:text-white transition-colors">
                        <i className="fa-solid fa-arrow-left mr-2"></i> Back to Login
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
            <div className="absolute top-[-10%] left-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl opacity-50"></div>
            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-10 text-center">
                    <h1 className="text-3xl font-display font-extrabold text-gray-900 dark:text-white tracking-tight">Forgot Password?</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 text-sm px-8">No worries, it happens. Enter your email and we'll help you get back in.</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm p-4 rounded-2xl mb-6 flex items-start">
                        <i className="fa-solid fa-circle-exclamation mt-1 mr-3"></i>
                        {error}
                    </div>
                )}

                <form onSubmit={handleReset} className="space-y-6">
                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email" 
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />
                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                        className="shadow-xl shadow-primary/30"
                    >
                        {isLoading ? 'Sending Request...' : 'Send Reset Link'}
                    </Button>
                </form>

                <div className="mt-8 text-center">
                    <Link to="/login" className="text-sm font-bold text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors">
                        <i className="fa-solid fa-arrow-left mr-2"></i> Back to Login
                    </Link>
                </div>
            </div>
        </div>
    );
};

export const UpdatePassword: React.FC = () => {
    const { updatePassword, showToast } = useApp();
    const navigate = useNavigate();
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleUpdate = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        if (password !== confirmPassword) {
            setError("Passwords do not match");
            return;
        }

        if (password.length < 6) {
            setError("Password must be at least 6 characters long");
            return;
        }

        setIsLoading(true);
        const result = await updatePassword(password);
        setIsLoading(false);

        if (result.success) {
            showToast("Password updated successfully!", "success");
            navigate('/login');
        } else {
            setError(result.error || 'Failed to update password.');
        }
    };

    const isMatch = password && confirmPassword && password === confirmPassword;

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
            <div className="absolute bottom-[-10%] right-[-10%] w-64 h-64 bg-secondary/10 rounded-full blur-3xl opacity-50"></div>
            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-3xl font-display font-extrabold text-gray-900 dark:text-white">Set New Password</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 text-sm">Create a strong, secure password for your account</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm p-3 rounded-xl mb-4 flex items-center">
                         <i className="fa-solid fa-circle-exclamation mr-2"></i>
                        {error}
                    </div>
                )}

                <form onSubmit={handleUpdate} className="space-y-6">
                    <div>
                        <Input 
                            label="New Password" 
                            icon="lock" 
                            type="password"
                            placeholder="New secure password" 
                            value={password}
                            onChange={e => setPassword(e.target.value)} 
                            required
                            minLength={6}
                        />
                        <p className={`text-[10px] ml-1 -mt-4 mb-4 font-bold uppercase tracking-tight ${password.length >= 6 ? 'text-green-500' : 'text-gray-400'}`}>
                            {password.length >= 6 ? '✓ Strong enough' : 'Min. 6 characters required'}
                        </p>
                    </div>

                    <div>
                        <Input 
                            label="Confirm New Password" 
                            icon="lock" 
                            type="password"
                            placeholder="Re-type your new password" 
                            value={confirmPassword}
                            onChange={e => setConfirmPassword(e.target.value)} 
                            required
                            minLength={6}
                        />
                        {confirmPassword && (
                            <p className={`text-[10px] ml-1 -mt-4 mb-4 font-bold uppercase tracking-tight ${isMatch ? 'text-green-500' : 'text-red-500'}`}>
                                {isMatch ? '✓ Passwords match' : '✗ Passwords do not match'}
                            </p>
                        )}
                    </div>

                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading || !isMatch || password.length < 6}
                        className="shadow-xl shadow-primary/30 mt-2"
                    >
                        {isLoading ? 'Updating...' : 'Update Password'}
                    </Button>
                </form>
            </div>
        </div>
    );
};

export const Register: React.FC = () => {
    const { signup, registerCourier } = useApp();
    const navigate = useNavigate();
    const location = useLocation();

    // Initialize role from state if provided (e.g., from Welcome page)
    const initialRole = (location.state as any)?.role || 'buyer';

    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [phoneNumber, setPhoneNumber] = useState('');
    const [role, setRole] = useState<Role>(initialRole);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSignup = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        const result = await signup(email, password, fullName, role, phoneNumber);

        if (result.success) {
            if (role === 'courier') {
                const userId = result.user?.id;
                const courierRes = await registerCourier({ fullName, phoneNumber }, userId);
                setIsLoading(false);
                if (courierRes.success) {
                    alert("Courier account created! Please wait for admin verification.");
                    navigate('/buyer/profile');
                } else {
                    setError("Account created but failed to submit courier application. Please contact support.");
                }
            } else if (role === 'vendor') {
                 // ONLY vendors should be sent to onboarding
                 setIsLoading(false);
                 navigate('/vendor/onboarding');
            } else {
                 // Buyers are sent directly to the dashboard
                 setIsLoading(false);
                 navigate('/buyer/dashboard');
            }
        } else {
            setIsLoading(false);
            setError(result.error || 'Registration failed. Email might be taken.');
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
             <div className="absolute top-[-10%] left-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl opacity-50"></div>

             <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-3xl font-display font-extrabold text-gray-900 dark:text-white">Create Account</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2">Join the campus marketplace</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm p-3 rounded-xl mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSignup} className="space-y-5">
                    <Input 
                        label="Full Name" 
                        icon="user" 
                        placeholder="John Doe" 
                        value={fullName} 
                        onChange={e => setFullName(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email" 
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Phone Number" 
                        icon="phone" 
                        type="tel" 
                        placeholder="050 123 4567" 
                        value={phoneNumber} 
                        onChange={e => setPhoneNumber(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Password" 
                        icon="lock" 
                        type="password"
                        placeholder="Create a password" 
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        required
                        minLength={6}
                    />

                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2 ml-1">I want to...</label>
                        <div className="grid grid-cols-3 gap-2">
                            <div 
                                onClick={() => setRole('buyer')}
                                className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'buyer' ? 'border-primary bg-primary/5 text-primary font-bold' : 'border-gray-100 dark:border-gray-800 text-gray-500 dark:text-gray-400'}`}
                            >
                                <i className="fa-solid fa-bag-shopping text-lg"></i>
                                <span className="text-[10px]">Buy</span>
                            </div>
                            <div 
                                onClick={() => setRole('vendor')}
                                className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'vendor' ? 'border-secondary bg-secondary/5 text-secondary font-bold' : 'border-gray-100 dark:border-gray-800 text-gray-500 dark:text-gray-400'}`}
                            >
                                <i className="fa-solid fa-store text-lg"></i>
                                <span className="text-[10px]">Sell</span>
                            </div>
                            <div 
                                onClick={() => setRole('courier')}
                                className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'courier' ? 'border-blue-500 bg-blue-50 text-blue-600 font-bold' : 'border-gray-100 dark:border-gray-800 text-gray-500 dark:text-gray-400'}`}
                            >
                                <i className="fa-solid fa-motorcycle text-lg"></i>
                                <span className="text-[10px]">Deliver</span>
                            </div>
                        </div>
