export const BuyerDashboard: React.FC = () => {
  const { products, vendors, favorites, toggleFavorite, currentUser, addToCart, removeFromCart, cart, showToast, isDataLoading } = useApp();
  const navigate = useNavigate();
  const [selectedCat, setSelectedCat] = useState('All');
  const [sortType, setSortType] = useState<'nearby' | 'price' | 'rating'>('nearby');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
              (position) => setUserLocation({ lat: position.coords.latitude, lng: position.coords.longitude }),
              () => setUserLocation({ lat: 5.6506, lng: -0.1962 })
          );
      }
  }, []);

  const getDistanceFromLatLonInKm = (lat1: number, lon1: number, lat2: number, lon2: number) => {
      const R = 6371; 
      const dLat = (lat2 - lat1) * (Math.PI/180);
      const dLon = (lon2 - lon1) * (Math.PI/180);
      const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(lat1 * (Math.PI/180)) * Math.cos(lat2 * (Math.PI/180)) * Math.sin(dLon/2) * Math.sin(dLon/2); 
      return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))); 
  };

  const getCoordsForLocation = (locStr: string): {lat: number, lng: number} | null => {
      const clean = locStr.toLowerCase();
      if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
      const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
      if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
      return null;
  };

  const categoryList = useMemo(() => [
      { id: 'cat-all', name: 'All', icon: 'layer-group', image: '' },
      ...CATEGORIES
  ], []);

  const trendingItems = useMemo(() => {
      return products.filter(p => p.isTrending && p.status === 'approved');
  }, [products]);

  const sortedProducts = useMemo(() => {
      const approvedProducts = products.filter(p => p.status === 'approved');
      let filtered = selectedCat === 'All' ? approvedProducts : approvedProducts.filter(p => p.category === selectedCat);

      if (sortType === 'price') return [...filtered].sort((a, b) => a.price - b.price);
      if (sortType === 'rating') return [...filtered].sort((a, b) => (b.rating || 0) - (a.rating || 0));
      if (sortType === 'nearby' && userLocation) {
          return [...filtered].sort((a, b) => {
              const coordsA = getCoordsForLocation(a.location);
              const coordsB = getCoordsForLocation(b.location);
              const distA = coordsA ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsA.lat, coordsA.lng) : 999;
              const distB = coordsB ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsB.lat, coordsB.lng) : 999;
              return distA - distB;
          });
      }
      return filtered;
  }, [products, selectedCat, sortType, userLocation]);

  return (
    <div className="flex flex-col space-y-5 animate-fade-in pb-4 bg-gray-50 dark:bg-darkBg min-h-screen overflow-x-hidden">
      <div className="bg-white/90 dark:bg-darkSurface/90 backdrop-blur-xl pt-2 pb-3 px-4 sticky top-0 z-30 border-b border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="relative group" onClick={() => navigate('/buyer/search')}>
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <i className="fa-solid fa-magnifying-glass text-gray-400"></i>
            </div>
            <input readOnly placeholder="Search campus stores..." className="block w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-darkBg py-2.5 pl-10 pr-4 text-sm text-gray-900 dark:text-white cursor-pointer hover:bg-white dark:hover:bg-darkSurface transition-all" />
        </div>
      </div>

      {/* Indefinite Scroll Trending Section */}
      {trendingItems.length > 0 && (
          <div className="space-y-4">
              <div className="flex items-center gap-2 px-4">
                  <i className="fa-solid fa-fire text-accent text-sm"></i>
                  <h3 className="font-display font-black text-gray-900 dark:text-white text-xs uppercase tracking-[0.2em]">Trending Now</h3>
              </div>
              <div className="relative w-full overflow-hidden">
                  <div className="flex animate-scroll hover:pause-on-hover py-2 w-max gap-8 px-4">
                      {[...trendingItems, ...trendingItems, ...trendingItems].map((p, idx) => (
                          <div 
                              key={`${p.id}-${idx}`} 
                              onClick={() => navigate(`/buyer/product/${p.id}`)}
                              className="w-80 flex-shrink-0 bg-white dark:bg-darkSurface rounded-[2.5rem] shadow-float border border-gray-100 dark:border-gray-800 overflow-hidden cursor-pointer group hover:-translate-y-2 transition-all duration-500"
                          >
                              <div className="h-52 overflow-hidden relative bg-gray-50 dark:bg-gray-900">
                                  <img src={p.images[0]} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
                                  <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent"></div>
                                  <div className="absolute top-4 left-4">
                                      <Badge color="violet" className="backdrop-blur-md bg-white/80 dark:bg-darkBg/80 shadow-sm border-white/50 px-3 py-1.5">Promotion</Badge>
                                  </div>
                              </div>
                              <div className="p-5">
                                  <p className="text-sm font-black text-gray-900 dark:text-white truncate uppercase tracking-tight mb-1 font-display">{p.title}</p>
                                  <div className="flex justify-between items-center">
                                      <p className="text-primary font-black text-lg">₵{p.price.toFixed(2)}</p>
                                      <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center transition-colors group-hover:bg-primary group-hover:text-white">
                                          <i className="fa-solid fa-arrow-right text-[10px]"></i>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="pl-4">
        <h3 className="font-display font-bold text-gray-400 text-[10px] uppercase tracking-widest mb-3 opacity-60">Categories</h3>
        <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-2 pr-4">
            {categoryList.map(cat => (
                <div key={cat.id} className="flex flex-col items-center gap-1 cursor-pointer min-w-[72px]" onClick={() => setSelectedCat(cat.name)}>
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center transition-all overflow-hidden border-2 ${selectedCat === cat.name ? 'border-primary ring-2 ring-primary/20' : 'border-transparent bg-gray-200 dark:bg-darkSurface text-gray-500'}`}>
                        {cat.image ? <img src={cat.image} className="w-full h-full object-cover" /> : <i className={`fa-solid fa-${cat.icon} text-lg`}></i>}
                    </div>
                    <span className={`text-[10px] font-bold text-center w-full uppercase ${selectedCat === cat.name ? 'text-primary' : 'text-gray-500'}`}>{cat.name}</span>
                </div>
            ))}
        </div>
      </div>

      <div className="px-4 pb-24">
         <div className="flex justify-between items-center mb-4">
            <h3 className="font-display font-black text-gray-900 dark:text-white text-sm uppercase tracking-widest opacity-60">Campus Feed</h3>
            <div className="flex gap-1.5">
                {['nearby', 'price'].map(type => (
                    <button key={type} onClick={() => setSortType(type as any)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${sortType === type ? 'bg-primary text-white' : 'bg-white dark:bg-darkSurface text-gray-400 border border-gray-100 dark:border-gray-800'}`}>{type}</button>
                ))}
            </div>
         </div>

         {isDataLoading ? (
             <div className="grid grid-cols-2 gap-3">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                {sortedProducts.map(product => {
                    const vendor = vendors.find(v => v.vendorId === product.vendorId);
