    const [activeImg, setActiveImg] = useState(0);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleShare = async () => {
        const shareData = {
            title: product.title,
            text: `Check out ${product.title} from ${vendor?.storeName || 'LYNQED'}!`,
            url: window.location.href
        };

        if (navigator.share) {
            try {
                await navigator.share(shareData);
            } catch (err) {
                if ((err as Error).name !== 'AbortError') {
                    copyToClipboard();
                }
            }
        } else {
            copyToClipboard();
        }
    };

    const copyToClipboard = async () => {
        try {
            await navigator.clipboard.writeText(window.location.href);
            showToast("Link copied to clipboard!", "success");
        } catch (err) {
            showToast("Failed to copy link", "error");
        }
    };

    const handleAddToCart = () => {
        if (product.stock === 0) return;
        addToCart(product, quantity);
    };

    const handleBuyNow = () => {
        if (product.stock === 0) return;
        if (!isInCart) addToCart(product, quantity);
        navigate('/buyer/checkout');
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            {/* Action Bar */}
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-100 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center justify-between">
                <button onClick={() => navigate(-1)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-300 transition-colors">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="flex gap-2">
                    <button 
                        onClick={handleShare} 
                        className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-50 dark:bg-gray-800 text-gray-500 hover:text-primary transition-all shadow-sm"
                        title="Share Product"
                    >
                        <i className="fa-solid fa-share-nodes text-sm"></i>
                    </button>
                    <button 
                        onClick={() => toggleFavorite(product.id)} 
                        className={`w-10 h-10 flex items-center justify-center rounded-full transition-all shadow-sm ${isFav ? 'bg-red-500 text-white' : 'bg-gray-50 dark:bg-gray-800 text-gray-400'}`}
                        title={isFav ? "Remove from Wishlist" : "Add to Wishlist"}
                    >
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart text-sm`}></i>
                    </button>
                </div>
            </div>

            <div className="max-w-4xl mx-auto">
                {/* Images */}
                <div className="relative aspect-square sm:aspect-video overflow-hidden bg-gray-200 dark:bg-gray-900 sm:rounded-b-3xl">
                    <img 
                        src={product.images[activeImg]} 
                        className="w-full h-full object-cover" 
                        alt={product.title} 
                    />
                    {product.images.length > 1 && (
                        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-2">
                            {product.images.map((_, i) => (
                                <button 
                                    key={i} 
                                    onClick={() => setActiveImg(i)}
                                    className={`h-1.5 rounded-full transition-all ${activeImg === i ? 'w-6 bg-white' : 'w-2 bg-white/50'}`}
                                />
                            ))}
                        </div>
                    )}
                    {product.stock === 0 && (
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] flex items-center justify-center">
                            <Badge color="red" className="px-6 py-2 text-sm shadow-xl">Out of Stock</Badge>
                        </div>
                    )}
                </div>

                <div className="p-5 sm:p-8 space-y-8">
                    {/* Header Info */}
                    <div>
                        <div className="flex justify-between items-start mb-2">
                            <Badge color="violet" className="px-3 py-1">{product.category}</Badge>
                            <div className="flex items-center gap-1 text-yellow-500">
                                <i className="fa-solid fa-star text-xs"></i>
                                <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{product.rating || '5.0'}</span>
                                <span className="text-xs text-gray-400">({product.reviewCount || 0})</span>
                            </div>
                        </div>
                        <h1 className="text-2xl sm:text-3xl font-display font-black text-gray-900 dark:text-white leading-tight mb-2">
                            {product.title}
                        </h1>
                        <p className="text-3xl font-black text-primary">₵{product.price.toFixed(2)}</p>
                    </div>

                    {/* Vendor Card */}
                    {vendor && (
                        <Link to={`/store/${vendor.vendorId}`}>
                            <Card className="p-4 flex items-center justify-between hover:border-primary/30 transition-all border-gray-100 dark:border-gray-800">
                                <div className="flex items-center gap-4">
                                    <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="lg" />
                                    <div>
                                        <h4 className="font-bold text-gray-900 dark:text-white leading-tight">{vendor.storeName}</h4>
                                        <p className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                            <i className="fa-solid fa-location-dot text-primary"></i> {vendor.location}
                                        </p>
                                    </div>
                                </div>
                                <i className="fa-solid fa-chevron-right text-gray-300"></i>
                            </Card>
                        </Link>
                    )}

                    {/* Description */}
                    <div className="space-y-3">
                        <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest">Product Details</h3>
                        <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm sm:text-base">
                            {product.description}
                        </p>
                    </div>

                    {/* Action Section */}
                    <div className="space-y-4">
                        <div className="flex items-center gap-4">
                            <div className="flex items-center bg-gray-100 dark:bg-darkSurface rounded-2xl p-1 border border-gray-200 dark:border-gray-800">
                                <button 
                                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                                    className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary transition-colors"
                                >
                                    <i className="fa-solid fa-minus"></i>
                                </button>
                                <span className="w-12 text-center font-bold dark:text-white">{quantity}</span>
                                <button 
                                    onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
                                    className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary transition-colors"
                                >
                                    <i className="fa-solid fa-plus"></i>
                                </button>
                            </div>
                            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">
                                {product.stock} units available
                            </p>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2">
                            <Button 
                                size="lg" 
                                variant="secondary" 
                                onClick={handleAddToCart}
                                disabled={product.stock === 0}
                                icon={isInCart ? "check" : "cart-plus"}
                            >
                                {isInCart ? "Added to Cart" : "Add to Cart"}
                            </Button>
                            <Button 
                                size="lg" 
                                onClick={handleBuyNow}
                                disabled={product.stock === 0}
                                className="shadow-lg shadow-primary/30"
                            >
                                Buy Now
                            </Button>
                        </div>
                    </div>

                    {/* Reviews */}
                    <div className="pt-8 border-t border-gray-100 dark:border-gray-800">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest">Reviews ({productReviews.length})</h3>
                            {currentUser && (
                                <button 
                                    onClick={() => setIsReviewModalOpen(true)}
                                    className="text-xs font-bold text-primary hover:underline"
                                >
                                    Write a Review
                                </button>
                            )}
                        </div>

                        <div className="space-y-6">
                            {productReviews.length === 0 ? (
                                <div className="text-center py-10 bg-gray-100 dark:bg-darkBg rounded-3xl">
                                    <p className="text-gray-400 text-xs font-medium">Be the first to review this product!</p>
                                </div>
                            ) : (
                                productReviews.map((review, i) => (
                                    <div key={i} className="space-y-3">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <Avatar src={review.user?.avatarUrl} name={review.user?.name || 'User'} size="sm" />
                                                <div>
                                                    <p className="text-xs font-bold dark:text-white">{review.user?.name}</p>
                                                    <div className="flex text-yellow-400 text-[8px] gap-0.5">
                                                        {[...Array(5)].map((_, i) => (
                                                            <i key={i} className={`fa-solid fa-star ${i >= review.rating ? 'text-gray-200 dark:text-gray-700' : ''}`}></i>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                            <span className="text-[10px] text-gray-400">{new Date(review.createdAt).toLocaleDateString()}</span>
                                        </div>
                                        <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed pl-11">
                                            {review.comment}
                                        </p>
                                        {review.images && review.images.length > 0 && (
                                            <div className="flex gap-2 pl-11">
                                                {review.images.map((img, idx) => (
                                                    <img key={idx} src={img} className="w-16 h-16 rounded-xl object-cover border border-gray-100 dark:border-gray-800" />
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {isReviewModalOpen && vendor && (
                <ReviewModal 
                    productId={product.id} 
                    vendorId={vendor.vendorId} 
                    onClose={() => setIsReviewModalOpen(false)} 
                />
            )}
        </div>
    );
};

