                                >
                                    <i className={`fa-${isFavorite ? 'solid' : 'regular'} fa-heart text-[10px]`}></i>
                                </button>

                                {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><span className="bg-black text-white text-[8px] px-2 py-1 rounded font-bold uppercase">Sold Out</span></div>}
                            </div>
                            <div className="p-3 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2">{product.title}</h3>
                                    <p className="text-[10px] text-gray-400 mt-1">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <span className="text-sm font-extrabold text-gray-900 dark:text-white">₵{product.price}</span>
                                    <button 
                                        className={`w-7 h-7 rounded-full flex items-center justify-center text-white transition-all ${isInCart ? 'bg-green-500 scale-110' : 'bg-black dark:bg-white dark:text-black active:scale-90'}`}
                                        onClick={(e) => { e.stopPropagation(); if (product.stock > 0) isInCart ? removeFromCart(product.id) : addToCart(product); }}
                                    >
                                        <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-[10px]`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
// Added missing Navigate import to resolve "Cannot find name 'Navigate'" error
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product, Review } from '../types';

export const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
    existingReview?: Review;
}> = ({ productId, vendorId, onClose, existingReview }) => {
    const { submitReview, currentUser, uploadFile } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [images, setImages] = useState<string[]>(existingReview?.images || []);
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setUploading(true);
            const files = Array.from(e.target.files);
            const uploaded: string[] = [];
            for (const file of files) {
                const url = await uploadFile(file, 'review-images');
                if (url) uploaded.push(url);
            }
            setImages(prev => [...prev, ...uploaded]);
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            id: existingReview?.id, productId, vendorId, userId: currentUser.id,
            rating, comment, images
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-w-lg rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white">{existingReview ? 'Edit Review' : 'Write a Review'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} type="button" onClick={() => setRating(star)} className={`text-3xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-200 dark:text-gray-700'}`}>
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>
                    <textarea
                        className="w-full rounded-2xl bg-gray-50 dark:bg-gray-900 p-4 text-sm h-32 outline-none border border-gray-100 dark:border-gray-800 dark:text-white"
                        placeholder="Tell us what you think..."
                        value={comment}
                        onChange={e => setComment(e.target.value)}
                        required
                    />
                    <div className="flex flex-wrap gap-2">
                        {images.map((img, i) => (
                            <img key={i} src={img} className="w-16 h-16 rounded-lg object-cover" />
                        ))}
                        {images.length < 3 && (
                            <button type="button" onClick={() => fileRef.current?.click()} className="w-16 h-16 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center text-gray-400">
                                {uploading ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-camera"></i>}
                            </button>
                        )}
                    </div>
                    <input type="file" ref={fileRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
                    <Button fullWidth size="lg" type="submit" disabled={submitting || uploading}>{submitting ? 'Posting...' : 'Submit Review'}</Button>
                </form>
            </Card>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast, reviews, orders, currentUser } = useApp();
    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);
    const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
    const [quantity, setQuantity] = useState(1);
    const [activeImg, setActiveImg] = useState(0);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleShare = async () => {
        // Construct a clean sharing link (ensures it works even if we are on a hash route)
        const baseUrl = window.location.origin + window.location.pathname;
        const hashPath = window.location.hash.split('?')[0]; // Get current #/path
        const fullShareUrl = baseUrl + hashPath;

        const shareData = {
            title: `LYNQED: ${product.title}`,
            text: `Hey, check out ${product.title} from ${vendor?.storeName || 'LYNQED'}! It's only ₵${product.price}.`,
            url: fullShareUrl
        };

        // 1. Try Native Sharing first (perfect for mobile browsers/apps)
        if (navigator.share && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
            try {
                await navigator.share(shareData);
                return; // Shared successfully
            } catch (err) {
                // User cancelled or share failed, fallback to copy
                if ((err as Error).name !== 'AbortError') {
                    copyToClipboard(fullShareUrl);
                }
            }
        } else {
            // 2. Fallback to Clipboard (best for Desktop)
            copyToClipboard(fullShareUrl);
        }
    };

    const copyToClipboard = async (url: string) => {
        try {
            // Use legacy fallback if navigator.clipboard is missing (common in some dev previews)
            if (!navigator.clipboard) {
                const textArea = document.createElement("textarea");
                textArea.value = url;
                document.body.appendChild(textArea);
                textArea.select();
                try {
                    document.execCommand('copy');
                    showToast("Product link copied to clipboard!", "success");
                } catch (err) {
                    showToast("Couldn't copy link. Please try again.", "error");
                }
                document.body.removeChild(textArea);
            } else {
                await navigator.clipboard.writeText(url);
                showToast("Product link copied to clipboard!", "success");
            }
        } catch (err) {
            showToast("Failed to copy link. Check your permissions.", "error");
        }
    };

    const handleAddToCart = () => {
        if (product.stock === 0) return;
        addToCart(product, quantity);
    };

    const handleBuyNow = () => {
        if (product.stock === 0) return;
        if (!isInCart) addToCart(product, quantity);
        navigate('/buyer/checkout');
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            {/* Action Bar */}
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-100 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center justify-between">
                <button onClick={() => navigate(-1)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-300 transition-colors">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="flex gap-2">
                    <button 
                        onClick={handleShare} 
                        className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-50 dark:bg-gray-800 text-gray-500 hover:text-primary transition-all shadow-sm active:scale-90"
                        title="Share Product"
                    >
                        <i className="fa-solid fa-share-nodes text-sm"></i>
                    </button>
                    <button 
                        onClick={() => toggleFavorite(product.id)} 
                        className={`w-10 h-10 flex items-center justify-center rounded-full transition-all shadow-sm ${isFav ? 'bg-red-500 text-white' : 'bg-gray-50 dark:bg-gray-800 text-gray-400'}`}
                        title={isFav ? "Remove from Wishlist" : "Add to Wishlist"}
                    >
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart text-sm`}></i>
                    </button>
                </div>
            </div>

            <div className="max-w-4xl mx-auto">
                {/* Images */}
                <div className="relative aspect-square sm:aspect-video overflow-hidden bg-gray-200 dark:bg-gray-900 sm:rounded-b-3xl">
                    <img 
                        src={product.images[activeImg]} 
                        className="w-full h-full object-cover" 
                        alt={product.title} 
                    />
                    {product.images.length > 1 && (
                        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-2">
                            {product.images.map((_, i) => (
                                <button 
                                    key={i} 
                                    onClick={() => setActiveImg(i)}
                                    className={`h-1.5 rounded-full transition-all ${activeImg === i ? 'w-6 bg-white' : 'w-2 bg-white/50'}`}
                                />
                            ))}
                        </div>
                    )}
                    {product.stock === 0 && (
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] flex items-center justify-center">
                            <Badge color="red" className="px-6 py-2 text-sm shadow-xl">Out of Stock</Badge>
                        </div>
                    )}
                </div>

                <div className="p-5 sm:p-8 space-y-8">
                    {/* Header Info */}
                    <div>
                        <div className="flex justify-between items-start mb-2">
                            <Badge color="violet" className="px-3 py-1">{product.category}</Badge>
                            <div className="flex items-center gap-1 text-yellow-500">
                                <i className="fa-solid fa-star text-xs"></i>
                                <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{product.rating || '5.0'}</span>
                                <span className="text-xs text-gray-400">({product.reviewCount || 0})</span>
                            </div>
                        </div>
                        <h1 className="text-2xl sm:text-3xl font-display font-black text-gray-900 dark:text-white leading-tight mb-2">
                            {product.title}
                        </h1>
                        <p className="text-3xl font-black text-primary">₵{product.price.toFixed(2)}</p>
                    </div>

                    {/* Vendor Card */}
                    {vendor && (
                        <Link to={`/store/${vendor.vendorId}`}>
                            <Card className="p-4 flex items-center justify-between hover:border-primary/30 transition-all border-gray-100 dark:border-gray-800">
                                <div className="flex items-center gap-4">
                                    <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="lg" />
                                    <div>
                                        <h4 className="font-bold text-gray-900 dark:text-white leading-tight">{vendor.storeName}</h4>
                                        <p className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                            <i className="fa-solid fa-location-dot text-primary"></i> {vendor.location}
                                        </p>
                                    </div>
                                </div>
                                <i className="fa-solid fa-chevron-right text-gray-300"></i>
                            </Card>
                        </Link>
                    )}

                    {/* Description */}
                    <div className="space-y-3">
                        <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest">Product Details</h3>
                        <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm sm:text-base">
                            {product.description}
                        </p>
                    </div>

                    {/* Action Section */}
                    <div className="space-y-4">
                        <div className="flex items-center gap-4">
                            <div className="flex items-center bg-gray-100 dark:bg-darkSurface rounded-2xl p-1 border border-gray-200 dark:border-gray-800">
                                <button 
                                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                                    className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary transition-colors"
                                >
                                    <i className="fa-solid fa-minus"></i>
                                </button>
                                <span className="w-12 text-center font-bold dark:text-white">{quantity}</span>
                                <button 
                                    onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
                                    className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary transition-colors"
                                >
                                    <i className="fa-solid fa-plus"></i>
                                </button>
                            </div>
                            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">
                                {product.stock} units available
                            </p>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2">
                            <Button 
                                size="lg" 
                                variant="secondary" 
                                onClick={handleAddToCart}
                                disabled={product.stock === 0}
                                icon={isInCart ? "check" : "cart-plus"}
                            >
                                {isInCart ? "Added to Cart" : "Add to Cart"}
                            </Button>
                            <Button 
                                size="lg" 
                                onClick={handleBuyNow}
                                disabled={product.stock === 0}
                                className="shadow-lg shadow-primary/30"
                            >
                                Buy Now
                            </Button>
                        </div>
                    </div>

                    {/* Reviews */}
                    <div className="pt-8 border-t border-gray-100 dark:border-gray-800">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest">Reviews ({productReviews.length})</h3>
                            {currentUser && (
                                <button 
                                    onClick={() => setIsReviewModalOpen(true)}
                                    className="text-xs font-bold text-primary hover:underline"
                                >
                                    Write a Review
                                </button>
                            )}
                        </div>

                        <div className="space-y-6">
                            {productReviews.length === 0 ? (
                                <div className="text-center py-10 bg-gray-100 dark:bg-darkBg rounded-3xl">
                                    <p className="text-gray-400 text-xs font-medium">Be the first to review this product!</p>
                                </div>
                            ) : (
                                productReviews.map((review, i) => (
                                    <div key={i} className="space-y-3">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <Avatar src={review.user?.avatarUrl} name={review.user?.name || 'User'} size="sm" />
                                                <div>
                                                    <p className="text-xs font-bold dark:text-white">{review.user?.name}</p>
                                                    <div className="flex text-yellow-400 text-[8px] gap-0.5">
                                                        {[...Array(5)].map((_, i) => (
                                                            <i key={i} className={`fa-solid fa-star ${i >= review.rating ? 'text-gray-200 dark:text-gray-700' : ''}`}></i>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                            <span className="text-[10px] text-gray-400">{new Date(review.createdAt).toLocaleDateString()}</span>
                                        </div>
                                        <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed pl-11">
                                            {review.comment}
                                        </p>
                                        {review.images && review.images.length > 0 && (
                                            <div className="flex gap-2 pl-11">
                                                {review.images.map((img, idx) => (
                                                    <img key={idx} src={img} className="w-16 h-16 rounded-xl object-cover border border-gray-100 dark:border-gray-800" />
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {isReviewModalOpen && vendor && (
                <ReviewModal 
                    productId={product.id} 
                    vendorId={vendor.vendorId} 
                    onClose={() => setIsReviewModalOpen(false)} 
                />
            )}
        </div>
    );
};

