        </div>
      </div>

      {/* Indefinite Scroll Trending Section - Optimized for Seamless Scrolling */}
      {trendingItems.length > 0 && (
          <div className="space-y-2">
              <div className="flex items-center gap-2 px-4">
                  <i className="fa-solid fa-fire text-accent text-[8px]"></i>
                  <h3 className="font-display font-black text-gray-900 dark:text-white text-[8px] uppercase tracking-[0.2em]">Trending</h3>
              </div>
              <div className="relative w-full overflow-hidden">
                  {/* Visual Edge Fading */}
                  <div className="absolute left-0 top-0 bottom-0 w-8 bg-gradient-to-r from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>
                  <div className="absolute right-0 top-0 bottom-0 w-8 bg-gradient-to-l from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>

                  {/* We duplicate the items once to create a perfect loop for the -50% translation */}
                  <div className="flex animate-scroll hover:pause-on-hover py-0.5 w-max gap-3">
                      {[...trendingItems, ...trendingItems].map((p, idx) => (
                          <div 
                              key={`${p.id}-${idx}`} 
                              onClick={() => navigate(`/buyer/product/${p.id}`)}
                              className="w-32 flex-shrink-0 bg-white dark:bg-darkSurface rounded-2xl shadow-soft border border-gray-50 dark:border-gray-800/50 overflow-hidden cursor-pointer group hover:-translate-y-0.5 transition-all duration-300"
                          >
                              <div className="h-24 overflow-hidden relative bg-gray-50 dark:bg-gray-900">
                                  <img src={p.images[0]} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                                  <div className="absolute top-1.5 left-1.5">
                                      <div className="bg-primary/90 text-white text-[6px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter">Live</div>
                                  </div>
                              </div>
                              <div className="p-2">
                                  <p className="text-[9px] font-bold text-gray-900 dark:text-white truncate uppercase tracking-tight mb-0.5 font-display">{p.title}</p>
