  const [selectedCat, setSelectedCat] = useState('All');
  const [sortType, setSortType] = useState<'nearby' | 'price' | 'rating'>('nearby');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
              (position) => setUserLocation({ lat: position.coords.latitude, lng: position.coords.longitude }),
              () => setUserLocation({ lat: 5.6506, lng: -0.1962 })
          );
      }
  }, []);

  const getDistanceFromLatLonInKm = (lat1: number, lon1: number, lat2: number, lon2: number) => {
      const R = 6371; 
      const dLat = (lat2 - lat1) * (Math.PI/180);
      const dLon = (lon2 - lon1) * (Math.PI/180);
      const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(lat1 * (Math.PI/180)) * Math.cos(lat2 * (Math.PI/180)) * Math.sin(dLon/2) * Math.sin(dLon/2); 
      return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))); 
  };

  const getCoordsForLocation = (locStr: string): {lat: number, lng: number} | null => {
      const clean = locStr.toLowerCase();
      if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
      const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
      if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
      return null;
  };

  const categoryList = useMemo(() => [
      { id: 'cat-all', name: 'All', icon: 'layer-group', image: '' },
      ...CATEGORIES
  ], []);

  const trendingItems = useMemo(() => {
      return products.filter(p => p.isTrending && p.status === 'approved');
  }, [products]);

  const sortedProducts = useMemo(() => {
      const approvedProducts = products.filter(p => p.status === 'approved');
      let filtered = selectedCat === 'All' ? approvedProducts : approvedProducts.filter(p => p.category === selectedCat);

      if (sortType === 'price') return [...filtered].sort((a, b) => a.price - b.price);
      if (sortType === 'rating') return [...filtered].sort((a, b) => (b.rating || 0) - (a.rating || 0));
      if (sortType === 'nearby' && userLocation) {
          return [...filtered].sort((a, b) => {
              const coordsA = getCoordsForLocation(a.location);
              const coordsB = getCoordsForLocation(b.location);
              const distA = coordsA ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsA.lat, coordsA.lng) : 999;
              const distB = coordsB ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsB.lat, coordsB.lng) : 999;
              return distA - distB;
          });
      }
      return filtered;
  }, [products, selectedCat, sortType, userLocation]);

  return (
    <div className="flex flex-col space-y-5 animate-fade-in pb-4 bg-gray-50 dark:bg-darkBg min-h-screen overflow-x-hidden">
      <div className="bg-white/90 dark:bg-darkSurface/90 backdrop-blur-xl pt-2 pb-3 px-4 sticky top-0 z-30 border-b border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="relative group" onClick={() => navigate('/buyer/search')}>
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <i className="fa-solid fa-magnifying-glass text-gray-400"></i>
            </div>
            <input readOnly placeholder="Search campus stores..." className="block w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-darkBg py-2.5 pl-10 pr-4 text-sm text-gray-900 dark:text-white cursor-pointer hover:bg-white dark:hover:bg-darkSurface transition-all" />
        </div>
      </div>

      {/* Indefinite Scroll Trending Section - Ultra-Compact & Seamless */}
      {trendingItems.length > 0 && (
          <div className="space-y-2">
              <div className="flex items-center gap-2 px-4">
                  <i className="fa-solid fa-fire text-accent text-[8px]"></i>
                  <h3 className="font-display font-black text-gray-900 dark:text-white text-[8px] uppercase tracking-[0.2em]">Trending Now</h3>
              </div>
              <div className="relative w-full overflow-hidden">
                  {/* Outer gradient masks for smooth entry/exit */}
                  <div className="absolute left-0 top-0 bottom-0 w-8 bg-gradient-to-r from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>
                  <div className="absolute right-0 top-0 bottom-0 w-8 bg-gradient-to-l from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>

                  {/* Duplicated list for infinite reset loop */}
                  <div className="flex animate-scroll hover:pause-on-hover py-0.5 w-max gap-3">
                      {[...trendingItems, ...trendingItems, ...trendingItems].map((p, idx) => (
                          <div 
                              key={`${p.id}-${idx}`} 
                              onClick={() => navigate(`/buyer/product/${p.id}`)}
                              className="w-32 flex-shrink-0 bg-white dark:bg-darkSurface rounded-2xl shadow-soft border border-gray-100 dark:border-gray-800/50 overflow-hidden cursor-pointer group hover:-translate-y-0.5 transition-all duration-300"
                          >
                              <div className="h-24 overflow-hidden relative bg-gray-50 dark:bg-gray-900">
                                  <img src={p.images[0]} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                                  <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-40"></div>
                                  <div className="absolute top-1.5 left-1.5">
                                      <div className="bg-primary/90 text-white text-[6px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter shadow-sm">Featured</div>
                                  </div>
                              </div>
                              <div className="p-2">
                                  <p className="text-[9px] font-bold text-gray-900 dark:text-white truncate uppercase tracking-tight mb-0.5 font-display">{p.title}</p>
                                  <div className="flex justify-between items-center">
                                      <p className="text-primary font-black text-[10px]">₵{p.price.toFixed(0)}</p>
                                      <i className="fa-solid fa-chevron-right text-[6px] text-gray-300 group-hover:text-primary transition-colors"></i>
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="pl-4">
        <h3 className="font-display font-bold text-gray-400 text-[10px] uppercase tracking-widest mb-3 opacity-60">Categories</h3>
        <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-2 pr-4">
            {categoryList.map(cat => (
                <div key={cat.id} className="flex flex-col items-center gap-1 cursor-pointer min-w-[72px]" onClick={() => setSelectedCat(cat.name)}>
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center transition-all overflow-hidden border-2 ${selectedCat === cat.name ? 'border-primary ring-2 ring-primary/20' : 'border-transparent bg-gray-200 dark:bg-darkSurface text-gray-500'}`}>
                        {cat.image ? <img src={cat.image} className="w-full h-full object-cover" /> : <i className={`fa-solid fa-${cat.icon} text-lg`}></i>}
                    </div>
                    <span className={`text-[10px] font-bold text-center w-full uppercase ${selectedCat === cat.name ? 'text-primary' : 'text-gray-500'}`}>{cat.name}</span>
                </div>
            ))}
        </div>
      </div>

      <div className="px-4 pb-24">
         <div className="flex justify-between items-center mb-4">
            <h3 className="font-display font-black text-gray-900 dark:text-white text-sm uppercase tracking-widest opacity-60">Campus Feed</h3>
            <div className="flex gap-1.5">
                {['nearby', 'price'].map(type => (
                    <button key={type} onClick={() => setSortType(type as any)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${sortType === type ? 'bg-primary text-white' : 'bg-white dark:bg-darkSurface text-gray-400 border border-gray-100 dark:border-gray-800'}`}>{type}</button>
                ))}
            </div>
         </div>

         {isDataLoading ? (
             <div className="grid grid-cols-2 gap-3">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                {sortedProducts.map(product => {
                    const vendor = vendors.find(v => v.vendorId === product.vendorId);
                    const isInCart = cart.some(item => item.productId === product.id);
                    const isFavorite = favorites.includes(product.id);
                    return (
                        <div key={product.id} className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 flex flex-col h-full cursor-pointer relative group" onClick={() => navigate(`/buyer/product/${product.id}`)}>
                            <div className="aspect-square relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                <img src={product.images[0]} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt={product.title} />
                                <div className="absolute top-2 left-2 bg-white/90 dark:bg-darkBg/90 px-2 py-1 rounded-lg text-[9px] font-bold text-gray-700 dark:text-gray-300">📍 {product.location}</div>

                                <button 
                                    onClick={(e) => { e.stopPropagation(); toggleFavorite(product.id); }}
                                    className={`absolute top-2 right-2 w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 transform ${isFavorite ? 'bg-red-500 text-white shadow-lg scale-100 opacity-100' : 'bg-white/80 dark:bg-darkSurface/80 text-gray-400 hover:text-red-500 scale-90 opacity-0 group-hover:scale-100 group-hover:opacity-100'}`}
                                >
                                    <i className={`fa-${isFavorite ? 'solid' : 'regular'} fa-heart text-[10px]`}></i>
                                </button>

                                {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><span className="bg-black text-white text-[8px] px-2 py-1 rounded font-bold uppercase">Sold Out</span></div>}
                            </div>
                            <div className="p-3 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2">{product.title}</h3>
                                    <p className="text-[10px] text-gray-400 mt-1">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <span className="text-sm font-extrabold text-gray-900 dark:text-white">₵{product.price}</span>
                                    <button 
                                        className={`w-7 h-7 rounded-full flex items-center justify-center text-white transition-all ${isInCart ? 'bg-green-500 scale-110' : 'bg-black dark:bg-white dark:text-black active:scale-90'}`}
                                        onClick={(e) => { e.stopPropagation(); if (product.stock > 0) isInCart ? removeFromCart(product.id) : addToCart(product); }}
                                    >
                                        <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-[10px]`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product, Review } from '../types';

export const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
    existingReview?: Review;
}> = ({ productId, vendorId, onClose, existingReview }) => {
    const { submitReview, currentUser, uploadFile } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [images, setImages] = useState<string[]>(existingReview?.images || []);
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setUploading(true);
            const files = Array.from(e.target.files);
            const uploaded: string[] = [];
            for (const file of files) {
                const url = await uploadFile(file, 'review-images');
                if (url) uploaded.push(url);
            }
            setImages(prev => [...prev, ...uploaded]);
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            id: existingReview?.id, productId, vendorId, userId: currentUser.id,
            rating, comment, images
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-lg rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white">{existingReview ? 'Edit Review' : 'Write a Review'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} type="button" onClick={() => setRating(star)} className={`text-3xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-200 dark:text-gray-700'}`}>
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>
                    <textarea
                        className="w-full rounded-2xl bg-gray-50 dark:bg-gray-900 p-4 text-sm h-32 outline-none border border-gray-100 dark:border-gray-800 dark:text-white"
                        placeholder="Tell us what you think..."
                        value={comment}
                        onChange={e => setComment(e.target.value)}
                        required
                    />
                    <div className="flex flex-wrap gap-2">
                        {images.map((img, i) => (
                            <img key={i} src={img} className="w-16 h-16 rounded-lg object-cover" />
                        ))}
                        {images.length < 3 && (
                            <button type="button" onClick={() => fileRef.current?.click()} className="w-16 h-16 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center text-gray-400">
                                {uploading ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-camera"></i>}
                            </button>
                        )}
                    </div>
                    <input type="file" ref={fileRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
                    <Button fullWidth size="lg" type="submit" disabled={submitting || uploading}>{submitting ? 'Posting...' : 'Submit Review'}</Button>
                </form>
            </Card>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast, reviews, orders, currentUser } = useApp();
    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);
    const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
    const [quantity, setQuantity] = useState(1);
    const [activeImg, setActiveImg] = useState(0);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleShare = async () => {
        // Build the clean URL: use window.location.href but strip extra search params if needed
        // For HashRouter, window.location.origin + window.location.hash is the most reliable external link
        const cleanUrl = `${window.location.origin}${window.location.pathname}${window.location.hash}`;

        const shareData = {
            title: `LYNQED: ${product.title}`,
            text: `Check out ${product.title} on LYNQED! It's only ₵${product.price}.`,
            url: cleanUrl
        };

        const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

        if (navigator.share && isMobile) {
            try {
                await navigator.share(shareData);
            } catch (err) {
                if ((err as Error).name !== 'AbortError') {
                    copyToClipboard(cleanUrl);
                }
            }
        } else {
            copyToClipboard(cleanUrl);
        }
    };

    const copyToClipboard = async (url: string) => {
        try {
            // Priority 1: Async Clipboard API
            if (navigator.clipboard && window.isSecureContext) {
                await navigator.clipboard.writeText(url);
                showToast("Product link copied successfully!", "success");
            } else {
                // Priority 2: Standard Fallback (essential for many dev/sandbox environments)
                const textArea = document.createElement("textarea");
                textArea.value = url;
                textArea.style.position = "fixed"; // prevent scrolling to bottom
                textArea.style.left = "-9999px";
                textArea.style.top = "0";
                document.body.appendChild(textArea);
                textArea.focus();
                textArea.select();
                const successful = document.execCommand('copy');
                document.body.removeChild(textArea);
                if (successful) {
                    showToast("Product link copied successfully!", "success");
                } else {
                    throw new Error('Fallback failed');
                }
            }
        } catch (err) {
            showToast("Failed to copy. Try copying the browser URL manually.", "error");
        }
    };

    const handleAddToCart = () => {
        if (product.stock === 0) return;
        addToCart(product, quantity);
    };

    const handleBuyNow = () => {
        if (product.stock === 0) return;
        if (!isInCart) addToCart(product, quantity);
        navigate('/buyer/checkout');
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            {/* Action Bar */}
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-100 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center justify-between">
                <button onClick={() => navigate(-1)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-300 transition-colors">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="flex gap-2">
                    <button 
                        onClick={handleShare} 
                        className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-50 dark:bg-gray-800 text-gray-500 hover:text-primary transition-all shadow-sm active:scale-90"
                        title="Share Product"
                    >
                        <i className="fa-solid fa-share-nodes text-sm"></i>
                    </button>
                    <button 
                        onClick={() => toggleFavorite(product.id)} 
                        className={`w-10 h-10 flex items-center justify-center rounded-full transition-all shadow-sm ${isFav ? 'bg-red-500 text-white' : 'bg-gray-50 dark:bg-gray-800 text-gray-400'}`}
                        title={isFav ? "Remove from Wishlist" : "Add to Wishlist"}
                    >
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart text-sm`}></i>
                    </button>
                </div>
            </div>

            <div className="max-w-4xl mx-auto">
                {/* Images */}
                <div className="relative aspect-square sm:aspect-video overflow-hidden bg-gray-200 dark:bg-gray-900 sm:rounded-b-3xl">
                    <img 
                        src={product.images[activeImg]} 
                        className="w-full h-full object-cover" 
                        alt={product.title} 
                    />
                    {product.images.length > 1 && (
                        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-2">
                            {product.images.map((_, i) => (
                                <button 
                                    key={i} 
                                    onClick={() => setActiveImg(i)}
                                    className={`h-1.5 rounded-full transition-all ${activeImg === i ? 'w-6 bg-white' : 'w-2 bg-white/50'}`}
                                />
                            ))}
                        </div>
                    )}
                    {product.stock === 0 && (
