            <input readOnly placeholder="Search campus stores..." className="block w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-darkBg py-2.5 pl-10 pr-4 text-sm text-gray-900 dark:text-white cursor-pointer hover:bg-white dark:hover:bg-darkSurface transition-all" />
        </div>
      </div>

      {/* Indefinite Scroll Trending Section - Ultra-Compact & Seamless */}
      {trendingItems.length > 0 && (
          <div className="space-y-2">
              <div className="flex items-center gap-2 px-4">
                  <i className="fa-solid fa-fire text-accent text-[8px]"></i>
                  <h3 className="font-display font-black text-gray-900 dark:text-white text-[8px] uppercase tracking-[0.2em]">Trending Now</h3>
              </div>
              <div className="relative w-full overflow-hidden">
                  {/* Visual Edge Fading */}
                  <div className="absolute left-0 top-0 bottom-0 w-12 bg-gradient-to-r from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>
                  <div className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-gray-50 dark:from-darkBg to-transparent z-10 pointer-events-none"></div>

