import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Avatar, Spinner } from '../components/UI';
import { Product, Review } from '../types';

export const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
    existingReview?: Review;
}> = ({ productId, vendorId, onClose, existingReview }) => {
    const { submitReview, currentUser, uploadFile } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [images, setImages] = useState<string[]>(existingReview?.images || []);
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setUploading(true);
            const files = Array.from(e.target.files);
            const uploaded: string[] = [];
            for (const file of files) {
                const url = await uploadFile(file, 'review-images');
                if (url) uploaded.push(url);
            }
            setImages(prev => [...prev, ...uploaded]);
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            id: existingReview?.id, productId, vendorId, userId: currentUser.id,
            rating, comment, images
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-w-lg rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white">{existingReview ? 'Edit Review' : 'Write a Review'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} type="button" onClick={() => setRating(star)} className={`text-3xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-200 dark:text-gray-700'}`}>
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>
                    <textarea
                        className="w-full rounded-2xl bg-gray-50 dark:bg-gray-900 p-4 text-sm h-32 outline-none border border-gray-100 dark:border-gray-800 dark:text-white"
                        placeholder="Tell us what you think..."
                        value={comment}
                        onChange={e => setComment(e.target.value)}
                        required
                    />
                    <div className="flex flex-wrap gap-2">
                        {images.map((img, i) => (
                            <img key={i} src={img} className="w-16 h-16 rounded-lg object-cover" />
                        ))}
                        {images.length < 3 && (
                            <button type="button" onClick={() => fileRef.current?.click()} className="w-16 h-16 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center text-gray-400">
                                {uploading ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-camera"></i>}
                            </button>
                        )}
                    </div>
                    <input type="file" ref={fileRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
                    <Button fullWidth size="lg" type="submit" disabled={submitting || uploading}>{submitting ? 'Posting...' : 'Submit Review'}</Button>
                </form>
            </Card>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, vendors, favorites, toggleFavorite, showToast, reviews, currentUser } = useApp();

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    const scrollRef = useRef<HTMLDivElement>(null);
    const zoomScrollRef = useRef<HTMLDivElement>(null);

    const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
    const [quantity, setQuantity] = useState(1);
    const [activeImg, setActiveImg] = useState(0);
    const [isZoomed, setIsZoomed] = useState(false);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    const relatedProducts = useMemo(() => {
        return products.filter(p => p.category === product?.category && p.id !== id && p.status === 'approved').slice(0, 6);
    }, [products, product?.category, id]);

    const suggestedProducts = useMemo(() => {
        return products.filter(p => p.id !== id && p.status === 'approved').sort(() => 0.5 - Math.random()).slice(0, 6);
    }, [products, id]);

    const handleScroll = (ref: React.RefObject<HTMLDivElement | null>) => {
        if (ref.current) {
            const index = Math.round(ref.current.scrollLeft / ref.current.clientWidth);
            if (index !== activeImg) setActiveImg(index);
        }
    };

    const scrollToImage = (index: number, ref: React.RefObject<HTMLDivElement | null>) => {
        if (ref.current) {
            ref.current.scrollTo({
                left: index * ref.current.clientWidth,
                behavior: 'smooth'
            });
            setActiveImg(index);
        }
    };

    // Synchronize zoom scroll when opening
    useEffect(() => {
        if (isZoomed && zoomScrollRef.current) {
            setTimeout(() => {
                if (zoomScrollRef.current) {
                    zoomScrollRef.current.scrollTo({
                        left: activeImg * zoomScrollRef.current.clientWidth,
                        behavior: 'auto'
                    });
                }
            }, 50);
        }
    }, [isZoomed]);

    // Synchronize main scroll when closing zoom
    useEffect(() => {
        if (!isZoomed && scrollRef.current) {
            scrollRef.current.scrollTo({
                left: activeImg * scrollRef.current.clientWidth,
                behavior: 'auto'
            });
        }
    }, [isZoomed]);

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleShare = async () => {
        const baseUrl = "https://lynqed.vercel.app";
        const cleanUrl = `${baseUrl}/#/buyer/product/${product.id}`;
        const shareData = {
            title: `LYNQED: ${product.title}`,
            text: `Hey! Check out ${product.title} on LYNQED! It's just ₵${product.price.toFixed(2)}.`,
            url: cleanUrl
        };
        if (navigator.share && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
            try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') copyToClipboard(cleanUrl); }
        } else { copyToClipboard(cleanUrl); }
    };

    const copyToClipboard = async (url: string) => {
        try {
            if (navigator.clipboard && window.isSecureContext) {
                await navigator.clipboard.writeText(url);
                showToast("Link copied!", "success");
            } else {
                const textArea = document.createElement("textarea");
                textArea.value = url;
                textArea.style.position = "fixed";
                textArea.style.left = "-9999px";
                document.body.appendChild(textArea);
                textArea.focus();
                textArea.select();
                document.execCommand('copy');
                document.body.removeChild(textArea);
                showToast("Link copied!", "success");
            }
        } catch (err) { showToast("Failed to copy", "error"); }
    };

    const ProductRibbon = ({ title, items }: { title: string, items: Product[] }) => {
        if (items.length === 0) return null;
        return (
            <div className="space-y-3">
                <h3 className="font-display font-black text-gray-900 dark:text-white text-[10px] uppercase tracking-[0.15em] opacity-50 ml-1">{title}</h3>
                <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-2 snap-x">
                    {items.map(p => (
                        <div 
                            key={p.id} 
                            onClick={() => { navigate(`/buyer/product/${p.id}`); window.scrollTo(0, 0); }}
                            className="w-36 flex-shrink-0 bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-sm border border-gray-100 dark:border-gray-800 transition-all active:scale-95 snap-start"
