                            <div className="aspect-square bg-gray-50 dark:bg-gray-900">
                                <img src={p.images[0]} className="w-full h-full object-cover" alt="" />
                            </div>
                            <div className="p-2.5">
                                <h4 className="text-[10px] font-bold text-gray-800 dark:text-white line-clamp-1 leading-tight">{p.title}</h4>
                                <p className="text-primary font-black text-xs mt-1">₵{p.price}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in scroll-smooth">
            {/* Fullscreen Swipable Zoom Overlay */}
            {isZoomed && (
                <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-md flex flex-col animate-fade-in">
                    <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-center z-[210]">
                        <span className="text-white/60 text-[10px] font-black uppercase tracking-widest bg-white/10 px-3 py-1.5 rounded-full">{activeImg + 1} / {product.images.length}</span>
                        <button 
                            onClick={() => setIsZoomed(false)}
                            className="w-10 h-10 flex items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20 transition-all"
                        >
                            <i className="fa-solid fa-xmark"></i>
                        </button>
                    </div>

                    <div 
                        ref={zoomScrollRef}
                        onScroll={() => handleScroll(zoomScrollRef)}
                        className="flex-1 flex overflow-x-auto snap-x snap-mandatory hide-scrollbar"
                    >
                        {product.images.map((img, i) => (
                            <div key={i} className="flex-shrink-0 w-full h-full snap-center flex items-center justify-center p-4">
                                <img 
                                    src={img} 
                                    className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl" 
                                    alt={`Product view ${i + 1}`}
                                />
                            </div>
                        ))}
                    </div>

                    <div className="p-8 flex justify-center gap-3 overflow-x-auto hide-scrollbar bg-gradient-to-t from-black/50 to-transparent">
                        {product.images.map((img, i) => (
                            <button 
                                key={i}
                                onClick={() => scrollToImage(i, zoomScrollRef)}
                                className={`w-14 h-14 rounded-xl overflow-hidden border-2 transition-all flex-shrink-0 ${activeImg === i ? 'border-primary scale-110 shadow-glow' : 'border-white/20 opacity-40'}`}
                            >
                                <img src={img} className="w-full h-full object-cover" alt="" />
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Action Bar - Ultra Compact */}
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-100 dark:border-gray-800 sticky top-0 z-30 px-3 py-2 flex items-center justify-between">
                <button onClick={() => navigate(-1)} className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300">
                    <i className="fa-solid fa-arrow-left text-xs"></i>
