export const Checkout: React.FC = () => {
    const { cart, placeOrder } = useApp();
    const navigate = useNavigate();
    const [option, setOption] = useState<'delivery' | 'pickup'>('delivery');
    const [processing, setProcessing] = useState(false);

    const handleCheckout = async () => {
        setProcessing(true);
        await placeOrder(option, option === 'delivery' ? 5 : 0);
        setProcessing(false);
        navigate('/buyer/orders');
    };

    if (cart.length === 0) return <Navigate to="/buyer/dashboard" />;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24">
            <div className="bg-white dark:bg-darkSurface p-4 shadow-sm flex items-center gap-4 sticky top-0 z-30">
                <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <h1 className="text-xl font-bold dark:text-white">Checkout</h1>
            </div>
            <div className="p-6 max-w-lg mx-auto space-y-8">
                <div>
                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Delivery Option</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <button 
                            onClick={() => setOption('delivery')}
                            className={`p-6 rounded-3xl border-2 flex flex-col items-center gap-2 transition-all ${option === 'delivery' ? 'border-primary bg-primary/5 text-primary' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
                        >
                            <i className="fa-solid fa-truck-fast text-2xl"></i>
                            <span className="font-bold text-sm">Delivery</span>
                            <span className="text-[10px] opacity-60">+₵5.00</span>
                        </button>
                        <button 
                            onClick={() => setOption('pickup')}
                            className={`p-6 rounded-3xl border-2 flex flex-col items-center gap-2 transition-all ${option === 'pickup' ? 'border-primary bg-primary/5 text-primary' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
                        >
                            <i className="fa-solid fa-hand-holding-box text-2xl"></i>
                            <span className="font-bold text-sm">Pickup</span>
                            <span className="text-[10px] opacity-60">Free</span>
                        </button>
                    </div>
                </div>

                <div className="space-y-4">
                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Order Summary</h3>
                    {cart.map(i => (
                        <div key={i.productId} className="flex justify-between text-sm">
                            <span className="text-gray-500">{i.quantity}x {i.product.title}</span>
                            <span className="font-bold dark:text-white">₵{(i.product.price * i.quantity).toFixed(2)}</span>
                        </div>
                    ))}
                    <div className="pt-4 border-t border-gray-100 dark:border-gray-800 flex justify-between items-center">
                        <span className="font-bold text-lg dark:text-white">Grand Total</span>
                        <span className="text-2xl font-black text-primary">₵{(cart.reduce((a, c) => a + c.product.price * c.quantity, 0) + (option === 'delivery' ? 5 : 0)).toFixed(2)}</span>
                    </div>
                </div>

                <Button fullWidth size="lg" onClick={handleCheckout} disabled={processing}>
                    {processing ? "Processing..." : "Place Order"}
                </Button>
            </div>
        </div>
    );
};

