                        <i className="fa-solid fa-plus text-white text-[10px]"></i>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* Categories Section */}
      <div className="pl-4">
        <h3 className="font-display font-bold text-gray-900 dark:text-white text-lg mb-4">Categories</h3>
        <div className="flex gap-4 overflow-x-auto hide-scrollbar pb-2 pr-4">
            {categoryList.map(cat => (
                <div key={cat.id} className="flex flex-col items-center gap-2 cursor-pointer min-w-[80px] group" onClick={() => setSelectedCat(cat.name)}>
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center transition-all overflow-hidden border-2 ${selectedCat === cat.name ? 'border-primary ring-4 ring-primary/10 scale-105' : 'border-transparent bg-white dark:bg-darkSurface text-gray-500 shadow-sm group-hover:scale-105'}`}>
                        {cat.image ? <img src={cat.image} className="w-full h-full object-cover" /> : <i className={`fa-solid fa-${cat.icon} text-xl`}></i>}
                    </div>
                    <span className={`text-[11px] font-bold text-center w-full transition-colors ${selectedCat === cat.name ? 'text-primary' : 'text-gray-500'}`}>{cat.name}</span>
                </div>
