import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Avatar, Spinner, Input } from '../components/UI';
import { Product, Review, Vendor } from '../types';
import { INITIAL_LOCATION_CACHE } from '../constants';

// --- Review Modal ---
export const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
    existingReview?: Review;
}> = ({ productId, vendorId, onClose, existingReview }) => {
    const { submitReview, currentUser, uploadFile } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [images, setImages] = useState<string[]>(existingReview?.images || []);
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setUploading(true);
            const files = Array.from(e.target.files);
            const uploaded: string[] = [];
            for (const file of files) {
                const url = await uploadFile(file, 'review-images');
                if (url) uploaded.push(url);
            }
            setImages(prev => [...prev, ...uploaded]);
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            id: existingReview?.id, productId, vendorId, userId: currentUser.id,
            rating, comment, images
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-w-lg rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white">{existingReview ? 'Edit Review' : 'Write a Review'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} type="button" onClick={() => setRating(star)} className={`text-3xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-200 dark:text-gray-700'}`}>
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>
                    <textarea
                        className="w-full rounded-2xl bg-gray-50 dark:bg-gray-900 p-4 text-sm h-32 outline-none border border-gray-100 dark:border-gray-800 dark:text-white"
                        placeholder="Tell us what you think..."
                        value={comment}
                        onChange={e => setComment(e.target.value)}
                        required
                    />
                    <div className="flex flex-wrap gap-2">
                        {images.map((img, i) => (
                            <img key={i} src={img} className="w-16 h-16 rounded-lg object-cover" alt="Review" />
                        ))}
                        {images.length < 3 && (
                            <button type="button" onClick={() => fileRef.current?.click()} className="w-16 h-16 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center text-gray-400 hover:border-primary hover:text-primary transition-colors">
                                {uploading ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-camera"></i>}
                            </button>
                        )}
                    </div>
                    <input type="file" ref={fileRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
                    <Button fullWidth size="lg" type="submit" disabled={submitting || uploading}>{submitting ? 'Posting...' : 'Submit Review'}</Button>
                </form>
            </Card>
        </div>
    );
};

// --- Store Page ---
export const StorePage: React.FC = () => {
    const { vendorId } = useParams();
    const navigate = useNavigate();
    const { vendors, products, reviews, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const storeProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');
    const storeReviews = reviews.filter(r => r.vendorId === vendorId);

    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstance = useRef<any>(null);

    useEffect(() => {
        if (!vendor || !mapRef.current || !window.L || mapInstance.current) return;

        const coords = INITIAL_LOCATION_CACHE[vendor.location.toLowerCase()] || [5.6506, -0.1962];

        const map = window.L.map(mapRef.current, {
            zoomControl: false,
            attributionControl: false,
            dragging: false,
            scrollWheelZoom: false,
            touchZoom: false,
            doubleClickZoom: false
        }).setView(coords, 16);

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        window.L.marker(coords, {
            icon: window.L.divIcon({
                className: 'custom-map-pin',
                html: `<div class="w-10 h-10 bg-primary rounded-full border-4 border-white shadow-glow flex items-center justify-center text-white"><i class="fa-solid fa-store text-sm"></i></div>`,
                iconSize: [40, 40],
                iconAnchor: [20, 40]
            })
        }).addTo(map);

        mapInstance.current = map;

        return () => {
            if (mapInstance.current) {
                mapInstance.current.remove();
                mapInstance.current = null;
            }
        };
    }, [vendor]);

    if (!vendor) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const handleShare = () => {
        const url = window.location.href;
        navigator.clipboard.writeText(url);
        showToast("Store link copied!", "success");
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            {/* Header with Map Background */}
            <div className="relative h-[320px] w-full overflow-hidden">
                <div ref={mapRef} className="absolute inset-0 z-0 h-full w-full" />
                <div className="absolute inset-0 bg-gradient-to-t from-gray-50 via-gray-50/20 dark:from-darkBg dark:via-darkBg/20 to-transparent z-10" />

                <button 
                    onClick={() => navigate(-1)}
                    className="absolute top-6 left-6 z-20 w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-lg flex items-center justify-center text-gray-600 dark:text-white backdrop-blur-md active:scale-90 transition-all"
                >
                    <i className="fa-solid fa-arrow-left"></i>
                </button>

                <div className="absolute bottom-0 left-0 right-0 z-20 px-6 pb-6">
                    <div className="flex items-end gap-5">
                        <div className="relative">
                            <Avatar 
                                src={vendor.storeAvatarUrl} 
                                name={vendor.storeName} 
                                size="xl" 
                                className="border-4 border-white dark:border-darkSurface shadow-2xl rounded-[2rem]" 
                            />
                            <div className="absolute -bottom-1 -right-1 bg-green-500 w-6 h-6 rounded-full border-4 border-white dark:border-darkSurface flex items-center justify-center shadow-sm">
                                <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></div>
                            </div>
                        </div>
                        <div className="flex-1 pb-1">
                            <h1 className="text-3xl font-display font-black text-gray-900 dark:text-white leading-none tracking-tight">{vendor.storeName}</h1>
                            <div className="flex items-center gap-3 mt-3">
                                <Badge color="violet" className="px-2 py-0.5 text-[9px]">Verified Merchant</Badge>
                                <div className="flex items-center gap-1.5 text-xs font-bold text-gray-500 dark:text-gray-400">
                                    <i className="fa-solid fa-star text-yellow-400"></i>
                                    {vendor.rating.toFixed(1)} ({storeReviews.length})
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="px-6 mt-8 space-y-8 max-w-5xl mx-auto">
                {/* Store Actions */}
                <div className="flex gap-3">
                    <Button fullWidth icon="phone" onClick={() => window.open(`tel:${vendor.contactPhone}`)}>Call Shop</Button>
                    <Button fullWidth variant="secondary" icon="share-nodes" onClick={handleShare}>Share</Button>
                </div>

                {/* About Section */}
                <div>
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">About the Shop</h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-medium bg-white dark:bg-darkSurface p-5 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm">
                        {vendor.storeDescription || "A premier vendor providing quality goods to the campus community."}
                        <span className="block mt-4 text-xs font-bold text-primary flex items-center gap-2">
                            <i className="fa-solid fa-location-dot"></i>
                            Find us at: {vendor.location}
                        </span>
                    </p>
                </div>

                {/* Products Grid */}
                <div>
                    <div className="flex justify-between items-center mb-5 ml-1">
                        <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Store Products</h3>
                        <span className="text-[10px] font-bold text-primary">{storeProducts.length} Items</span>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                        {storeProducts.length === 0 ? (
                            <div className="col-span-full py-20 text-center opacity-30">
                                <i className="fa-solid fa-box-open text-4xl mb-3"></i>
                                <p className="text-sm font-bold">No products listed yet.</p>
                            </div>
                        ) : (
                            storeProducts.map(product => (
                                <Card 
                                    key={product.id} 
                                    className="p-0 overflow-hidden group border-gray-100 dark:border-gray-800"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-square relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                        <img src={product.images[0]} alt={product.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                    </div>
                                    <div className="p-3">
                                        <h4 className="text-xs font-bold text-gray-900 dark:text-white line-clamp-1">{product.title}</h4>
                                        <div className="flex justify-between items-center mt-2">
                                            <span className="text-xs font-black text-primary">₵{product.price}</span>
                                            <i className="fa-solid fa-chevron-right text-[8px] text-gray-300"></i>
                                        </div>
                                    </div>
                                </Card>
                            ))
                        )}
                    </div>
                </div>

                {/* Reviews Section */}
                <div className="pb-10">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-5 ml-1">Customer Reviews</h3>
                    {storeReviews.length === 0 ? (
                        <p className="text-center py-10 text-gray-400 text-xs italic font-medium">Be the first to leave a review!</p>
                    ) : (
                        <div className="space-y-4">
                            {storeReviews.map(review => (
                                <div key={review.id} className="bg-white dark:bg-darkSurface p-5 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm">
                                    <div className="flex justify-between items-start mb-3">
                                        <div className="flex items-center gap-3">
                                            <Avatar src={review.user?.avatarUrl} name={review.user?.name || "User"} size="sm" />
                                            <div>
                                                <p className="text-xs font-bold text-gray-900 dark:text-white">{review.user?.name}</p>
                                                <div className="flex text-[8px] text-yellow-400 mt-0.5">
                                                    {[...Array(5)].map((_, i) => <i key={i} className={`fa-solid fa-star ${i < review.rating ? '' : 'text-gray-200 dark:text-gray-700'}`}></i>)}
                                                </div>
                                            </div>
                                        </div>
                                        <span className="text-[10px] font-bold text-gray-400 uppercase">{new Date(review.createdAt).toLocaleDateString()}</span>
                                    </div>
                                    <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed">{review.comment}</p>
                                    {review.images && review.images.length > 0 && (
                                        <div className="flex gap-2 mt-4">
                                            {review.images.map((img, i) => (
                                                <img key={i} src={img} className="w-16 h-16 rounded-xl object-cover" alt="Review detail" />
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

// --- Product Detail ---
export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, vendors, favorites, toggleFavorite, showToast, reviews } = useApp();

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    const scrollRef = useRef<HTMLDivElement>(null);
    const [activeImg, setActiveImg] = useState(0);
    const [quantity, setQuantity] = useState(1);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleAddToCart = () => {
        addToCart(product, quantity);
    };

    const handleShare = () => {
        navigator.clipboard.writeText(window.location.href);
        showToast("Product link copied!", "success");
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in max-w-5xl mx-auto">
            <div className="relative">
                {/* Product Images Scroll */}
                <div 
                    ref={scrollRef}
                    onScroll={() => {
                        if (scrollRef.current) {
                            const index = Math.round(scrollRef.current.scrollLeft / scrollRef.current.clientWidth);
                            setActiveImg(index);
                        }
                    }}
                    className="aspect-[4/5] sm:aspect-video w-full flex overflow-x-auto snap-x snap-mandatory hide-scrollbar bg-gray-200 dark:bg-gray-900"
                >
                    {product.images.map((img, i) => (
                        <div key={i} className="w-full flex-shrink-0 snap-center">
                            <img src={img} className="w-full h-full object-cover" alt={product.title} />
                        </div>
                    ))}
                </div>

                {/* Back & Share Buttons */}
                <div className="absolute top-6 left-6 right-6 flex justify-between z-10">
                    <button 
                        onClick={() => navigate(-1)}
                        className="w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-lg flex items-center justify-center text-gray-600 dark:text-white backdrop-blur-md active:scale-90 transition-all"
                    >
                        <i className="fa-solid fa-arrow-left"></i>
                    </button>
                    <div className="flex gap-3">
                        <button 
                            onClick={handleShare}
                            className="w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-lg flex items-center justify-center text-gray-600 dark:text-white backdrop-blur-md active:scale-90 transition-all"
                        >
                            <i className="fa-solid fa-share-nodes"></i>
                        </button>
                        <button 
                            onClick={() => toggleFavorite(product.id)}
                            className={`w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-lg flex items-center justify-center backdrop-blur-md active:scale-90 transition-all ${isFav ? 'text-red-500' : 'text-gray-600 dark:text-white'}`}
                        >
                            <i className={`fa-${isFav ? 'solid' : 'regular'} fa-heart`}></i>
                        </button>
                    </div>
                </div>

                {/* Dots Indicator */}
                {product.images.length > 1 && (
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                        {product.images.map((_, i) => (
                            <div key={i} className={`h-1.5 rounded-full transition-all duration-300 ${i === activeImg ? 'w-6 bg-primary' : 'w-1.5 bg-white/50'}`}></div>
                        ))}
                    </div>
                )}
            </div>

            <div className="px-6 py-8 space-y-8 bg-white dark:bg-darkSurface rounded-t-[3rem] -mt-10 relative z-20 shadow-up">
                {/* Header Info */}
                <div className="space-y-4">
                    <div className="flex justify-between items-start">
                        <h1 className="text-2xl font-display font-black text-gray-900 dark:text-white leading-tight flex-1 mr-4">{product.title}</h1>
                        <Badge color="violet" className="font-black text-[10px] tracking-widest">{product.category}</Badge>
                    </div>
                    <div className="flex items-center gap-4">
                        <span className="text-3xl font-black text-primary">₵{product.price}</span>
                        <div className="flex items-center gap-1.5 text-xs font-bold text-gray-400">
                            <i className="fa-solid fa-star text-yellow-400"></i>
                            {product.rating?.toFixed(1) || "5.0"} ({productReviews.length} reviews)
                        </div>
                    </div>
                </div>

                {/* Vendor Info Card */}
                <Card 
                    className="p-4 border-gray-100 dark:border-gray-800 hover:border-primary/20 bg-gray-50/50 dark:bg-darkBg/50 group"
                    onClick={() => navigate(`/store/${product.vendorId}`)}
                >
                    <div className="flex items-center gap-4">
                        <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || "Vendor"} size="lg" className="rounded-2xl" />
                        <div className="flex-1">
                            <div className="flex items-center justify-between">
                                <h3 className="font-bold text-gray-900 dark:text-white font-display text-sm">{vendor?.storeName}</h3>
                                <Badge color="violet" className="text-[8px] h-fit">Verified</Badge>
                            </div>
                            <p className="text-[10px] font-bold text-gray-400 mt-1 uppercase tracking-tighter">📍 {vendor?.location}</p>
                        </div>
                        <i className="fa-solid fa-chevron-right text-gray-300 group-hover:text-primary transition-all"></i>
                    </div>
                </Card>

                {/* Description */}
                <div>
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">Description</h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-medium">
                        {product.description}
                    </p>
                </div>

                {/* Quantity Selector & Action Bar */}
                <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 dark:bg-darkSurface/95 backdrop-blur-xl border-t border-gray-100 dark:border-gray-800 z-50 flex gap-4 max-w-5xl mx-auto">
                    <div className="flex items-center gap-4 bg-gray-50 dark:bg-darkBg p-2 rounded-2xl border border-gray-100 dark:border-gray-800">
                        <button 
                            onClick={() => setQuantity(q => Math.max(1, q - 1))}
                            className="w-10 h-10 rounded-xl bg-white dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all"
                        >
                            <i className="fa-solid fa-minus text-xs"></i>
                        </button>
                        <span className="font-black text-lg w-6 text-center dark:text-white">{quantity}</span>
                        <button 
                            onClick={() => setQuantity(q => Math.min(product.stock, q + 1))}
                            className="w-10 h-10 rounded-xl bg-white dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all"
                        >
                            <i className="fa-solid fa-plus text-xs"></i>
                        </button>
                    </div>
                    <Button 
                        fullWidth 
                        size="lg" 
                        onClick={handleAddToCart}
                        disabled={product.stock === 0}
                        className="shadow-xl shadow-primary/30 h-14 font-black"
                    >
                        {product.stock === 0 ? 'Out of Stock' : isInCart ? 'Add More' : 'Add to Cart'}
                    </Button>
                </div>
            </div>
        </div>
    );
};

// --- Cart Component ---
export const Cart: React.FC = () => {
    const { cart, removeFromCart, updateCartQuantity, clearCart } = useApp();
    const navigate = useNavigate();

    const subtotal = cart.reduce((acc, item) => acc + (item.product.price * item.quantity), 0);
    const isEmpty = cart.length === 0;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in max-w-5xl mx-auto">
            <div className="bg-white dark:bg-darkSurface p-4 shadow-sm sticky top-0 z-30 flex items-center justify-between border-b border-gray-100 dark:border-gray-800">
                <div className="flex items-center gap-3">
                    <button onClick={() => navigate(-1)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 dark:text-white transition-colors"><i className="fa-solid fa-arrow-left"></i></button>
                    <h1 className="text-xl font-bold font-display dark:text-white">Your Cart</h1>
                </div>
                {!isEmpty && (
                    <button onClick={clearCart} className="text-[10px] font-black uppercase text-red-500 hover:underline">Clear All</button>
                )}
            </div>

            <div className="p-4 space-y-4">
                {isEmpty ? (
                    <div className="text-center py-20 animate-fade-in">
                        <div className="w-24 h-24 bg-gray-100 dark:bg-darkSurface rounded-full flex items-center justify-center mx-auto mb-6 text-gray-300 dark:text-gray-700">
                            <i className="fa-solid fa-cart-shopping text-4xl"></i>
                        </div>
                        <h2 className="text-xl font-bold dark:text-white mb-2">Cart is empty</h2>
                        <p className="text-gray-500 dark:text-gray-400 mb-8 max-w-xs mx-auto text-sm">Looks like you haven't added anything to your cart yet.</p>
                        <Button onClick={() => navigate('/buyer/dashboard')} icon="bag-shopping">Start Shopping</Button>
                    </div>
                ) : (
                    cart.map(item => (
                        <Card key={item.productId} className="p-3 flex gap-4 animate-slide-up border-gray-100 dark:border-gray-800">
                            <div className="w-20 h-20 rounded-2xl overflow-hidden flex-shrink-0 bg-gray-100 dark:bg-gray-900">
                                <img src={item.product.images[0]} className="w-full h-full object-cover" alt={item.product.title} />
                            </div>
                            <div className="flex-1 min-w-0 flex flex-col justify-between py-1">
                                <div className="flex justify-between items-start">
                                    <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-1">{item.product.title}</h4>
                                    <button onClick={() => removeFromCart(item.productId)} className="text-gray-300 hover:text-red-500"><i className="fa-solid fa-trash-can text-xs"></i></button>
                                </div>
                                <div className="flex justify-between items-center mt-2">
                                    <span className="font-black text-primary">₵{item.product.price}</span>
                                    <div className="flex items-center gap-3 bg-gray-50 dark:bg-darkBg p-1.5 rounded-xl border border-gray-100 dark:border-gray-800">
                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity - 1)} className="w-6 h-6 flex items-center justify-center text-gray-400"><i className="fa-solid fa-minus text-[10px]"></i></button>
                                        <span className="text-xs font-black dark:text-white">{item.quantity}</span>
                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity + 1)} className="w-6 h-6 flex items-center justify-center text-gray-400"><i className="fa-solid fa-plus text-[10px]"></i></button>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    ))
                )}
            </div>

            {!isEmpty && (
                <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 dark:bg-darkSurface/95 backdrop-blur-xl border-t border-gray-100 dark:border-gray-800 z-40 max-w-5xl mx-auto">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-widest">Estimated Total</span>
                        <span className="text-2xl font-black text-gray-900 dark:text-white font-display">₵{subtotal.toFixed(2)}</span>
                    </div>
                    <Button fullWidth size="lg" className="h-14 font-black text-lg shadow-xl shadow-primary/30" onClick={() => navigate('/buyer/checkout')}>Proceed to Checkout</Button>
