import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Button, Avatar } from '../components/UI';
import { INITIAL_LOCATION_CACHE } from '../constants';

// Define Leaflet on window
declare global {
    interface Window {
        L: any;
    }
}

export const SearchPage: React.FC = () => {
  const { products, vendors, refreshData } = useApp();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [isDrawerOpen, setIsDrawerOpen] = useState(true);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markersLayerRef = useRef<any>(null); 
  const routingLayerRef = useRef<any>(null);

  // Track active plot operation to prevent duplicates from overlapping async calls
  const activePlotId = useRef<number>(0);

  // Persistent coordinate cache
  const coordCache = useRef<Record<string, [number, number]>>((() => {
      try {
          const saved = localStorage.getItem('lynqed_geo_cache');
          if (saved) {
              const parsed = JSON.parse(saved);
              return { ...INITIAL_LOCATION_CACHE, ...parsed };
          }
      } catch (e) {
          console.error("Failed to load geo cache", e);
      }
      return INITIAL_LOCATION_CACHE;
  })());

  const approvedProducts = products.filter(p => 
    p.status === 'approved' && 
    (p.title.toLowerCase().includes(query.toLowerCase()) || 
     p.category.toLowerCase().includes(query.toLowerCase()))
  );

  // Robust Vendor Avatar Helper
  const getVendorAvatar = (v: any) => {
      if (v?.storeAvatarUrl && v.storeAvatarUrl.startsWith('http')) {
          return v.storeAvatarUrl;
      }
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(v?.storeName || 'Store')}&background=6366f1&color=fff&bold=true`;
  };

  // --- Helper: Smart Geocoding with Granular Fallbacks ---
  const getCoordinates = async (locationName: string): Promise<[number, number]> => {
      const cleanName = locationName.toLowerCase().trim();

      // 1. Exact Match in Extended Cache
      if (coordCache.current[cleanName]) return coordCache.current[cleanName];

      // 2. Partial Search in Cache (e.g., "Sarbah B" -> "Sarbah Annex B")
      const partialKey = Object.keys(coordCache.current).find(k => cleanName.includes(k) || k.includes(cleanName));
      if (partialKey) return coordCache.current[partialKey];

      try {
          const campusQuery = `${locationName}, University of Ghana, Legon`;
          let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(campusQuery)}`);
          let data = await response.json();

          if (!data || data.length === 0) {
              response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(locationName)}, Ghana`);
              data = await response.json();
          }

          if (data && data.length > 0) {
              const lat = parseFloat(data[0].lat);
              const lon = parseFloat(data[0].lon);
              if (!isNaN(lat) && !isNaN(lon)) {
                  const coords: [number, number] = [lat, lon];
                  coordCache.current[cleanName] = coords;
                  localStorage.setItem('lynqed_geo_cache', JSON.stringify(coordCache.current));
                  return coords;
              }
          }
      } catch (e) { 
          console.warn(`Geocoding failed for: ${locationName}`); 
      }

      // 3. Last Resort: Central Academic Area (NOT Registry)
      return [5.6515, -0.1885]; // Balme Library center
  };

  // 1. Initialize Map
  useEffect(() => {
      if (!mapContainerRef.current || mapInstanceRef.current) return;

      if (window.L) {
        const defaultCenter: [number, number] = [5.6506, -0.1962];
        const map = window.L.map(mapContainerRef.current, { 
            zoomControl: true,
            attributionControl: false,
            dragging: true,
            scrollWheelZoom: true,
            touchZoom: true
        }).setView(defaultCenter, 16); // Starting zoom 16 to see buildings

        if (map.zoomControl) {
            map.zoomControl.setPosition('topright');
        }

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        markersLayerRef.current = window.L.layerGroup().addTo(map);
        routingLayerRef.current = window.L.layerGroup().addTo(map);
        mapInstanceRef.current = map;

        setTimeout(() => map.invalidateSize(), 300);
      }

      refreshData();

      return () => {
          if (mapInstanceRef.current) {
              mapInstanceRef.current.remove();
              mapInstanceRef.current = null;
          }
      };
  }, []); 

  // 2. Plot Vendors
  useEffect(() => {
      const markersLayer = markersLayerRef.current;
      const routingLayer = routingLayerRef.current;
      const map = mapInstanceRef.current;

      if (!map || !markersLayer || !window.L) return;

      const plotId = ++activePlotId.current;

      const plotVendors = async () => {
          markersLayer.clearLayers();
          routingLayer.clearLayers();

          const activeVendors = vendors.filter(v => v.isApproved);
          const userPos: [number, number] = [5.6506, -0.1962]; 

          if (plotId !== activePlotId.current) return;

          // User Pin
          window.L.marker(userPos, { 
              icon: window.L.divIcon({
                  className: 'custom-user-pin',
                  html: `<div class="w-5 h-5 bg-primary rounded-full border-2 border-white shadow-glow pulse-ring"></div>`,
                  iconSize: [20, 20]
              }) 
          }).addTo(markersLayer);

          // Group vendors by location to calculate offsets
          const vendorsByLocation: Record<string, any[]> = {};

          for (const v of activeVendors) {
            const basePos = await getCoordinates(v.location);
            const key = `${basePos[0].toFixed(6)},${basePos[1].toFixed(6)}`;
            if (!vendorsByLocation[key]) vendorsByLocation[key] = [];
            vendorsByLocation[key].push({ ...v, basePos });
          }

          if (plotId !== activePlotId.current) return;

          // Plot grouped vendors with radial displacement
          Object.keys(vendorsByLocation).forEach((key) => {
              const group = vendorsByLocation[key];
              const numInGroup = group.length;

              group.forEach((v, index) => {
                // Displacement logic for clusters: small circle around building center
                let finalPos = [...v.basePos];
                if (numInGroup > 1) {
                    const angle = (index / numInGroup) * 2 * Math.PI;
                    const radius = 0.0002; // Approx 20 meters displacement
                    finalPos[0] += Math.cos(angle) * radius;
                    finalPos[1] += Math.sin(angle) * radius;
                }

                const isSelected = selectedProductId && products.find(p => p.id === selectedProductId)?.vendorId === v.vendorId;
                const avatarUrl = getVendorAvatar(v);

                if (isSelected) {
                    const polyline = window.L.polyline([userPos, finalPos], { 
                        color: '#6366f1', 
                        weight: 4, 
                        opacity: 0.6, 
                        dashArray: '8, 12' 
                    }).addTo(routingLayer);
                    map.fitBounds(polyline.getBounds(), { padding: [100, 100] });
                }

                const marker = window.L.marker(finalPos, { 
                    icon: window.L.divIcon({
                        className: 'custom-map-pin',
                        html: `
                            <div class="relative flex flex-col items-center group cursor-pointer ${isSelected ? 'z-50 scale-125' : ''}">
                                <!-- ALWAYS VISIBLE LOCATION LABEL -->
                                <div class="absolute -top-12 bg-gray-900 text-white text-[9px] font-black px-3 py-1.5 rounded-lg shadow-2xl border border-white/20 whitespace-nowrap uppercase tracking-widest z-50">
                                    ${v.location}
                                </div>
                                <div class="w-12 h-12 bg-white dark:bg-darkSurface rounded-2xl p-0.5 shadow-float border-2 ${isSelected ? 'border-primary ring-4 ring-primary/20' : 'border-white dark:border-gray-800'} overflow-hidden transform transition-all duration-300">
                                    <img src="${avatarUrl}" class="w-full h-full object-cover bg-gray-100 dark:bg-darkBg rounded-xl" />
                                </div>
                                <div class="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[8px] ${isSelected ? 'border-t-primary' : 'border-t-white dark:border-t-gray-800'}"></div>
                            </div>
                        `,
                        iconSize: [48, 60],
                        iconAnchor: [24, 60]
                    }),
                    zIndexOffset: isSelected ? 1000 : index // Layer them correctly
                });

                marker.bindPopup(`
                    <div class="p-2 text-center" style="min-width: 140px;">
                        <p class="font-display font-black text-gray-900 text-sm m-0 leading-tight">${v.storeName}</p>
                        <p class="text-[10px] text-gray-400 m-0 mt-1.5 uppercase font-bold tracking-tight">📍 ${v.location}</p>
                        <button onclick="window.location.hash='#/store/${v.vendorId}'" class="mt-3 w-full text-[10px] bg-primary text-white px-3 py-2 rounded-xl font-black uppercase active:scale-95 transition-all shadow-lg shadow-primary/20">Enter Store</button>
                    </div>
                `, { closeButton: false, className: 'custom-leaflet-popup' });

                markersLayer.addLayer(marker);
              });
          });
      };

      plotVendors();

  }, [vendors, selectedProductId, products]);

  const handleProductSelect = (pid: string) => {
      setSelectedProductId(pid);
      setIsDrawerOpen(false); 
  };

  const handleBack = (e: React.MouseEvent) => {
      e.preventDefault();
      if (window.history.length > 1) navigate(-1);
      else navigate('/buyer/dashboard', { replace: true });
  };

  return (
    <div className="relative h-screen w-full overflow-hidden bg-gray-100 dark:bg-darkBg flex flex-col transition-colors duration-300">

      {/* Floating Search Bar */}
      <div className="absolute top-4 left-4 right-4 z-[60] animate-slide-up">
        <div className="bg-white/95 dark:bg-darkSurface/95 backdrop-blur-md rounded-2xl shadow-float flex items-center p-3 border border-white/20 dark:border-white/5">
            <button type="button" onClick={handleBack} className="mr-3 w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-gray-500 dark:text-gray-400">
                <i className="fa-solid fa-arrow-left"></i>
            </button>
            <input 
                autoFocus
                value={query}
                onChange={(e) => { setQuery(e.target.value); setSelectedProductId(null); setIsDrawerOpen(true); }}
                placeholder="Search shops, hostels, or items..."
                className="flex-grow bg-transparent outline-none text-sm text-gray-800 dark:text-white placeholder-gray-400 font-medium"
            />
             {(query || selectedProductId) && <i className="fa-solid fa-xmark text-gray-400 cursor-pointer p-2" onClick={() => { setQuery(''); setSelectedProductId(null); setIsDrawerOpen(true); }}></i>}
        </div>
      </div>

      {/* Map Surface */}
      <div className="absolute inset-0 z-0" onClick={() => setIsDrawerOpen(false)}>
          <div ref={mapContainerRef} className="w-full h-full outline-none" />
      </div>

      {/* Results Drawer */}
      <div className={`absolute left-0 right-0 bottom-0 bg-white dark:bg-darkSurface rounded-t-[3rem] shadow-[0_-20px_50px_rgba(0,0,0,0.15)] z-30 transition-all duration-500 cubic-bezier(0.32, 0.72, 0, 1) flex flex-col ${isDrawerOpen ? 'h-[65vh]' : 'h-[18vh]'}`}>
        <div className="w-full py-5 flex justify-center cursor-grab active:cursor-grabbing" onClick={() => setIsDrawerOpen(!isDrawerOpen)}>
            <div className="w-14 h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
        </div>

        <div className="flex-grow overflow-y-auto px-6 pb-24 hide-scrollbar">
            <div className="flex justify-between items-center mb-6 sticky top-0 bg-white dark:bg-darkSurface py-2 z-10 border-b border-gray-50 dark:border-gray-800">
                <h3 className="font-black text-gray-900 dark:text-white text-xl font-display tracking-tight">
                    {selectedProductId ? 'Store Highlight' : `${approvedProducts.length} Shops Found`}
                </h3>
                {!selectedProductId && <span className="text-[10px] font-black text-primary uppercase tracking-widest bg-primary/10 px-2 py-1 rounded-lg">Campus Live</span>}
            </div>

            <div className="grid grid-cols-1 gap-4">
                {selectedProductId ? (
                    (() => {
                        const p = products.find(prod => prod.id === selectedProductId);
                        if (!p) return null;
                        const v = vendors.find(vend => vend.vendorId === p.vendorId);
                        const avatarUrl = getVendorAvatar(v);

                        return (
                            <div className="bg-indigo-50/50 dark:bg-primary/5 border border-indigo-100 dark:border-primary/20 rounded-[2.5rem] p-6 shadow-sm animate-fade-in">
                                <div className="flex items-center gap-5 mb-6 pb-6 border-b border-indigo-100 dark:border-primary/10">
                                     <div className="w-16 h-16 rounded-2xl overflow-hidden border-2 border-primary shadow-lg bg-white dark:bg-darkBg">
                                        <img src={avatarUrl} className="w-full h-full object-cover" />
                                     </div>
                                     <div>
                                         <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mb-1">Active Merchant</p>
                                         <h4 className="font-display font-black text-gray-900 dark:text-white text-xl leading-tight">{v?.storeName}</h4>
                                         <p className="text-xs text-gray-500 font-bold mt-1 flex items-center gap-1"><i className="fa-solid fa-location-dot text-red-500"></i> {v?.location}</p>
                                     </div>
                                </div>
                                <div className="flex gap-5">
                                    <div className="w-24 h-24 rounded-2xl overflow-hidden shadow-md border border-white dark:border-gray-800">
                                        <img src={p.images[0]} className="w-full h-full object-cover" />
                                    </div>
                                    <div className="flex-1 flex flex-col justify-center">
                                        <h4 className="font-bold text-gray-900 dark:text-white text-base leading-snug">{p.title}</h4>
                                        <p className="font-black text-primary text-2xl mt-1">₵{p.price}</p>
                                    </div>
                                </div>
                                <div className="mt-8 flex gap-3">
                                    <Button size="lg" className="flex-1 shadow-xl shadow-primary/30 h-14 font-black" onClick={() => navigate(`/buyer/product/${p.id}`)}>Enter Store</Button>
                                    <Button variant="secondary" size="lg" className="w-14 h-14" onClick={() => { setSelectedProductId(null); setIsDrawerOpen(true); }}><i className="fa-solid fa-list"></i></Button>
                                </div>
                            </div>
                        );
                    })()
                ) : (
                    approvedProducts.length === 0 ? (
                        <div className="text-center py-20 text-gray-300 opacity-60">
                            <i className="fa-solid fa-map-location-dot text-5xl mb-4"></i>
                            <p className="font-black uppercase tracking-[0.2em] text-xs">No active vendors here</p>
                        </div>
                    ) : (
                        approvedProducts.map(product => {
                            const vendor = vendors.find(v => v.vendorId === product.vendorId);
                            const avatarUrl = getVendorAvatar(vendor);
                            return (
                                <div key={product.id} className="flex bg-white dark:bg-darkBg/40 border border-gray-100 dark:border-gray-800 rounded-[2rem] p-4 shadow-sm active:scale-[0.98] transition-all cursor-pointer group" onClick={() => handleProductSelect(product.id)}>
                                    <div className="w-24 h-24 flex-shrink-0 bg-gray-50 dark:bg-darkBg rounded-2xl overflow-hidden border border-white dark:border-gray-800 shadow-sm relative">
                                        <img src={product.images[0]} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={product.title} />
                                    </div>
                                    <div className="ml-4 flex-grow flex flex-col justify-between py-1">
                                        <div>
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1 text-sm font-display leading-tight">{product.title}</h4>
                                                <Avatar src={avatarUrl} name={vendor?.storeName || ''} size="sm" className="w-6 h-6 ml-2 rounded-lg" />
