To support the new multi-campus infrastructure for **University of Ghana (Legon)** and **UPSA**, please run the following SQL scripts in your Supabase SQL Editor. 

These scripts are strictly additive and will not modify or delete your existing data.

```sql
-- 1. CAMPUSES TABLE
-- Stores high-level information about each campus
CREATE TABLE IF NOT EXISTS public.campuses (
  code text PRIMARY KEY, -- e.g., 'UG', 'UPSA'
  name text NOT NULL,
  city text DEFAULT 'Accra',
  center_coordinates jsonb NOT NULL, -- { "lat": 5.65, "lng": -0.18 }
  is_active boolean DEFAULT true,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. LOCATION CATEGORIES
-- Categories for map markers (Residential, Academic, Food, etc.)
CREATE TABLE IF NOT EXISTS public.location_categories (
  id uuid DEFAULT uuid_generate_v4() PRIMARY KEY,
  name text UNIQUE NOT NULL,
  icon text,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. DELIVERY ZONES
-- Geographical groupings for simplified delivery routing
CREATE TABLE IF NOT EXISTS public.delivery_zones (
  id uuid DEFAULT uuid_generate_v4() PRIMARY KEY,
  campus_code text REFERENCES public.campuses(code),
  name text NOT NULL,
  description text,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 4. CAMPUS LOCATIONS (Hyper-Precise Points)
-- Persistent storage for building-level geodata
CREATE TABLE IF NOT EXISTS public.campus_locations (
  id uuid DEFAULT uuid_generate_v4() PRIMARY KEY,
  campus_code text REFERENCES public.campuses(code),
  name text NOT NULL, -- e.g., 'Mensah Sarbah Hall'
  slug text NOT NULL, -- lowercase-cleaned version for lookups
  coordinates jsonb NOT NULL, -- { "lat": 5.6517, "lng": -0.1932 }
  category_id uuid REFERENCES public.location_categories(id),
  delivery_zone_id uuid REFERENCES public.delivery_zones(id),
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  UNIQUE(campus_code, slug)
);

-- 5. SAFE UPDATES TO EXISTING TABLES (Additive Only)
-- Adding campus column to vendors and products for filtering
DO $$ 
BEGIN
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='vendors' AND COLUMN_NAME='campus') THEN
    ALTER TABLE public.vendors ADD COLUMN campus text DEFAULT 'UG';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='products' AND COLUMN_NAME='campus') THEN
    ALTER TABLE public.products ADD COLUMN campus text DEFAULT 'UG';
  END IF;
END $$;

-- 6. PERFORMANCE INDEXES
CREATE INDEX IF NOT EXISTS idx_locations_campus_slug ON public.campus_locations (campus_code, slug);
CREATE INDEX IF NOT EXISTS idx_products_campus ON public.products (campus);
CREATE INDEX IF NOT EXISTS idx_vendors_campus ON public.vendors (campus);

-- 7. INITIAL CAMPUS DATA
INSERT INTO public.campuses (code, name, center_coordinates)
VALUES 
  ('UG', 'University of Ghana, Legon', '{"lat": 5.6506, "lng": -0.1962}'),
  ('UPSA', 'University of Professional Studies, Accra', '{"lat": 5.6508, "lng": -0.1685}')
ON CONFLICT (code) DO NOTHING;

-- 8. INITIAL CATEGORIES
INSERT INTO public.location_categories (name, icon)
VALUES 
  ('Residential', 'house'),
  ('Academic', 'book-open'),
  ('Food & Social', 'utensils'),
  ('Administration', 'building-columns'),
  ('Security & Access', 'shield-halved')
ON CONFLICT (name) DO NOTHING;

-- 9. RLS POLICIES (Read-only for public)
ALTER TABLE public.campuses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campus_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.delivery_zones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.location_categories ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public read campuses" ON public.campuses FOR SELECT USING (true);
CREATE POLICY "Public read locations" ON public.campus_locations FOR SELECT USING (true);
CREATE POLICY "Public read delivery zones" ON public.delivery_zones FOR SELECT USING (true);
CREATE POLICY "Public read categories" ON public.location_categories FOR SELECT USING (true);

