                <div className="flex-1 flex flex-row relative h-[500px] md:h-[600px] lg:h-[700px]">

                    {/* Vertical Gallery Sidebar - ALIGNED & SCROLLABLE */}
                    <div className="w-20 md:w-28 lg:w-32 bg-white dark:bg-darkBg/30 border-r border-gray-100 dark:border-white/5 flex flex-col overflow-y-auto hide-scrollbar gap-3 p-3 items-center scroll-smooth">
                        {product.images.map((img, i) => (
                            <div 
                                key={i} 
                                onClick={() => setActiveImg(i)}
                                className={`w-14 h-14 md:w-20 md:h-20 lg:w-24 lg:h-24 rounded-2xl flex-shrink-0 cursor-pointer overflow-hidden transition-all duration-300 border-2 ${activeImg === i ? 'border-primary shadow-glow ring-2 ring-primary/10' : 'border-gray-50 dark:border-gray-800 opacity-60 hover:opacity-100 bg-white'}`}
                            >
                                <img src={img} className="w-full h-full object-contain p-1" alt={`Thumb ${i}`} />
