export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, vendors, favorites, toggleFavorite, showToast, reviews } = useApp();

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    const [activeImg, setActiveImg] = useState(0);
    const [quantity, setQuantity] = useState(1);
    const [showZoom, setShowZoom] = useState(false);
    const [direction, setDirection] = useState(0); // 1 for next, -1 for prev

    // Swipe Ref State
    const touchStart = useRef<number | null>(null);
    const touchEnd = useRef<number | null>(null);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleAddToCart = () => {
        addToCart(product, quantity);
    };

    const nextImg = () => {
        setDirection(1);
        setActiveImg(prev => (prev + 1) % product.images.length);
    };

    const prevImg = () => {
        setDirection(-1);
        setActiveImg(prev => (prev - 1 + product.images.length) % product.images.length);
    };

    // Swipe Handlers
    const handleTouchStart = (e: React.TouchEvent) => {
        touchStart.current = e.targetTouches[0].clientX;
    };
    const handleTouchMove = (e: React.TouchEvent) => {
        touchEnd.current = e.targetTouches[0].clientX;
    };
    const handleTouchEnd = () => {
        if (!touchStart.current || !touchEnd.current) return;
        const diff = touchStart.current - touchEnd.current;
        const sensitivity = 50;
        if (diff > sensitivity) nextImg();
        if (diff < -sensitivity) prevImg();
        touchStart.current = null;
        touchEnd.current = null;
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in max-w-7xl mx-auto md:p-6 lg:p-10">
            {/* Gallery Interaction Area - FIXED HEIGHT ON DESKTOP FOR PERFECT TIP-TO-TIP ALIGNMENT */}
            <div className="bg-white dark:bg-darkSurface rounded-[3rem] shadow-float overflow-hidden flex flex-col lg:flex-row border border-white/20 dark:border-white/5">

                {/* 1. APPEAL GALLERY: LEFT (Vertical Sidebar) + CENTER (Main Focus) */}
