                                        <img src={product.images[0]} alt={product.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                        {product.stock === 0 && (<div className="absolute inset-0 bg-black/50 flex items-center justify-center backdrop-blur-sm"><span className="text-[9px] font-black text-white uppercase tracking-widest bg-red-500 px-3 py-1 rounded-full shadow-lg">Restocking Soon</span></div>)}
                                    </div>
                                    <div className="p-4">
                                        <h4 className="text-xs font-bold text-gray-900 dark:text-white line-clamp-1 mb-1 font-display tracking-tight">{product.title}</h4>
                                        <div className="flex justify-between items-center mt-2"><span className="text-sm font-black text-primary">₵{product.price}</span><i className="fa-solid fa-arrow-right text-[10px] text-gray-300 group-hover:text-primary group-hover:translate-x-1 transition-all"></i></div>
                                    </div>
                                </Card>
                            ))
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- Product Detail ---
export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, vendors, favorites, toggleFavorite, showToast, reviews } = useApp();

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    const [activeImg, setActiveImg] = useState(0);
    const [quantity, setQuantity] = useState(1);
    const [showZoom, setShowZoom] = useState(false);

    // Sidebar scrolling logic
    const sidebarRef = useRef<HTMLDivElement>(null);
    const thumbnailRefs = useRef<(HTMLDivElement | null)[]>([]);

    useEffect(() => {
        if (thumbnailRefs.current[activeImg] && sidebarRef.current) {
            thumbnailRefs.current[activeImg]?.scrollIntoView({
                behavior: 'smooth',
                block: 'nearest'
            });
        }
    }, [activeImg]);

    // Swipe Ref State
    const touchStart = useRef<number | null>(null);
    const touchEnd = useRef<number | null>(null);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleAddToCart = () => {
        addToCart(product, quantity);
    };

    const nextImg = () => setActiveImg(prev => (prev + 1) % product.images.length);
    const prevImg = () => setActiveImg(prev => (prev - 1 + product.images.length) % product.images.length);

    // Swipe Handlers
    const handleTouchStart = (e: React.TouchEvent) => {
        touchStart.current = e.targetTouches[0].clientX;
    };
    const handleTouchMove = (e: React.TouchEvent) => {
        touchEnd.current = e.targetTouches[0].clientX;
    };
    const handleTouchEnd = () => {
        if (touchStart.current === null || touchEnd.current === null) return;
        const diff = touchStart.current - touchEnd.current;
        const sensitivity = 50;
        if (diff > sensitivity) nextImg();
        if (diff < -sensitivity) prevImg();
        touchStart.current = null;
        touchEnd.current = null;
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in max-w-7xl mx-auto md:p-6 lg:p-10">
            {/* Gallery Area */}
            <div className="bg-white dark:bg-darkSurface rounded-[3rem] shadow-float overflow-hidden flex flex-col lg:flex-row border border-white/20 dark:border-white/5">

                {/* 1. APPEAL GALLERY: LEFT (Vertical Sidebar) + CENTER (Main Focus) */}
                <div className="flex-1 flex flex-row relative h-[500px] md:h-[600px] lg:h-[700px] group overflow-hidden">

                    {/* Vertical Gallery Sidebar - SCROLLABLE, PINNED TO TIPS OF MAIN IMAGE */}
                    <div 
                        ref={sidebarRef}
                        className="w-20 md:w-28 lg:w-32 bg-gray-50/30 dark:bg-darkBg/20 border-r border-gray-100 dark:border-white/5 flex flex-col overflow-y-auto hide-scrollbar gap-3 p-3 items-center scroll-smooth h-full"
                    >
                        {product.images.map((img, i) => (
                            <div 
                                key={i} 
                                // Fixed: Ensuring ref callback returns void instead of the element to avoid TypeScript error
                                ref={el => { thumbnailRefs.current[i] = el; }}
                                onClick={() => setActiveImg(i)}
                                className={`w-14 h-14 md:w-20 md:h-20 lg:w-24 lg:h-24 rounded-2xl flex-shrink-0 cursor-pointer overflow-hidden transition-all duration-500 border-2 ${activeImg === i ? 'border-primary shadow-glow scale-105 ring-2 ring-primary/20 bg-white' : 'border-transparent opacity-40 hover:opacity-100 bg-white'}`}
                            >
                                <img src={img} className="w-full h-full object-contain p-1" alt={`Thumb ${i}`} />
                            </div>
                        ))}
                        {/* Empty spacer to allow 4th or 5th item to align properly at top if scrolled */}
                        <div className="h-2 flex-shrink-0"></div>
                    </div>

                    {/* MAIN IMAGE DISPLAY - ULTRA SMOOTH SLIDER */}
                    <div 
                        className="flex-1 relative bg-white dark:bg-darkBg/10 overflow-hidden flex items-center justify-center cursor-zoom-in select-none touch-pan-y" 
                        onClick={() => setShowZoom(true)}
                        onTouchStart={handleTouchStart}
                        onTouchMove={handleTouchMove}
                        onTouchEnd={handleTouchEnd}
                    >
                        {/* Horizontal Translation Slider Layer */}
                        <div 
                            className="absolute inset-0 flex transition-transform duration-500 ease-out"
                            style={{ transform: `translateX(-${activeImg * 100}%)` }}
                        >
                            {product.images.map((img, idx) => (
                                <div key={idx} className="w-full h-full flex-shrink-0 flex items-center justify-center p-6 sm:p-10">
                                    <img 
                                        src={img} 
                                        className="max-h-full max-w-full object-contain transform transition-transform duration-700 hover:scale-105" 
                                        alt={product.title} 
                                    />
                                </div>
                            ))}
                        </div>

                        {/* Desktop Navigation Arrows */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); prevImg(); }}
                            className="hidden md:flex absolute left-4 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all hover:bg-primary hover:text-white z-20"
                        >
                            <i className="fa-solid fa-chevron-left"></i>
                        </button>
                        <button 
                            onClick={(e) => { e.stopPropagation(); nextImg(); }}
                            className="hidden md:flex absolute right-4 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all hover:bg-primary hover:text-white z-20"
                        >
                            <i className="fa-solid fa-chevron-right"></i>
                        </button>

                        {/* Pagination Indicator */}
                        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-2.5 px-4 py-2 bg-black/10 backdrop-blur-md rounded-full pointer-events-none z-20">
                            {product.images.map((_, i) => (
                                <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ease-in-out ${activeImg === i ? 'w-8 bg-primary shadow-glow' : 'w-1.5 bg-gray-300'}`}></div>
                            ))}
                        </div>

                        {/* Product Labels */}
                        <div className="absolute top-8 left-8 flex flex-col gap-3 pointer-events-none z-20">
                            <Badge color="violet" className="w-fit shadow-xl backdrop-blur-md px-4 py-2 text-[10px] font-black tracking-widest">{product.category}</Badge>
                            {product.stock < 5 && product.stock > 0 && <Badge color="red" className="w-fit shadow-xl bg-red-500 text-white animate-pulse">Low Stock</Badge>}
                        </div>

                        {/* Floating Back Button */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); navigate(-1); }}
                            className="absolute top-8 right-8 w-12 h-12 rounded-2xl bg-white/80 dark:bg-darkSurface/80 shadow-2xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-xl border border-white/20 active:scale-90 transition-all hover:bg-primary hover:text-white z-20"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                    </div>
                </div>

                {/* 2. SPECIFICATIONS SECTION - RIGHT */}
                <div className="w-full lg:w-[480px] p-8 md:p-12 flex flex-col border-t lg:border-t-0 lg:border-l border-gray-100 dark:border-white/5 bg-white dark:bg-darkSurface">
                    <div className="flex-grow space-y-8">
                        <div>
                            <p className="text-[10px] font-black text-primary uppercase tracking-[0.3em] mb-3">Campus Essential</p>
                            <h1 className="text-3xl md:text-4xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight">{product.title}</h1>

                            <div className="flex items-center gap-4 mt-6">
                                <span className="text-4xl font-black text-gray-900 dark:text-white font-display">₵{product.price}</span>
                                <div className="h-8 w-px bg-gray-200 dark:bg-gray-800"></div>
                                <div className="flex items-center gap-1.5 text-xs font-black text-gray-500">
                                    <i className="fa-solid fa-star text-yellow-400"></i>
                                    {product.rating?.toFixed(1) || "5.0"}
                                    <span className="text-gray-300 dark:text-gray-600 ml-1">({productReviews.length} reviews)</span>
                                </div>
                            </div>
                        </div>

                        {/* Merchant Card */}
                        <Card 
                            className="p-5 border-gray-100 dark:border-gray-800 hover:border-primary/40 bg-gray-50/50 dark:bg-white/5 group rounded-[2.5rem] transition-all cursor-pointer"
                            onClick={() => navigate(`/store/${product.vendorId}`)}
                        >
                            <div className="flex items-center gap-4">
                                <div className="relative">
                                    <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || "Vendor"} size="lg" className="rounded-2xl shadow-md border-2 border-white dark:border-darkBg" />
                                    <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white dark:border-darkBg rounded-full"></div>
                                </div>
                                <div className="flex-1">
                                    <h3 className="font-bold text-gray-900 dark:text-white text-base font-display line-clamp-1">{vendor?.storeName}</h3>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1 flex items-center gap-1">
                                        <i className="fa-solid fa-location-dot text-red-500"></i> {vendor?.location}
                                    </p>
                                </div>
                                <i className="fa-solid fa-arrow-right-long text-gray-300 group-hover:text-primary transition-all group-hover:translate-x-1"></i>
