                        <div>
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Description</h3>
                            <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-medium whitespace-pre-line">
                                {product.description}
                            </p>
                        </div>
                    </div>

                    {/* CTA Actions */}
                    <div className="mt-12 space-y-5">
                        <div className="flex items-center gap-4 bg-gray-50 dark:bg-darkBg p-2 rounded-2xl border border-gray-100 dark:border-gray-800">
                            <button 
                                onClick={() => setQuantity(q => Math.max(1, q - 1))}
