    // Sidebar and Swiping Refs
    const sidebarRef = useRef<HTMLDivElement>(null);
    const thumbnailRefs = useRef<(HTMLDivElement | null)[]>([]);
    const touchStart = useRef<number | null>(null);
    const touchEnd = useRef<number | null>(null);

    // Sync sidebar scroll when image changes
    useEffect(() => {
        if (thumbnailRefs.current[activeImg] && sidebarRef.current) {
            thumbnailRefs.current[activeImg]?.scrollIntoView({
                behavior: 'smooth',
                block: 'nearest'
            });
        }
    }, [activeImg]);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleAddToCart = () => {
        addToCart(product, quantity);
    };

    const nextImg = () => setActiveImg(prev => (prev + 1) % product.images.length);
    const prevImg = () => setActiveImg(prev => (prev - 1 + product.images.length) % product.images.length);

    // Swipe Handlers
    const handleTouchStart = (e: React.TouchEvent) => { touchStart.current = e.targetTouches[0].clientX; };
    const handleTouchMove = (e: React.TouchEvent) => { touchEnd.current = e.targetTouches[0].clientX; };
    const handleTouchEnd = () => {
        if (touchStart.current === null || touchEnd.current === null) return;
        const diff = touchStart.current - touchEnd.current;
        if (diff > 50) nextImg();
        if (diff < -50) prevImg();
        touchStart.current = null;
        touchEnd.current = null;
