            <div className="bg-white dark:bg-darkSurface rounded-[3rem] shadow-float overflow-hidden flex flex-col md:flex-row border border-white/20 dark:border-white/5 h-auto lg:h-[750px]">

                {/* GALLERY BLOCK: SIDEBAR + MAIN (Big Selected Display) */}
                <div className="flex-1 flex flex-row relative h-[500px] md:h-full group overflow-hidden">

                    {/* Vertical Gallery Sidebar - PINNED TOP-TO-BOTTOM TIPS */}
                    <div 
                        ref={sidebarRef}
                        className="w-20 md:w-24 lg:w-32 bg-gray-50/50 dark:bg-darkBg/20 border-r border-gray-100 dark:border-white/5 flex flex-col overflow-y-auto hide-scrollbar gap-3 p-3 items-center scroll-smooth h-full flex-shrink-0"
                    >
                        {product.images.map((img, i) => (
                            <div 
                                key={i} 
                                ref={el => { thumbnailRefs.current[i] = el; }}
                                onClick={() => setActiveImg(i)}
                                className={`w-14 h-14 md:w-16 md:h-16 lg:w-24 lg:h-24 rounded-2xl flex-shrink-0 cursor-pointer overflow-hidden transition-all duration-300 border-2 bg-white flex items-center justify-center ${activeImg === i ? 'border-primary shadow-glow scale-105 ring-2 ring-primary/20' : 'border-transparent opacity-40 hover:opacity-100'}`}
                            >
                                <img src={img} className="w-full h-full object-contain p-1" alt={`Thumb ${i}`} />
                            </div>
                        ))}
                    </div>

                    {/* MAIN "BIG" IMAGE DISPLAY: Aligns exactly with sidebar tips */}
                    <div 
                        className="flex-1 relative bg-white dark:bg-darkBg/5 overflow-hidden flex items-center justify-center cursor-zoom-in select-none touch-pan-y" 
                        onClick={() => setShowZoom(true)}
                        onTouchStart={handleTouchStart}
                        onTouchMove={handleTouchMove}
                        onTouchEnd={handleTouchEnd}
                    >
                        {/* THE BIG IMAGE SLIDER: ALWAYS VISIBLE ON LARGE SCREENS */}
                        <div 
                            className="absolute inset-0 flex transition-transform duration-700 cubic-bezier(0.16, 1, 0.3, 1)"
                            style={{ transform: `translateX(-${activeImg * 100}%)` }}
                        >
                            {product.images.map((img, idx) => (
                                <div key={idx} className="w-full h-full flex-shrink-0 flex items-center justify-center p-8 md:p-12 lg:p-16">
                                    <img 
                                        src={img} 
                                        className="max-h-full max-w-full object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.15)] transform transition-transform duration-1000 hover:scale-105" 
                                        alt={product.title} 
                                    />
                                </div>
                            ))}
                        </div>

                        {/* Floating Interaction Overlays */}
                        <div className="absolute top-6 left-6 flex flex-col gap-3 pointer-events-none z-20">
                            <Badge color="violet" className="w-fit shadow-xl backdrop-blur-md px-4 py-2 text-[10px] font-black tracking-widest">{product.category}</Badge>
                            {product.stock < 5 && product.stock > 0 && <Badge color="red" className="w-fit shadow-xl bg-red-500 text-white animate-pulse">Running Low</Badge>}
                        </div>

                        {/* Navigation Controls */}
                        <button onClick={(e) => { e.stopPropagation(); prevImg(); }} className="hidden md:flex absolute left-4 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all hover:bg-primary hover:text-white z-30">
                            <i className="fa-solid fa-chevron-left"></i>
                        </button>
                        <button onClick={(e) => { e.stopPropagation(); nextImg(); }} className="hidden md:flex absolute right-4 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all hover:bg-primary hover:text-white z-30">
                            <i className="fa-solid fa-chevron-right"></i>
                        </button>

                        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-2 px-4 py-2 bg-black/10 backdrop-blur-md rounded-full pointer-events-none z-30">
                            {product.images.map((_, i) => (
                                <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${activeImg === i ? 'w-8 bg-primary shadow-glow' : 'w-1.5 bg-gray-300'}`}></div>
                            ))}
                        </div>

                        <button 
                            onClick={(e) => { e.stopPropagation(); navigate(-1); }}
                            className="absolute top-6 right-6 w-12 h-12 rounded-2xl bg-white/80 dark:bg-darkSurface/80 shadow-2xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-xl border border-white/20 active:scale-90 transition-all hover:bg-primary hover:text-white z-30"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                    </div>
                </div>

                {/* 2. PRODUCT INFO AREA (ALWAYS NEXT TO BIG IMAGE ON LARGE SCREENS) */}
                <div className="w-full md:w-[400px] lg:w-[480px] p-8 md:p-12 flex flex-col border-t md:border-t-0 md:border-l border-gray-100 dark:border-white/5 bg-white dark:bg-darkSurface">
                    <div className="flex-grow space-y-8">
                        <div>
                            <p className="text-[11px] font-black text-primary uppercase tracking-[0.3em] mb-3">Campus Exclusive</p>
                            <h1 className="text-3xl lg:text-4xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight">{product.title}</h1>

                            <div className="flex items-center gap-4 mt-6">
                                <span className="text-4xl font-black text-gray-900 dark:text-white font-display">₵{product.price}</span>
                                <div className="h-8 w-px bg-gray-200 dark:bg-gray-800"></div>
                                <div className="flex items-center gap-1.5 text-xs font-black text-gray-500">
                                    <i className="fa-solid fa-star text-yellow-400"></i>
                                    {product.rating?.toFixed(1) || "5.0"}
                                    <span className="text-gray-300 dark:text-gray-600 ml-1">({productReviews.length})</span>
                                </div>
                            </div>
                        </div>

                        {/* Store Link Card */}
                        <Card 
                            className="p-5 border-gray-100 dark:border-gray-800 hover:border-primary/40 bg-gray-50/50 dark:bg-white/5 group rounded-[2.5rem] transition-all cursor-pointer"
                            onClick={() => navigate(`/store/${product.vendorId}`)}
                        >
