export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, vendors, favorites, toggleFavorite, reviews, showToast } = useApp();

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    const [activeImg, setActiveImg] = useState(0);
    const [quantity, setQuantity] = useState(1);
    const [showZoom, setShowZoom] = useState(false);

    const sidebarRef = useRef<HTMLDivElement>(null);
    const thumbnailRefs = useRef<(HTMLDivElement | null)[]>([]);

    useEffect(() => {
        if (thumbnailRefs.current[activeImg] && sidebarRef.current) {
            thumbnailRefs.current[activeImg]?.scrollIntoView({
                behavior: 'smooth',
                block: 'nearest'
            });
        }
    }, [activeImg]);

    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);
    const isFav = favorites.includes(product?.id || '');

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const isInCart = cart.some(i => i.productId === product.id);

    const handleBuyNow = () => {
        if (product.stock > 0) {
            addToCart(product, quantity);
            navigate('/buyer/checkout');
        }
    };

    const handleWhatsApp = () => {
        const phone = vendor?.contactPhone || product.contactPhone;
        if (!phone) {
            showToast("Vendor contact info not found.", "error");
            return;
        }
        let cleanPhone = phone.replace(/\D/g, '');
        if (cleanPhone.startsWith('0')) {
            cleanPhone = '233' + cleanPhone.substring(1);
        }
        const message = encodeURIComponent(`Hi ${vendor?.storeName || 'Vendor'}, I'm interested in your "${product.title}" (₵${product.price}) listed on LYNQED.`);
        window.open(`https://wa.me/${cleanPhone}?text=${message}`, '_blank');
    };

    const handleShare = async () => {
        const shareData = {
            title: product.title,
            text: `Check out this "${product.title}" on LYNQED!`,
            url: `https://lynqed.vercel.app/#/buyer/product/${id}`
        };

        if (navigator.share) {
            try {
                await navigator.share(shareData);
            } catch (err) {
                console.log('Native share failed', err);
            }
        } else {
            // Fallback for desktop or non-supported browsers
            navigator.clipboard.writeText(shareData.url);
            showToast("Product link copied!", "success");
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in max-w-7xl mx-auto md:p-6 lg:p-10">
            {/* 1. MAIN PRODUCT CARD */}
            <div className="bg-white dark:bg-darkSurface rounded-[3rem] shadow-float overflow-hidden grid grid-cols-1 lg:grid-cols-10 border border-white/20 dark:border-white/5 lg:min-h-[800px]">

                {/* A. GALLERY STAGE */}
                <div className="lg:col-span-7 flex flex-row relative h-[450px] md:h-[650px] lg:h-full group overflow-hidden border-b lg:border-b-0 lg:border-r border-gray-100 dark:border-white/5">

                    {/* Vertical Gallery Sidebar */}
                    <div 
                        ref={sidebarRef}
                        className="w-20 md:w-24 lg:w-32 bg-gray-50/50 dark:bg-darkBg/20 border-r border-gray-100 dark:border-white/5 flex flex-col overflow-y-auto hide-scrollbar gap-4 p-4 items-center scroll-smooth h-full flex-shrink-0"
                    >
                        {product.images.map((img, i) => (
                            <div 
                                key={i} 
                                ref={el => { thumbnailRefs.current[i] = el; }}
                                onClick={() => setActiveImg(i)}
                                className={`w-14 h-14 md:w-16 md:h-16 lg:w-24 lg:h-24 rounded-2xl flex-shrink-0 cursor-pointer overflow-hidden transition-all duration-300 border-2 bg-white flex items-center justify-center ${activeImg === i ? 'border-primary shadow-glow scale-105 ring-2 ring-primary/20' : 'border-transparent opacity-40 hover:opacity-100'}`}
                            >
                                <img src={img} className="w-full h-full object-contain p-1" alt={`Thumb ${i}`} />
                            </div>
                        ))}
                    </div>

                    {/* MAIN BIG IMAGE HUB */}
                    <div 
                        className="flex-1 relative bg-white dark:bg-darkBg/5 overflow-hidden flex items-center justify-center cursor-zoom-in select-none h-full" 
                        onClick={() => setShowZoom(true)}
                    >
                        <div 
                            className="w-full h-full flex transition-transform duration-700 cubic-bezier(0.16, 1, 0.3, 1)"
                            style={{ transform: `translateX(-${activeImg * 100}%)` }}
                        >
                            {product.images.map((img, idx) => (
                                <div key={idx} className="w-full h-full flex-shrink-0 flex items-center justify-center p-8 md:p-12 lg:p-20">
                                    <img 
                                        src={img} 
                                        className="max-h-full max-w-full object-contain drop-shadow-[0_45px_100px_rgba(0,0,0,0.2)] transition-all duration-1000" 
                                        alt={product.title} 
                                    />
                                </div>
                            ))}
                        </div>

                        <div className="absolute top-8 left-8 flex flex-col gap-3 pointer-events-none z-20">
                            <Badge color="violet" className="w-fit shadow-xl backdrop-blur-md px-4 py-2 text-[10px] font-black tracking-widest">{product.category}</Badge>
                            {product.stock < 10 && product.stock > 0 && <Badge color="red" className="w-fit shadow-xl bg-red-500 text-white animate-bounce-slight uppercase">Limited Stock: {product.stock}</Badge>}
                        </div>

                        <button 
                            onClick={(e) => { e.stopPropagation(); navigate(-1); }}
                            className="absolute top-8 right-8 w-12 h-12 rounded-2xl bg-white/80 dark:bg-darkSurface/80 shadow-2xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-xl border border-white/20 active:scale-90 transition-all hover:bg-primary hover:text-white z-30"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>

                        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-3 px-5 py-2.5 bg-black/15 backdrop-blur-md rounded-full pointer-events-none z-30">
                            {product.images.map((_, i) => (
                                <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${activeImg === i ? 'w-10 bg-primary shadow-glow' : 'w-1.5 bg-gray-300'}`}></div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* B. PRODUCT DETAILS & PURCHASE PANEL */}
                <div className="lg:col-span-3 p-8 md:p-12 flex flex-col bg-white dark:bg-darkSurface h-full">
                    <div className="flex-grow space-y-8">
                        <div>
                            <p className="text-[11px] font-black text-primary uppercase tracking-[0.4em] mb-4">Official Campus Listing</p>
                            <h1 className="text-3xl lg:text-4xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight">{product.title}</h1>

                            <div className="flex items-center gap-5 mt-8">
                                <span className="text-4xl font-black text-gray-900 dark:text-white font-display">₵{product.price}</span>
                                <div className="h-10 w-px bg-gray-200 dark:bg-gray-800"></div>
                                <div className="flex flex-col">
                                    <div className="flex items-center gap-1.5 text-xs font-black text-gray-500">
                                        <i className="fa-solid fa-star text-yellow-400"></i>
                                        {product.rating?.toFixed(1) || "5.0"}
                                        <span className="text-gray-300 dark:text-gray-600 ml-1">({productReviews.length})</span>
                                    </div>
                                    <span className="text-[9px] font-bold text-green-500 uppercase mt-1 tracking-widest">In Stock & Verified</span>
                                </div>
                            </div>
                        </div>

                        <Card 
                            className="p-5 border-gray-100 dark:border-gray-800 hover:border-primary/40 bg-gray-50/50 dark:bg-white/5 group rounded-[2.5rem] transition-all cursor-pointer shadow-none"
                            onClick={() => navigate(`/store/${product.vendorId}`)}
                        >
                            <div className="flex items-center gap-4">
                                <div className="relative">
                                    <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || "Vendor"} size="lg" className="rounded-2xl shadow-md border-2 border-white dark:border-darkBg" />
                                    <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white dark:border-darkBg rounded-full"></div>
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h3 className="font-bold text-gray-900 dark:text-white text-base font-display truncate">{vendor?.storeName}</h3>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1 flex items-center gap-1">
                                        <i className="fa-solid fa-location-dot text-red-500"></i> {vendor?.location}
                                    </p>
                                </div>
                                <i className="fa-solid fa-chevron-right text-gray-300 group-hover:text-primary transition-all group-hover:translate-x-1"></i>
                            </div>
                        </Card>

                        <div>
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.25em] mb-4">Product Overview</h3>
                            <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-medium whitespace-pre-line max-h-60 overflow-y-auto pr-3 custom-scrollbar">
                                {product.description}
                            </p>
                        </div>
                    </div>

                    {/* TWO-SIDED ACTION PANEL */}
                    <div className="mt-12 space-y-8">

                        {/* SIDE ONE: Purchase & Wishlist Actions */}
                        <div className="bg-gray-50/50 dark:bg-white/5 p-6 rounded-[2.5rem] border border-gray-100 dark:border-white/5 space-y-4 shadow-sm">
                            <div className="flex items-center gap-4 bg-white dark:bg-darkBg p-2.5 rounded-2xl border border-gray-100 dark:border-gray-800">
                                <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="w-12 h-12 rounded-xl bg-gray-50 dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all hover:text-primary"><i className="fa-solid fa-minus"></i></button>
                                <span className="font-black text-xl flex-1 text-center dark:text-white">{quantity}</span>
                                <button onClick={() => setQuantity(q => Math.min(product.stock, q + 1))} className="w-12 h-12 rounded-xl bg-gray-50 dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all hover:text-primary"><i className="fa-solid fa-plus"></i></button>
                            </div>

                            <div className="grid grid-cols-1 gap-3">
                                <Button 
                                    fullWidth 
                                    size="lg" 
                                    onClick={handleBuyNow} 
                                    disabled={product.stock === 0} 
                                    className="h-16 font-black text-lg shadow-2xl shadow-primary/30 border-none uppercase tracking-tight"
                                    icon="bolt"
                                >
                                    {product.stock === 0 ? 'Out of Stock' : 'Buy It Now'}
                                </Button>

                                <div className="flex gap-3">
                                    <Button 
                                        fullWidth 
                                        size="lg" 
                                        variant="primary"
                                        onClick={() => addToCart(product, quantity)} 
                                        disabled={product.stock === 0} 
                                        className={`h-16 font-black text-sm uppercase tracking-widest transition-all !from-indigo-600 !to-indigo-800 ${isInCart ? '!from-green-600 !to-green-700 shadow-green-500/20' : ''}`}
                                        icon={isInCart ? 'cart-arrow-down' : 'cart-plus'}
                                    >
                                        {isInCart ? 'In Your Cart' : 'Add to Cart'}
                                    </Button>

                                    <button 
                                        onClick={() => toggleFavorite(product.id)} 
                                        title="Save to Wishlist"
                                        className={`w-16 h-16 rounded-[1.25rem] border-2 flex items-center justify-center transition-all flex-shrink-0 ${isFav ? 'bg-red-500 border-red-500 text-white shadow-red-500/30' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-400 hover:text-red-500'}`}
                                    >
                                        <i className={`fa-${isFav ? 'solid' : 'regular'} fa-heart text-xl`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* SIDE TWO: Direct Inquiry & Social Actions */}
                        <div className="space-y-3">
                            <button 
                                onClick={handleWhatsApp}
                                className="w-full h-16 rounded-2xl bg-emerald-500 hover:bg-emerald-600 text-white flex items-center justify-center gap-4 transition-all duration-300 active:scale-[0.98] shadow-lg shadow-emerald-500/20 group"
                            >
                                <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center group-hover:scale-110 transition-transform">
                                    <i className="fa-brands fa-whatsapp text-2xl"></i>
                                </div>
                                <div className="text-left">
                                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80 leading-none mb-1">Direct Chat</p>
                                    <p className="text-base font-bold leading-none">Message Merchant</p>
                                </div>
                                <i className="fa-solid fa-chevron-right text-[10px] ml-auto mr-6 opacity-40"></i>
                            </button>

                            <button 
                                onClick={handleShare}
                                className="w-full h-12 rounded-2xl bg-white dark:bg-darkSurface hover:bg-gray-50 dark:hover:bg-gray-800 text-gray-500 dark:text-gray-400 flex items-center justify-center gap-3 transition-all border border-gray-100 dark:border-white/5 font-bold text-xs uppercase tracking-widest"
                            >
                                <i className="fa-solid fa-share-nodes"></i>
                                Share This Product
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Mobile Fixed CTA */}
            <div className="md:hidden fixed bottom-0 left-0 right-0 p-6 bg-white/95 dark:bg-darkSurface/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 z-[60] animate-slide-up flex gap-3">
                <Button variant="primary" className="h-14 w-14 rounded-2xl flex-shrink-0 !from-indigo-600 !to-indigo-800 shadow-indigo-500/20" onClick={() => addToCart(product, quantity)}>
                    <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-cart-plus'} text-lg`}></i>
                </Button>
                <button 
                    onClick={handleWhatsApp}
                    className="h-14 w-14 rounded-2xl flex-shrink-0 bg-emerald-500 text-white flex items-center justify-center shadow-lg shadow-emerald-500/20 active:scale-95"
                >
                    <i className="fa-brands fa-whatsapp text-xl"></i>
                </button>
                <Button fullWidth size="lg" onClick={handleBuyNow} disabled={product.stock === 0} className="h-14 font-black shadow-xl shadow-primary/20 border-none text-base">
                    {product.stock === 0 ? 'Sold Out' : `Buy Now • ₵${(product.price * quantity).toFixed(0)}`}
                </Button>
            </div>

            {/* ZOOM LIGHTBOX */}
            {showZoom && (
                <div className="fixed inset-0 z-[200] bg-black/98 backdrop-blur-2xl flex flex-col items-center justify-center p-4 animate-fade-in" onClick={() => setShowZoom(false)}>
                    <button className="absolute top-8 right-8 w-14 h-14 bg-white/10 hover:bg-white/20 text-white rounded-full flex items-center justify-center text-2xl transition-all z-50">
                        <i className="fa-solid fa-xmark"></i>
                    </button>

                    <div className="relative w-full max-w-5xl flex items-center justify-center px-12" onClick={e => e.stopPropagation()}>
                        <button onClick={(e) => { e.stopPropagation(); setActiveImg(prev => (prev - 1 + product.images.length) % product.images.length); }} className="absolute left-0 w-16 h-16 rounded-full bg-white/5 text-white hover:bg-white/10 transition-colors flex items-center justify-center text-2xl">
                            <i className="fa-solid fa-chevron-left"></i>
                        </button>

                        <img src={product.images[activeImg]} className="max-w-full max-h-[80vh] rounded-3xl shadow-2xl object-contain animate-scale-up" alt="Zoomed" />

                        <button onClick={(e) => { e.stopPropagation(); setActiveImg(prev => (prev + 1) % product.images.length); }} className="absolute right-0 w-16 h-16 rounded-full bg-white/5 text-white hover:bg-white/10 transition-colors flex items-center justify-center text-2xl">
                            <i className="fa-solid fa-chevron-right"></i>
                        </button>
                    </div>

                    <div className="mt-12 flex gap-4 overflow-x-auto max-w-full p-4 hide-scrollbar">
                        {product.images.map((img, i) => (
                            <img 
                                key={i} 
                                src={img} 
                                onClick={(e) => { e.stopPropagation(); setActiveImg(i); }}
                                className={`w-20 h-20 md:w-28 md:h-28 rounded-2xl object-contain bg-white cursor-pointer border-4 transition-all ${activeImg === i ? 'border-primary scale-110 shadow-glow' : 'border-transparent opacity-20 hover:opacity-60'}`} 
                                alt="Thumb"
                            />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

