                    <span className="text-gray-900 dark:text-white line-clamp-1">{product.title}</span>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-10 gap-8">

                    {/* LEFT SIDE: GALLERY (6/10) */}
                    <div className="lg:col-span-6 flex gap-4 h-[450px] md:h-[650px]">
                        {/* Vertical Thumbnails - Now visible on all screens */}
                        <div 
                            ref={sidebarRef}
                            className="flex flex-col gap-2 md:gap-3 w-14 md:w-20 overflow-y-auto hide-scrollbar flex-shrink-0"
                        >
                            {product.images.map((img, i) => (
                                <div 
                                    key={i}
                                    ref={el => { thumbnailRefs.current[i] = el; }}
                                    onClick={() => setActiveImg(i)}
                                    className={`aspect-square w-full rounded-lg md:rounded-xl cursor-pointer border-2 transition-all p-0.5 md:p-1 bg-white ${activeImg === i ? 'border-primary ring-2 ring-primary/10 shadow-sm' : 'border-transparent opacity-50 hover:opacity-100'}`}
                                >
                                    <img src={img} className="w-full h-full object-contain" alt="" />
