                            className="flex-1 relative bg-gray-50 dark:bg-white/5 rounded-[2.5rem] overflow-hidden flex items-center justify-center cursor-zoom-in group shadow-inner touch-pan-y"
                            onClick={() => setShowZoom(true)}
                            onTouchStart={onTouchStart}
                            onTouchMove={onTouchMove}
                            onTouchEnd={onTouchEnd}
                        >
                            <img 
                                src={product.images[activeImg]} 
                                className="max-h-[90%] max-w-[90%] object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.1)] transition-transform duration-700 group-hover:scale-105" 
                                alt={product.title} 
                            />

                            {/* Tags Overlay */}
                            <div className="absolute top-6 left-6 flex flex-col gap-2">
                                <div className="bg-red-600 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter shadow-lg flex items-center gap-1.5">
                                    <i className="fa-solid fa-fire text-[8px]"></i> #1 Best-Selling
