                            >
                                <i className="fa-solid fa-arrow-left"></i>
                            </button>

                            {/* Swipe Indicator Dots for Mobile */}
                            <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-1.5 md:hidden">
                                {product.images.map((_, i) => (
                                    <div key={i} className={`w-1.5 h-1.5 rounded-full transition-all ${activeImg === i ? 'bg-primary w-4' : 'bg-gray-300'}`}></div>
                                ))}
