                    <span className="hover:text-primary cursor-pointer">{product.category}</span>
                    <i className="fa-solid fa-chevron-right text-[8px]"></i>
                    <span className="text-gray-900 dark:text-white line-clamp-1">{product.title}</span>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-10 gap-8">

                    {/* LEFT SIDE: GALLERY (6/10) */}
                    <div className="lg:col-span-6 flex gap-4 h-[450px] md:h-[650px]">
                        {/* Vertical Thumbnails */}
                        <div 
                            ref={sidebarRef}
                            className="flex flex-col gap-2 md:gap-3 w-14 md:w-20 overflow-y-auto hide-scrollbar flex-shrink-0"
                        >
                            {product.images.map((img, i) => (
                                <div 
                                    key={i}
                                    ref={el => { thumbnailRefs.current[i] = el; }}
                                    onClick={() => setActiveImg(i)}
                                    className={`aspect-square w-full rounded-lg md:rounded-xl cursor-pointer border-2 transition-all p-0.5 md:p-1 bg-white ${activeImg === i ? 'border-primary ring-2 ring-primary/10 shadow-sm' : 'border-transparent opacity-50 hover:opacity-100'}`}
                                >
                                    <img src={img} className="w-full h-full object-contain" alt="" />
                                </div>
                            ))}
                        </div>

                        {/* Main Stage with High-Fidelity Swipe Track */}
                        <div 
                            ref={galleryContainerRef}
                            className="flex-1 relative bg-gray-50 dark:bg-white/5 rounded-[2.5rem] overflow-hidden group shadow-inner touch-pan-y flex items-center"
                            onTouchStart={handleTouchStart}
                            onTouchMove={handleTouchMove}
                            onTouchEnd={handleTouchEnd}
                        >
                            {/* Animated Track */}
                            <div 
                                className={`flex w-full h-full items-center ${!isDragging ? 'transition-transform duration-500 cubic-bezier(0.2, 0.8, 0.2, 1)' : ''}`}
                                style={{ 
                                    transform: `translateX(calc(-${activeImg * 100}% + ${dragOffset}px))` 
                                }}
                            >
                                {product.images.map((img, i) => (
                                    <div 
                                        key={i} 
                                        className="w-full h-full flex-shrink-0 flex items-center justify-center p-8"
                                        onClick={() => setShowZoom(true)}
                                    >
                                        <img 
                                            src={img} 
                                            className="max-h-full max-w-full object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.1)] transition-transform duration-700 group-hover:scale-105 pointer-events-none select-none" 
                                            alt={product.title} 
                                        />
                                    </div>
                                ))}
                            </div>

                            {/* Tags Overlay */}
                            <div className="absolute top-6 left-6 flex flex-col gap-2 z-10 pointer-events-none">
                                <div className="bg-red-600 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter shadow-lg flex items-center gap-1.5">
                                    <i className="fa-solid fa-fire text-[8px]"></i> #1 Best-Selling
                                </div>
                                {product.stock < 10 && (
                                    <div className="bg-orange-500 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter shadow-lg">
                                        Almost Sold Out
                                    </div>
                                )}
                            </div>

                            {/* Back Button */}
                            <button 
                                onClick={(e) => { e.stopPropagation(); navigate(-1); }}
                                className="absolute top-6 right-6 w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all border border-white/50 z-10"
                            >
                                <i className="fa-solid fa-arrow-left"></i>
                            </button>

                            {/* Swipe Indicator Dots */}
                            <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-1.5 z-10 pointer-events-none">
                                {product.images.map((_, i) => (
                                    <div key={i} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${activeImg === i ? 'bg-primary w-4' : 'bg-gray-300'}`}></div>
                                ))}
