// --- Custom Swipe Hook ---
const useSwipeTrack = (itemCount: number, initialIndex: number = 0) => {
    const [activeIndex, setActiveIndex] = useState(initialIndex);
    const [isDragging, setIsDragging] = useState(false);
    const [dragOffset, setDragOffset] = useState(0);
    const touchStartX = useRef(0);

    const onTouchStart = (e: React.TouchEvent) => {
        touchStartX.current = e.touches[0].clientX;
        setIsDragging(true);
        setDragOffset(0);
    };

    const onTouchMove = (e: React.TouchEvent) => {
        if (!isDragging) return;
        const currentX = e.touches[0].clientX;
        const diff = currentX - touchStartX.current;

        // Elasticity at edges
        let elasticDiff = diff;
        if ((activeIndex === 0 && diff > 0) || (activeIndex === itemCount - 1 && diff < 0)) {
            elasticDiff = diff * 0.3;
        }
        setDragOffset(elasticDiff);
    };

    const onTouchEnd = () => {
        setIsDragging(false);
        const threshold = 60; // Smooth threshold

        if (dragOffset < -threshold && activeIndex < itemCount - 1) {
            setActiveIndex(prev => prev + 1);
        } else if (dragOffset > threshold && activeIndex > 0) {
            setActiveIndex(prev => prev - 1);
        }
        setDragOffset(0);
    };

    return {
        activeIndex,
        setActiveIndex,
        isDragging,
        dragOffset,
        handlers: { onTouchStart, onTouchMove, onTouchEnd }
    };
};

