                                    <div key={i} className="w-full h-full flex-shrink-0 flex items-center justify-center p-8" onClick={() => setShowZoom(true)}>
                                        <img src={img} className="max-h-full max-w-full object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.1)] transition-transform duration-700 group-hover:scale-105 pointer-events-none select-none" alt={product.title} />
                                    </div>
                                ))}
                            </div>

                            {/* Tags */}
                            <div className="absolute top-6 left-6 flex flex-col gap-2 z-10 pointer-events-none">
                                <div className="bg-red-600 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter shadow-lg flex items-center gap-1.5"><i className="fa-solid fa-fire text-[8px]"></i> #1 Best-Selling</div>
                                {product.stock < 10 && <div className="bg-orange-500 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter shadow-lg">Almost Sold Out</div>}
                            </div>

                            <button onClick={(e) => { e.stopPropagation(); navigate(-1); }} className="absolute top-6 right-6 w-10 h-10 rounded-full bg-white/90 dark:bg-darkSurface/90 shadow-xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all border border-white/50 z-10"><i className="fa-solid fa-arrow-left"></i></button>

                            <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-1.5 z-10 pointer-events-none">
                                {product.images.map((_, i) => <div key={i} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${mainGallery.activeIndex === i ? 'bg-primary w-4' : 'bg-gray-300'}`}></div>)}
                            </div>
                        </div>
                    </div>

                    {/* RIGHT SIDE: INFO */}
                    <div className="lg:col-span-4 space-y-6">
                        <div>
                            <div className="flex justify-between items-start mb-2">
                                <h1 className="text-2xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight flex-1 pr-4">{product.title}</h1>
                                <button onClick={handleShare} className="w-10 h-10 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-500 hover:text-primary transition-colors"><i className="fa-solid fa-share-nodes"></i></button>
                            </div>
                            <div className="flex items-center gap-3 text-sm">
                                <div className="flex items-center gap-1 text-yellow-400"><i className="fa-solid fa-star"></i><span className="font-black text-gray-900 dark:text-white">{product.rating?.toFixed(1) || '5.0'}</span></div>
                                <span className="text-gray-300 dark:text-gray-700">|</span>
                                <span className="text-gray-500 dark:text-gray-400 font-bold">1.2K+ sold</span>
                                <span className="text-gray-300 dark:text-gray-700">|</span>
                                <span className="text-gray-500 dark:text-gray-400 font-bold">{productReviews.length} Reviews</span>
                            </div>
                        </div>

                        <div className="bg-red-50/50 dark:bg-red-950/10 p-5 rounded-[2rem] border border-red-100 dark:border-red-900/20">
                            <div className="flex items-baseline gap-2">
                                <span className="text-sm font-black text-red-600">GHS</span>
                                <span className="text-4xl font-black text-red-600 tracking-tighter">₵{product.price.toFixed(2)}</span>
                                <span className="text-xs text-gray-400 line-through ml-2">₵{(product.price * 1.44).toFixed(0)}</span>
                                <Badge color="red" className="ml-auto bg-red-600 text-white rounded-md px-1.5 py-0.5 text-[8px]">-44% Limited Time</Badge>
                            </div>
                            <div className="flex items-center gap-2 mt-3 text-[10px] font-black text-red-600/70 uppercase tracking-widest"><i className="fa-solid fa-bolt-lightning animate-pulse"></i>Clearance Deal Ends in 05:22:11</div>
                        </div>

                        <div className="space-y-4 pt-4">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Vendor / Merchant</p>
                                <Card className="p-4 border-gray-100 dark:border-gray-800 hover:border-primary/40 bg-gray-50/50 dark:bg-white/5 rounded-2xl transition-all cursor-pointer shadow-none group" onClick={() => navigate(`/store/${product.vendorId}`)}>
                                    <div className="flex items-center gap-3">
                                        <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || "Vendor"} size="md" className="rounded-xl border-2 border-white dark:border-darkBg shadow-sm" />
                                        <div className="flex-1">
                                            <h3 className="font-bold text-gray-900 dark:text-white text-sm truncate">{vendor?.storeName}</h3>
                                            <p className="text-[9px] font-black text-gray-400 uppercase flex items-center gap-1"><i className="fa-solid fa-location-dot text-red-500"></i> {vendor?.location}</p>
                                        </div>
                                        <i className="fa-solid fa-chevron-right text-gray-300 group-hover:text-primary transition-all group-hover:translate-x-1"></i>
                                    </div>
                                </Card>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">About This Item</p>
                                <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-medium">{product.description}</p>
                            </div>
                        </div>

                        <div className="space-y-4 pt-6">
                            <div className="flex items-center justify-between">
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Quantity</span>
                                <div className="flex items-center gap-4 bg-gray-100 dark:bg-darkBg p-1.5 rounded-xl border border-gray-200 dark:border-gray-800">
                                    <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="w-8 h-8 rounded-lg bg-white dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all"><i className="fa-solid fa-minus text-[10px]"></i></button>
                                    <span className="font-black text-sm w-6 text-center dark:text-white">{quantity}</span>
                                    <button onClick={() => setQuantity(q => Math.min(product.stock, q + 1))} className="w-8 h-8 rounded-lg bg-white dark:bg-darkSurface text-gray-900 dark:text-white shadow-sm flex items-center justify-center active:scale-90 transition-all"><i className="fa-solid fa-plus text-[10px]"></i></button>
                                </div>
                            </div>
                            <div className="grid grid-cols-1 gap-3 pt-2">
                                <button onClick={handleBuyNow} disabled={product.stock === 0} className="w-full h-16 rounded-full bg-red-600 hover:bg-red-700 text-white font-black text-lg shadow-xl shadow-red-600/20 active:scale-[0.98] transition-all uppercase tracking-tight flex items-center justify-center gap-3 disabled:opacity-50 disabled:grayscale"><i className="fa-solid fa-bolt"></i>{product.stock === 0 ? 'Out of Stock' : 'Buy It Now'}</button>
                                <div className="flex gap-3">
                                    <button onClick={() => addToCart(product, quantity)} className={`flex-1 h-14 rounded-full font-black text-sm uppercase tracking-widest border-2 transition-all flex items-center justify-center gap-3 ${isInCart ? 'bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-white dark:bg-darkBg border-gray-900 dark:border-white text-gray-900 dark:text-white'}`}><i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-cart-plus'}`}></i>{isInCart ? 'Added to Cart' : 'Add to Cart'}</button>
                                    <button onClick={() => toggleFavorite(product.id)} className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all ${isFav ? 'bg-red-500 border-red-500 text-white shadow-lg shadow-red-500/20' : 'bg-white dark:bg-darkBg border-gray-100 dark:border-gray-800 text-gray-400'}`}><i className={`fa-${isFav ? 'solid' : 'regular'} fa-heart text-lg`}></i></button>
                                </div>
                            </div>
                            <div className="flex items-center gap-4 py-2"><div className="h-px flex-1 bg-gray-100 dark:bg-gray-800" /><span className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Questions?</span><div className="h-px flex-1 bg-gray-100 dark:bg-gray-800" /></div>
                            <button onClick={handleWhatsApp} className="w-full h-14 rounded-full bg-emerald-500 hover:bg-emerald-600 text-white flex items-center justify-center gap-4 transition-all shadow-lg shadow-emerald-500/20 group active:scale-[0.98]"><i className="fa-brands fa-whatsapp text-2xl"></i><span className="font-black text-sm uppercase tracking-widest">Message Merchant</span></button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Mobile Fixed CTA */}
            <div className="md:hidden fixed bottom-0 left-0 right-0 p-4 bg-white/95 dark:bg-darkSurface/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 z-[60] animate-slide-up flex gap-3 pb-safe">
                <button onClick={() => toggleFavorite(product.id)} className={`h-14 w-14 rounded-full flex-shrink-0 flex items-center justify-center border-2 ${isFav ? 'bg-red-500 border-red-500 text-white' : 'bg-gray-50 border-gray-100 text-gray-400'}`}><i className={`fa-${isFav ? 'solid' : 'regular'} fa-heart text-xl`}></i></button>
                <button onClick={handleBuyNow} disabled={product.stock === 0} className="flex-1 h-14 bg-red-600 text-white rounded-full font-black text-base shadow-lg shadow-red-600/20 active:scale-95">{product.stock === 0 ? 'Sold Out' : `Buy Now • ₵${(product.price * quantity).toFixed(0)}`}</button>
            </div>

            {/* ZOOM LIGHTBOX WITH SWIPE */}
            {showZoom && (
                <div className="fixed inset-0 z-[200] bg-black/98 backdrop-blur-2xl flex flex-col items-center justify-center p-0 animate-fade-in" onClick={() => setShowZoom(false)}>
                    <button className="absolute top-8 right-8 w-14 h-14 bg-white/10 hover:bg-white/20 text-white rounded-full flex items-center justify-center text-2xl transition-all z-[210]"><i className="fa-solid fa-xmark"></i></button>

                    {/* Zoom Swipe Stage */}
                    <div className="w-full h-full relative overflow-hidden flex items-center" {...zoomGallery.handlers}>
                        <div 
                            className={`flex w-full h-full items-center ${!zoomGallery.isDragging ? 'transition-transform duration-500 cubic-bezier(0.23, 1, 0.32, 1)' : ''}`}
                            style={{ transform: `translate3d(calc(-${zoomGallery.activeIndex * 100}% + ${zoomGallery.dragOffset}px), 0, 0)` }}
                        >
                            {product.images.map((img, i) => (
                                <div key={i} className="w-full h-full flex-shrink-0 flex items-center justify-center p-4 md:p-20" onClick={e => e.stopPropagation()}>
                                    <img src={img} className="max-w-full max-h-[85vh] rounded-3xl shadow-2xl object-contain animate-scale-up pointer-events-none select-none" alt="Zoomed" />
                                </div>
                            ))}
                        </div>

                        {/* Nav Buttons */}
                        <button onClick={(e) => { e.stopPropagation(); zoomGallery.setActiveIndex(prev => Math.max(0, prev - 1)); }} className="hidden md:flex absolute left-8 w-16 h-16 rounded-full bg-white/5 text-white hover:bg-white/10 transition-colors items-center justify-center text-2xl z-[210]"><i className="fa-solid fa-chevron-left"></i></button>
                        <button onClick={(e) => { e.stopPropagation(); zoomGallery.setActiveIndex(prev => Math.min(product.images.length - 1, prev + 1)); }} className="hidden md:flex absolute right-8 w-16 h-16 rounded-full bg-white/5 text-white hover:bg-white/10 transition-colors items-center justify-center text-2xl z-[210]"><i className="fa-solid fa-chevron-right"></i></button>
                    </div>

                    {/* Bottom Indicator List */}
                    <div className="absolute bottom-8 left-0 right-0 px-4">
                        <div className="flex gap-4 overflow-x-auto justify-center pb-4 hide-scrollbar">
                            {product.images.map((img, i) => (
                                <img key={i} src={img} onClick={(e) => { e.stopPropagation(); zoomGallery.setActiveIndex(i); }} className={`w-16 h-16 md:w-20 md:h-20 flex-shrink-0 rounded-xl object-contain bg-white cursor-pointer border-2 transition-all ${zoomGallery.activeIndex === i ? 'border-primary scale-110 shadow-glow' : 'border-transparent opacity-30 hover:opacity-60'}`} alt="Thumb" />
                            ))}
                        </div>
                        <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.3em] text-center">{zoomGallery.activeIndex + 1} / {product.images.length}</p>
                    </div>
                </div>
            )}
        </div>
    );
};

