// LYNQED Service Worker for Push Notifications

self.addEventListener('push', function(event) {
  let data = { title: 'LYNQED', body: 'New update available!' };

  if (event.data) {
    try {
      data = event.data.json();
    } catch (e) {
      data.body = event.data.text();
    }
  }

  const options = {
    body: data.body,
    icon: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
    badge: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
    vibrate: [100, 50, 100],
    data: data.url || '/',
    actions: [
      { action: 'open', title: 'View Details' }
    ],
    tag: 'lynqed-notif', // Groups notifications
    renotify: true
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

self.addEventListener('notificationclick', function(event) {
  event.notification.close();
  const urlToOpen = event.notification.data || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(clientList) {
      // If a window is already open, focus it
      for (let i = 0; i < clientList.length; i++) {
        let client = clientList[i];
        if (client.url === urlToOpen && 'focus' in client) {
          return client.focus();
        }
      }
      // Otherwise open a new one
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});

