const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    const upsaKey = Object.keys(UPSA_LOCATION_CACHE).find(k => clean.includes(k));
    if (upsaKey) return { lat: UPSA_LOCATION_CACHE[upsaKey][0], lng: UPSA_LOCATION_CACHE[upsaKey][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    const ugKey = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (ugKey) return { lat: INITIAL_LOCATION_CACHE[ugKey][0], lng: INITIAL_LOCATION_CACHE[ugKey][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

// Helper for VAPID conversion if using Web Push directly
function urlBase64ToUint8Array(base64String: string) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/\-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);

  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });

  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });

  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = 
      theme === 'dark' || 
      (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

    if (!isThemeSwitchingAllowed) {
        root.classList.remove('dark');
    } else {
        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');
    }
  }, [theme, isThemeSwitchingAllowed]);

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  const updateTheme = (newTheme: ThemeMode) => {
      setTheme(newTheme);
      safeSetItem('lynqed_theme_last', newTheme);
  };

  const toggleThemeSwitching = (allowed: boolean) => {
      setIsThemeSwitchingAllowed(allowed);
      safeSetItem('lynqed_sys_theme_allowed', String(allowed));
  };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` });
      return { success: !error, error: error?.message };
  };

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      return { success: !error, error: error?.message };
  };

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  useEffect(() => { 
      if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); 
  }, [currentRole]);

  const fetchNotifications = useCallback(async () => {
      const { data: session } = await supabase.auth.getSession();
      const userId = session?.session?.user?.id;
      if (!userId) return;

      try {
          const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`)
            .order('created_at', { ascending: false });

          if (!error && data) {
              const filtered = data.filter(n => {
                  if (n.target_scope === 'role' && n.target_role !== currentRole) return false;
                  return true;
              });

              setNotifications(filtered.map(n => ({
                  ...n, userId: n.user_id, targetRole: n.target_role,
                  targetScope: n.target_scope, relatedId: n.related_id,
                  isRead: n.is_read, createdAt: n.created_at
              })));
          }
      } catch (e) { console.warn("Notif Fetch Error", e); }
  }, [currentRole]);

  const fetchReviews = useCallback(async () => {
    try {
        const { data, error } = await supabase
            .from('reviews')
            .select('*, profiles(name, avatar_url)')
            .order('created_at', { ascending: false });

        if (error) throw error;
        if (data) {
            setReviews(data.map(r => ({
                ...r, productId: r.product_id, vendorId: r.vendor_id,
                userId: r.user_id, createdAt: r.created_at,
                user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
            })));
        }
    } catch (e) { console.warn("Review Fetch Error", e); }
  }, []);

  const fetchData = useCallback(async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             let query = supabase.from(table).select(select);
             if (orderBy) query = query.order(orderBy, { ascending: false });
             const { data } = await query;
             return data;
          };
          const [pData, vData, oData, cDataRaw, uData] = await Promise.all([
              fetchSafely('products', '*', 'created_at'), fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'), fetchSafely('couriers'),
              supabase.from('profiles').select('*')
          ]);
          if (pData) setProducts(pData.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
          if (vData) setVendors(vData.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone, campus: v.campus })));
          if (oData) setOrders(oData.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
          if (cDataRaw && uData.data) {
              const profileMap = new Map(uData.data.map((p: any) => [p.id, p]));
              setCouriers(cDataRaw.map((d: any) => ({ ...d, userId: d.user_id, fullName: (profileMap.get(d.user_id) as any)?.name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
          }
          if (uData.data) setUsers(uData.data as any);
      } catch (e) { console.error("Data Fetch Error:", e); } finally { setIsDataLoading(false); }
  }, []);

  const fetchUserProfile = async (userId: string, sessionUser?: any): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;
          if (data) {
              if (data.isBanned) throw new Error("Account Suspended");
              const user: User = { 
                  ...data, roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url, phoneNumber: data.phone_number,
                  defaultLocation: data.address, pushToken: data.push_token
              };
              setCurrentUser(user);
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              let finalRole: Role = (persistedRole && user.roles.includes(persistedRole)) ? persistedRole : (user.roles.includes('admin') ? 'admin' : (user.roles.includes('vendor') ? 'vendor' : 'buyer'));
              setCurrentRole(finalRole);
              safeSetItem('lynqed_role', finalRole);
              return user;
          } else if (sessionUser) {
              await supabase.from('profiles').insert({ id: userId, email: sessionUser.email, name: sessionUser.user_metadata?.full_name || 'User', roles: ['buyer'] });
              return fetchUserProfile(userId);
          }
      } catch (e) { console.error("Profile fetch error", e); }
      return null;
  };

  const initApp = async () => {
      try {
          const { data } = await supabase.auth.getSession();
          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
          await Promise.all([fetchData(), fetchNotifications(), fetchReviews()]);
          setConnectionError(false);
      } catch (e) { console.error("Initialization Failed:", e);
      } finally { setIsLoading(false); setIsDataLoading(false); }
  };

  useEffect(() => {
    initApp();
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, () => fetchData()).subscribe();
    const vendorSub = supabase.channel('public:vendors').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, () => fetchData()).subscribe();
    const notifSub = supabase.channel('public:notifications').on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => fetchNotifications()).subscribe();
    const reviewSub = supabase.channel('public:reviews').on('postgres_changes', { event: '*', schema: 'public', table: 'reviews' }, () => fetchReviews()).subscribe();

    return () => {
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
        supabase.removeChannel(vendorSub);
        supabase.removeChannel(notifSub);
        supabase.removeChannel(reviewSub);
    };
  }, [fetchNotifications, fetchReviews, fetchData]); 

  const sendNotification = useCallback(async (payload: Partial<Notification>) => {
    try {
        const { error } = await supabase.from('notifications').insert({
            user_id: payload.userId,
            target_role: payload.targetRole,
            target_scope: payload.targetScope || 'individual',
            type: payload.type,
            title: payload.title,
            message: payload.message,
            related_id: payload.relatedId,
            priority: payload.priority || 'normal',
            is_read: false
        });
        if (error) throw error;
        return true;
    } catch (e) {
        console.error("Send Notif Error", e);
        return false;
    }
  }, []);

  const submitReview = useCallback(async (review: Omit<Review, 'createdAt' | 'user'>) => {
    try {
        const { error } = await supabase.from('reviews').upsert({
            id: review.id || undefined,
            product_id: review.productId,
            vendor_id: review.vendorId,
            user_id: review.userId,
            rating: review.rating,
            comment: review.comment,
            images: review.images
        });
        if (error) throw error;
        showToast("Review submitted!", "success");
        fetchReviews();
        return true;
    } catch (e) {
        showToast("Failed to submit review", "error");
        return false;
    }
  }, [showToast, fetchReviews]);

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id, data.user);
          await Promise.all([fetchData(), fetchNotifications(), fetchReviews()]);
          const finalRole: Role = (user?.roles.includes('admin') ? 'admin' : (user?.roles.includes('vendor') ? 'vendor' : 'buyer')) as Role;
          setCurrentRole(finalRole);
          safeSetItem('lynqed_role', finalRole);
          return { success: true, role: finalRole };
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
           return await login(email, password); 
      }
      return { success: false };
  };

  const logout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentRole('guest'); setNotifications([]); setReviews([]); setCart([]); localStorage.removeItem('lynqed_role'); };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) { setCurrentRole(role); safeSetItem('lynqed_role', role); showToast(`Switched to ${role.charAt(0).toUpperCase() + role.slice(1)} Mode`, 'info'); fetchNotifications(); }
  };

  const markNotificationRead = async (id: string) => { 
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
      await supabase.from('notifications').update({ is_read: true }).eq('id', id); 
  };

  const markAllNotificationsRead = async () => { 
      if (!currentUser) return; 
      setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
      await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id).eq('is_read', false); 
  };

  const deleteNotification = async (id: string) => { 
      setNotifications(prev => prev.filter(n => n.id !== id));
      await supabase.from('notifications').delete().eq('id', id); 
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, 
                  delivery_fee: fee, status: 'placed', delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();
              if (error) throw error;
              if (vendor) await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order Received!', message: `New order for ₵${(subtotal+fee).toFixed(2)}.`, relatedId: data.id, priority: 'high' });
              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', orderId); 
      if (!error) {
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: ${status.replace('_', ' ')}.`, relatedId: orderId });
              if (status === 'ready_for_pickup' && order.deliveryOption === 'delivery') await sendNotification({ targetScope: 'role', targetRole: 'courier', type: 'delivery', title: 'Job Available!', message: 'A package is ready for delivery.', relatedId: orderId, priority: 'high' });
          }
          fetchData(); 
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); 
      if (!error) {
          const vendor = vendors.find(v => v.vendorId === vid);
          if (vendor) await sendNotification({ userId: vendor.userId, type: 'approval', title: s ? 'Store Approved!' : 'Review Update', message: s ? 'Your store is live.' : 'Review status changed.', priority: 'high' });
          fetchData(); 
      }
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type });
      if(!error) { 
          await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'system', title: 'New Driver Applied', message: `${data.fullName} applied.` });
          fetchData(); return { success: true }; 
      }
      return { success: false };
  };

  const updateProfile = async (data: Partial<User>) => {
    if(!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address, push_token: data.pushToken }).eq('id', currentUser.id);
    if(!error) { showToast("Profile updated", "success"); fetchUserProfile(currentUser.id); return { success: true }; }
    return { success: false };
  };

  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { showToast('Upload failed', 'error'); return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;
      const { error } = await supabase.from('vendors').upsert({ vendor_id: vid, user_id: currentUser.id, store_name: data.store_name, store_description: data.store_description, location: data.location, contact_phone: data.contact_phone, store_avatar_url: data.store_avatar_url, is_approved: ex ? ex.isApproved : false, rating: ex ? ex.rating : 5.0, campus: data.campus }, { onConflict: 'user_id' });
      if (!error) {
          if (!currentUser.roles.includes('vendor')) await supabase.from('profiles').update({ roles: [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])] }).eq('id', currentUser.id);
          if (!ex) await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'system', title: 'New Store Request', message: `${data.store_name} applied.` });
          fetchData(); return { success: true };
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, campus: v.campus, contact_phone: prod.contact_phone });
      if (!error) { 
          showToast("Submitted", "success"); 
          await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'approval', title: 'Item for Review', message: `New item from ${v.storeName}.` });
          fetchData(); return true; 
      }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id); fetchData(); };
  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { 
      await supabase.from('products').update({status}).eq('id', id); 
      const prod = products.find(p => p.id === id);
      const v = vendors.find(v => v.vendorId === prod?.vendorId);
      if (v) await sendNotification({ userId: v.userId, type: 'approval', title: 'Item Update', message: `"${prod?.title}" is ${status}.` });
      fetchData(); 
  };

  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { await supabase.from('products').update({ is_trending: isTrending }).eq('id', id); fetchData(); };
  const addToCart = useCallback((p: Product, q = 1) => { setCart(prev => { const ex = prev.find(i => i.productId === p.id); return ex ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; }); showToast(`Added ${p.title}`, "success"); }, [showToast]);
  const removeFromCart = useCallback((pid: string) => { setCart(prev => prev.filter(i => i.productId !== pid)); showToast("Removed", "info"); }, [showToast]);
  const updateCartQuantity = useCallback((pid: string, qty: number) => { if(qty <= 0) removeFromCart(pid); else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } }, [removeFromCart]);
  const clearCart = useCallback(() => { setCart([]); showToast("Cleared", "info"); }, [showToast]);

  const toggleFavorite = useCallback((pid: string) => { 
      const isRem = favorites.includes(pid); 
      setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); 
      showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success'); 
  }, [favorites, showToast]);

  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); const order = orders.find(o => o.id === oid); if (order) await sendNotification({ userId: order.buyerId, type: 'delivery', title: 'Driver Assigned!', message: `A courier is on the way.`, relatedId: oid }); fetchData(); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchData(); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); if (status === 'approved') { const profile = users.find(u => u.id === userId); if (profile) await supabase.from('profiles').update({ roles: [...new Set([...profile.roles, 'courier' as Role, 'buyer' as Role])] }).eq('id', userId); await sendNotification({ userId, type: 'approval', title: 'Driver Verified!', message: 'You are now live.' }); } fetchData(); };

  // Real Push Notification Handshake logic
  const requestNotificationPermission = async () => {
    if (!('Notification' in window)) {
        showToast("Push notifications not supported on this browser.", "error");
        return false;
    }

    try {
        const permission = await Notification.requestPermission();
        if (permission === 'granted') {
            if ('serviceWorker' in navigator) {
                const registration = await navigator.serviceWorker.ready;
                // VAPID Key Placeholder - You get this from Firebase Console
                // Settings -> Cloud Messaging -> Web Push Certificates
                const vapidKey = 'BF-PLACEHOLDER-VAPID-KEY-FROM-FIREBASE-CONSOLE'; 

                try {
                    const subscription = await registration.pushManager.subscribe({
                        userVisibleOnly: true,
                        applicationServerKey: urlBase64ToUint8Array(vapidKey)
                    });

                    // Save subscription string to database
                    if (currentUser) {
                        await updateProfile({ pushToken: JSON.stringify(subscription) });
                    }

                    showToast("Push notifications enabled!", "success");
                    return true;
                } catch (subErr) {
                    console.error("Subscription failed", subErr);
                    showToast("Failed to link device. Try again later.", "error");
                }
            }
        } else {
            showToast("Notification permission denied.", "info");
        }
    } catch (e) {
        console.error("Permission request error", e);
    }
    return false;
  };

  const refreshData = async () => { setIsDataLoading(true); await Promise.all([fetchData(), fetchNotifications(), fetchReviews()]); setIsDataLoading(false); };

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, submitReview, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast, requestNotificationPermission
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, addToCart, removeFromCart, updateCartQuantity, fetchNotifications, fetchReviews, fetchData, sendNotification, submitReview, toggleFavorite]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Badge, Avatar, Button } from './UI';
import { Notification } from '../types';

interface NotificationCenterProps {
    isOpen: boolean;
    onClose: () => void;
}

export const NotificationCenter: React.FC<NotificationCenterProps> = ({ isOpen, onClose }) => {
    const { 
        notifications, markNotificationRead, markAllNotificationsRead, 
        deleteNotification, unreadCount, currentRole, 
        requestNotificationPermission, currentUser 
    } = useApp();

    const navigate = useNavigate();
    const [filter, setFilter] = useState<'all' | 'unread' | 'order' | 'system'>('all');
    const [selectedNotif, setSelectedNotif] = useState<Notification | null>(null);
    const [showPushPrompt, setShowPushPrompt] = useState(false);

    // Check if we should show the push notification prompt
    useEffect(() => {
        if (isOpen && currentUser && !currentUser.pushToken) {
            // Only show if the browser supports notifications and they haven't been denied
            if ('Notification' in window && Notification.permission !== 'denied') {
                setShowPushPrompt(true);
            }
        }
    }, [isOpen, currentUser]);

    const filtered = useMemo(() => {
        return notifications.filter(n => {
            if (filter === 'unread') return !n.isRead;
            if (filter === 'order') return n.type === 'order_update' || n.type === 'new_order' || n.type === 'delivery';
            if (filter === 'system') return n.type === 'system' || n.type === 'approval';
            return true;
        });
    }, [notifications, filter]);

    const grouped = useMemo(() => {
        const groups: Record<string, Notification[]> = { Today: [], Yesterday: [], Earlier: [] };
        const now = new Date();
        const yesterday = new Date(now);
        yesterday.setDate(now.getDate() - 1);

        filtered.forEach(n => {
            const date = new Date(n.createdAt);
            if (date.toDateString() === now.toDateString()) groups.Today.push(n);
            else if (date.toDateString() === yesterday.toDateString()) groups.Yesterday.push(n);
            else groups.Earlier.push(n);
        });
        return groups;
    }, [filtered]);

    const handleEnablePush = async () => {
        const success = await requestNotificationPermission();
        if (success) setShowPushPrompt(false);
    };

    const handleSelectNotif = (n: Notification) => {
        setSelectedNotif(n);
    };

    const handleManualMarkRead = async (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        await markNotificationRead(id);
    };

    const handleDeepLink = (n: Notification) => {
        setSelectedNotif(null);
        onClose();
        if (n.relatedId) {
            const path = (currentRole === 'vendor' && (n.type === 'new_order' || n.type === 'order_update')) 
                ? '/vendor/orders' 
                : n.type === 'approval' 
                ? '/vendor/products' 
                : '/buyer/orders';
            navigate(path);
        }
    };

    const getIcon = (type: string) => {
        switch(type) {
            case 'order_update': return { icon: 'box', color: 'text-blue-500 bg-blue-50 dark:bg-blue-900/20' };
            case 'new_order': return { icon: 'cart-plus', color: 'text-green-500 bg-green-50 dark:bg-green-900/20' };
            case 'delivery': return { icon: 'motorcycle', color: 'text-primary bg-indigo-50 dark:bg-indigo-900/20' };
            case 'approval': return { icon: 'circle-check', color: 'text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20' };
            case 'promotion': return { icon: 'fire', color: 'text-orange-500 bg-orange-50 dark:bg-orange-900/20' };
            default: return { icon: 'bell', color: 'text-gray-500 bg-gray-50 dark:bg-gray-800' };
        }
    };

    if (!isOpen) return null;

    return (
        <>
            <div className="fixed inset-0 z-[100] flex justify-end">
                <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] animate-fade-in" onClick={onClose}></div>

                <div className="relative w-full max-w-sm h-full bg-white dark:bg-darkSurface shadow-2xl flex flex-col animate-slide-left border-l border-gray-100 dark:border-white/5">
                    {/* Header */}
                    <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex items-center justify-between">
                        <div>
                            <h2 className="text-xl font-display font-black text-gray-900 dark:text-white">Notifications</h2>
                            <div className="flex items-center gap-2 mt-1">
                                <span className="text-[10px] font-black text-primary uppercase tracking-widest bg-primary/10 px-2 py-0.5 rounded-full">
                                    {unreadCount} New
                                </span>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            {unreadCount > 0 && (
                                <button 
                                    onClick={markAllNotificationsRead} 
                                    title="Mark all as read"
                                    className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-primary hover:bg-primary hover:text-white transition-all shadow-sm"
                                >
                                    <i className="fa-solid fa-check-double text-xs"></i>
                                </button>
                            )}
                            <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-400 hover:text-gray-900 dark:hover:text-white transition-all">
                                <i className="fa-solid fa-xmark"></i>
                            </button>
                        </div>
                    </div>

                    {/* Push Notification Handshake Prompt */}
                    {showPushPrompt && (
                        <div className="p-4 bg-gradient-to-br from-primary/10 via-white to-indigo-50 dark:from-primary/20 dark:via-darkSurface dark:to-darkBg border-b border-primary/20 animate-fade-in">
                            <div className="flex gap-4">
                                <div className="w-12 h-12 rounded-2xl bg-primary text-white flex items-center justify-center shadow-glow flex-shrink-0 animate-bounce-slight">
                                    <i className="fa-solid fa-bell-concierge text-xl"></i>
                                </div>
                                <div className="flex-1">
                                    <h4 className="text-sm font-black text-gray-900 dark:text-white">Enable Real-Time Alerts?</h4>
                                    <p className="text-[11px] text-gray-500 dark:text-gray-400 mt-0.5 leading-relaxed">Get notified instantly when orders are accepted or a driver is nearby.</p>
                                    <div className="flex gap-2 mt-3">
                                        <button 
                                            onClick={handleEnablePush}
                                            className="px-4 py-1.5 bg-primary text-white text-[10px] font-black uppercase rounded-lg shadow-md active:scale-95 transition-all"
                                        >
                                            Turn On
                                        </button>
                                        <button 
                                            onClick={() => setShowPushPrompt(false)}
                                            className="px-4 py-1.5 bg-gray-100 dark:bg-gray-800 text-gray-500 text-[10px] font-black uppercase rounded-lg"
                                        >
                                            Later
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Filters */}
                    <div className="px-4 py-3 flex gap-2 overflow-x-auto hide-scrollbar border-b border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-black/10">
                        {[
                            {id: 'all', label: 'All'},
                            {id: 'unread', label: 'Unread'},
                            {id: 'order', label: 'Orders'},
                            {id: 'system', label: 'System'}
                        ].map(f => (
                            <button 
                                key={f.id}
                                onClick={() => setFilter(f.id as any)}
                                className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border ${filter === f.id ? 'bg-primary text-white border-primary shadow-glow' : 'bg-white dark:bg-gray-800 text-gray-400 border-gray-100 dark:border-gray-700'}`}
                            >
                                {f.label}
                            </button>
                        ))}
                    </div>

                    {/* List Grouped */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-8 custom-scrollbar">
                        {filtered.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-center opacity-30 px-10">
                                <div className="w-20 h-20 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4">
                                    <i className="fa-solid fa-bell-slash text-3xl"></i>
                                </div>
                                <p className="text-sm font-bold uppercase tracking-widest">Inbox Empty</p>
                                <p className="text-[10px] mt-2 leading-relaxed">We'll alert you here for orders, approvals, and campus updates.</p>
                            </div>
                        ) : (
                            Object.entries(grouped).map(([title, items]) => items.length > 0 && (
                                <div key={title} className="space-y-3">
                                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2 flex items-center gap-2">
                                        <span className="w-1.5 h-1.5 rounded-full bg-gray-300"></span>
                                        {title}
                                    </h3>
                                    {items.map(n => {
                                        const style = getIcon(n.type);
                                        return (
                                            <div 
                                                key={n.id}
                                                onClick={() => handleSelectNotif(n)}
                                                className={`p-4 rounded-2xl border transition-all cursor-pointer group relative ${n.isRead ? 'bg-white dark:bg-darkSurface border-gray-50 dark:border-gray-800/50 opacity-60' : 'bg-white dark:bg-gray-800/40 border-primary/20 shadow-md ring-1 ring-primary/5'}`}
                                            >
                                                <div className="flex gap-4">
                                                    <div className={`w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0 shadow-sm ${style.color}`}>
                                                        <i className={`fa-solid fa-${style.icon} text-base`}></i>
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <div className="flex justify-between items-start mb-1">
                                                            <h4 className={`text-sm font-bold truncate ${n.isRead ? 'text-gray-600 dark:text-gray-400' : 'text-gray-900 dark:text-white'}`}>{n.title}</h4>
                                                            <span className="text-[8px] font-black text-gray-400 uppercase whitespace-nowrap ml-2">
                                                                {new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                            </span>
                                                        </div>
                                                        <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-2 leading-relaxed font-medium">
                                                            {n.message}
                                                        </p>
                                                    </div>
                                                </div>

                                                <div className="absolute bottom-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    {!n.isRead && (
                                                        <button 
                                                            onClick={(e) => handleManualMarkRead(e, n.id)}
