// --- High Fidelity Swipe Hook ---
const useSwipeTrack = (itemCount: number, initialIndex: number = 0) => {
    const [activeIndex, setActiveIndex] = useState(initialIndex);
    const [isDragging, setIsDragging] = useState(false);
    const [dragOffset, setDragOffset] = useState(0);
    const touchStartX = useRef(0);
    const velocity = useRef(0);
    const lastTime = useRef(0);
    const lastX = useRef(0);

    const onTouchStart = (e: React.TouchEvent) => {
        touchStartX.current = e.touches[0].clientX;
        lastX.current = e.touches[0].clientX;
        lastTime.current = Date.now();
        setIsDragging(true);
        setDragOffset(0);
        velocity.current = 0;
    };

    const onTouchMove = (e: React.TouchEvent) => {
        if (!isDragging) return;
        const currentX = e.touches[0].clientX;
        const currentTime = Date.now();
        const diff = currentX - touchStartX.current;

        // Calculate velocity for "flick" effect
        const dt = currentTime - lastTime.current;
        if (dt > 0) {
            velocity.current = (currentX - lastX.current) / dt;
        }

        // High resistance at boundaries (Damping)
        let damping = 1;
        if ((activeIndex === 0 && diff > 0) || (activeIndex === itemCount - 1 && diff < 0)) {
            damping = 0.25;
        }

        setDragOffset(diff * damping);
        lastX.current = currentX;
        lastTime.current = currentTime;
    };

    const onTouchEnd = () => {
        setIsDragging(false);
        const threshold = 80; 
        const speedThreshold = 0.5; // Swipe speed triggers change even if threshold not met

        const totalDiff = dragOffset;
        const finalVelocity = velocity.current;

        // Snapping logic based on distance OR velocity
        if ((totalDiff < -threshold || finalVelocity < -speedThreshold) && activeIndex < itemCount - 1) {
            setActiveIndex(prev => prev + 1);
        } else if ((totalDiff > threshold || finalVelocity > speedThreshold) && activeIndex > 0) {
            setActiveIndex(prev => prev - 1);
        }

        setDragOffset(0);
    };

    return {
        activeIndex,
        setActiveIndex,
        isDragging,
        dragOffset,
        handlers: { onTouchStart, onTouchMove, onTouchEnd }
    };
};

