            )}

            {view === 'products' && (
                 <div className="grid grid-cols-3 md:grid-cols-4 gap-4 animate-fade-in">
                    {products.map(p => (
                        <Card key={p.id} className="flex flex-col h-full border-2 border-gray-50 dark:border-white/5 group overflow-hidden">
