                                    <span className="text-sm font-black text-primary">₵{p.price}</span>
                                    <button onClick={() => toggleTrendingStatus(p.id, !p.isTrending)} className={`w-7 h-7 rounded-lg flex items-center justify-center transition-all ${p.isTrending ? 'bg-orange-500 text-white' : 'bg-gray-50 text-gray-400'}`}><i className="fa-solid fa-fire text-[10px]"></i></button>
                                </div>
                                {p.status === 'pending' && (
                                    <div className="grid grid-cols-2 p-1 gap-1 mt-2">
                                        <button className="h-8 rounded-lg text-[8px] font-black uppercase bg-success text-white" onClick={() => updateProductStatus(p.id, 'approved')}>OK</button>
                                        <button className="h-8 rounded-lg text-[8px] font-black uppercase bg-danger text-white" onClick={() => updateProductStatus(p.id, 'rejected')}>NO</button>
                                    </div>
                                )}
                            </div>
                        </Card>
                    ))}
                 </div>
            )}
        </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useApp } from '../context';
import { Button, Badge, Card, Avatar, Input } from '../components/UI';
import { useNavigate } from 'react-router-dom';
import { Role, NotificationScope, NotificationPriority } from '../types';

type AdminView = 'dashboard' | 'users' | 'vendors' | 'products' | 'logistics' | 'broadcast' | 'system';

export const AdminDashboard: React.FC = () => {
  const { 
    products, users, vendors, orders, couriers,
    updateProductStatus, toggleTrendingStatus, deleteProduct, 
    approveVendor, banUser, approveCourier, sendNotification,
    logout, theme, updateTheme, isThemeSwitchingAllowed, toggleThemeSwitching, showToast, currentUser
  } = useApp();

  const navigate = useNavigate();
  const [view, setView] = useState<AdminView>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // --- Broadcast State ---
  const [bcScope, setBcScope] = useState<NotificationScope>('global');
  const [bcRole, setBcRole] = useState<Role>('buyer');
  const [bcUserId, setBcUserId] = useState('');
  const [bcTitle, setBcTitle] = useState('');
  const [bcMessage, setBcMessage] = useState('');
  const [bcPriority, setBcPriority] = useState<NotificationPriority>('normal');
  const [isSending, setIsSending] = useState(false);
  const [userSearch, setUserSearch] = useState('');

  // Stats
  const revenue = orders.reduce((acc, o) => acc + o.total, 0);
  const pendingProducts = products.filter(p => p.status === 'pending');
  const trendingProductsCount = products.filter(p => p.isTrending).length;
  const pendingVendors = vendors.filter(v => !v.isApproved);
  const pendingCouriers = couriers.filter(d => d.status === 'pending');
  const activeUserCount = users.filter(u => !u.isBanned).length;

  const filteredUsersForSearch = useMemo(() => {
      if (!userSearch) return [];
      return users.filter(u => 
        u.name.toLowerCase().includes(userSearch.toLowerCase()) || 
        u.email.toLowerCase().includes(userSearch.toLowerCase())
      ).slice(0, 5);
  }, [users, userSearch]);

  const handleSendBroadcast = async () => {
      if (!bcTitle || !bcMessage) return showToast("Please fill title and message", "error");
      if (bcScope === 'individual' && !bcUserId) return showToast("Select a target user", "error");

      setIsSending(true);
      const success = await sendNotification({
          userId: bcScope === 'individual' ? bcUserId : undefined,
          targetRole: bcScope === 'role' ? bcRole : undefined,
          targetScope: bcScope,
          type: 'system',
          title: bcTitle,
          message: bcMessage,
          priority: bcPriority
      });

      if (success) {
          showToast("Broadcast sent successfully!", "success");
          setBcTitle('');
          setBcMessage('');
          setBcUserId('');
          setUserSearch('');
      } else {
          showToast("Failed to send broadcast", "error");
      }
      setIsSending(false);
  };

  const handleTestLocalNotif = () => {
      if (!('Notification' in window)) return showToast("Not supported", "error");
      if (Notification.permission !== 'granted') return showToast("Enable notifications first", "info");

      navigator.serviceWorker.ready.then(registration => {
          // Fix: Cast options to any to bypass TypeScript limitations for NotificationOptions which might lack 'vibrate' or 'badge'.
          registration.showNotification('LYNQED System Check', {
              body: 'This is a test notification from the Admin Dashboard.',
              icon: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
              badge: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
              vibrate: [100, 50, 100],
              tag: 'admin-test'
          } as any);
          showToast("Sent test alert to your device", "success");
      });
