                <div className="relative">
                    <div className="w-24 h-24 sm:w-32 sm:h-32 bg-white/5 backdrop-blur-md rounded-[2.5rem] border border-white/10 flex items-center justify-center rotate-6 group-hover:rotate-12 transition-transform duration-500 shadow-2xl">
                        <i className="fa-solid fa-store text-4xl sm:text-5xl text-white/90 drop-shadow-glow"></i>
                    </div>
                    <div className="absolute -top-2 -left-2 w-6 h-6 bg-accent rounded-lg flex items-center justify-center animate-bounce-slight shadow-lg">
