      {/* 6. Dynamic Grid */}
      <div className="px-4 pb-24">
         <div className="flex justify-between items-center mb-6">
            <h3 className="font-display font-bold text-gray-900 dark:text-white text-lg">{dynamicSectionTitle}</h3>
         </div>

         {isDataLoading ? (
             <div className="grid grid-cols-2 gap-4">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {sortedProducts.map(product => {
                    const vendor = vendors.find(v => v.vendorId === product.vendorId);
                    const isInCart = cart.some(item => item.productId === product.id);
                    const isFavorite = favorites.includes(product.id);
                    return (
                        <div key={product.id} className="bg-white dark:bg-darkSurface rounded-3xl overflow-hidden shadow-sm border border-gray-100 dark:border-gray-800 flex flex-col h-full cursor-pointer relative group transition-all hover:shadow-lg" onClick={() => navigate(`/buyer/product/${product.id}`)}>
                            <div className="aspect-square relative overflow-hidden bg-gray-50 dark:bg-darkBg/90">
