// This code runs on Supabase Edge Functions (Deno)
// Name: push-notifications
import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    // 1. Setup Supabase Client
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    )

    // 2. Get the notification data from the webhook trigger
    const { record } = await req.json()
    const { user_id, title, message, type } = record

    // 3. Fetch the user's push token from their profile
    const { data: profile } = await supabase
      .from('profiles')
      .select('push_token')
      .eq('id', user_id)
      .single()

    if (!profile?.push_token) {
      return new Response(JSON.stringify({ error: 'No push token found for user' }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      })
    }

    // 4. Parse the Firebase Service Account JSON from Secrets
    // You must set this secret in your Supabase Dashboard
    const serviceAccount = JSON.parse(Deno.env.get('FIREBASE_SERVICE_ACCOUNT') || '{}')

    // 5. Generate FCM Access Token (OAuth2)
    // Note: In a production Deno environment, we use a helper or manual JWT sign
    // For this example, we assume you've configured the FCM V1 API correctly
    const fcmToken = await getAccessToken(serviceAccount)

    // 6. Send the Push Request to FCM v1 API
    const pushPayload = JSON.parse(profile.push_token)
    const response = await fetch(
      `https://fcm.googleapis.com/v1/projects/${serviceAccount.project_id}/messages:send`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${fcmToken}`,
        },
        body: JSON.stringify({
          message: {
            token: pushPayload.endpoint, // Or the specific device token depending on library
            notification: { title, body: message },
            data: { type, click_action: '/#/buyer/orders' },
            webpush: {
              notification: {
                icon: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
                badge: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
              }
            }
          },
        }),
      }
    )

    const result = await response.json()

    return new Response(JSON.stringify(result), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    })
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 400,
    })
  }
})

