async function getAccessToken(serviceAccount: any) {
  const payload: Payload = {
    iss: serviceAccount.client_email,
    sub: serviceAccount.client_email,
    aud: "https://oauth2.googleapis.com/token",
    iat: getNumericDate(0),
    exp: getNumericDate(3600),
    scope: "https://www.googleapis.com/auth/cloud-platform",
  };

  // Convert private key string to ArrayBuffer for importing
  const pemHeader = "-----BEGIN PRIVATE KEY-----";
  const pemFooter = "-----END PRIVATE KEY-----";
  const pemContents = serviceAccount.private_key
    .replace(pemHeader, "")
    .replace(pemFooter, "")
    .replace(/\s/g, "");

  const binaryDer = Uint8Array.from(atob(pemContents), (c) => c.charCodeAt(0));

  const key = await crypto.subtle.importKey(
    "pkcs8",
    binaryDer,
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["sign"]
  );

  const jwt = await create({ alg: "RS256", typ: "JWT" }, payload, key);

  const response = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: jwt,
    }),
  });

  const data = await response.json();
  return data.access_token;
}

// This code runs on Supabase Edge Functions (Deno)
// Name: push-notifications

declare const Deno: any;

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2"
import { create, Payload, getNumericDate } from "https://deno.land/x/djwt@v2.8/mod.ts"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    )

    // Parse the payload sent by the database trigger
    const body = await req.json()
    const record = body.record

    if (!record) {
      return new Response(JSON.stringify({ error: 'No record in payload' }), { 
        status: 400, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      })
    }

    const { user_id, title, message, type } = record

    // 1. Fetch the user's push token
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('push_token')
      .eq('id', user_id)
      .single()

    if (profileError || !profile?.push_token) {
      return new Response(JSON.stringify({ error: 'Push token not found for user' }), { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      })
    }

    // 2. Prepare authentication for Google FCM
    const serviceAccount = JSON.parse(Deno.env.get('FIREBASE_SERVICE_ACCOUNT') || '{}')
    if (!serviceAccount.project_id) {
       throw new Error('FIREBASE_SERVICE_ACCOUNT secret is not configured correctly');
    }

    const fcmToken = await getAccessToken(serviceAccount)

    // 3. Extract the device token from the stored subscription string
    const sub = JSON.parse(profile.push_token)
    // For FCM, if we stored the whole sub object, we often just need the 'token' or the end of the endpoint
    const deviceToken = sub.token || sub.endpoint.split('/').pop()

    // 4. Send to Firebase Cloud Messaging v1 API
    const response = await fetch(
      `https://fcm.googleapis.com/v1/projects/${serviceAccount.project_id}/messages:send`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${fcmToken}`,
        },
        body: JSON.stringify({
          message: {
            token: deviceToken,
            notification: { 
              title: title || 'LYNQED Alert', 
              body: message 
            },
            data: { 
              type: type || 'system', 
              click_action: 'https://lynqed.shop/#/buyer/orders' 
            },
            webpush: {
              fcm_options: {
                link: 'https://lynqed.shop/#/buyer/orders'
              },
              notification: {
                icon: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
                badge: 'https://suschmjoogvoufhozbet.supabase.co/storage/v1/object/public/lynqed-assets/Lynqed_Logo.png',
              }
            }
          },
        }),
      }
    )

    const result = await response.json()
    return new Response(JSON.stringify(result), { 
      headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
    })

  } catch (error) {
    console.error('Push Error:', error.message)
    return new Response(JSON.stringify({ error: error.message }), { 
      status: 500, 
      headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
    })
  }
})

