                            {product.images.map((img, i) => (
                                <img key={i} src={img} onClick={(e) => { e.stopPropagation(); zoomGallery.setActiveIndex(i); }} className={`w-16 h-16 flex-shrink-0 rounded-xl object-contain bg-white cursor-pointer border-2 transition-all ${zoomGallery.activeIndex === i ? 'border-primary shadow-glow' : 'border-transparent opacity-30'}`} />
