    const [deliveryOption, setDeliveryOption] = useState<'delivery' | 'pickup'>('delivery');
    const [isSubmitting, setIsSubmitting] = useState(false);

    const subtotal = cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
    const deliveryFee = deliveryOption === 'delivery' ? 10 : 0;
    const total = subtotal + deliveryFee;

    if (cart.length === 0 && !isSubmitting) return <Navigate to="/buyer/dashboard" />;

    const handleConfirmOrder = async () => {
        if (!currentUser?.address && deliveryOption === 'delivery') {
            showToast("Please add an address in Profile first.", "error");
            navigate('/buyer/profile');
