        const items = byVendor[vid];
        const subtotal = items.reduce((s: number, i: any) => s + i.product.price * i.quantity, 0);
        const { data: orderData, error } = await supabase.from('orders').insert({
          buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal + fee,
          delivery_fee: fee, status: 'placed', delivery_option: option,
          location_coordinates: resolveCoordinates(currentUser.address || 'campus')
        }).select().single();
        if (error) throw error;
      }
      showToast("Order Placed!", "success");
      clearCart();
    } catch (e) {
      showToast("Failed to place order", "error");
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    await supabase.from('orders').update({ status }).eq('id', orderId);
    showToast(`Order status: ${status}`, 'info');
    fetchGlobalData();
  };

  const toggleFavorite = useCallback((pid: string) => {
    const isRem = favorites.includes(pid);
    setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]);
    showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success');
  }, [favorites, showToast]);

  const requestNotificationPermission = async () => {
    if (!('Notification' in window)) return false;
    const permission = await Notification.requestPermission();
    if (permission === 'granted' && 'serviceWorker' in navigator) {
      const registration = await navigator.serviceWorker.ready;
      const vapidKey = 'BF1eh32QaHeoxYyO8O9HzxWKpjYo_UN72YDBxiPvfMRL9IfFQEKGwa0c3AtxSen25ueyko62rnDO1BX-_9d9QGQ';
      try {
        const subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(vapidKey)
        });
        if (currentUser) await updateProfile({ pushToken: JSON.stringify(subscription) });
        setIsPushActive(true);
        showToast("Push Active!", "success");
        return true;
      } catch (e) { console.error("Sub error", e); }
    }
    return false;
  };

  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('lynqed_cart') || '[]'));
  const [favorites, setFavorites] = useState<string[]>(() => JSON.parse(localStorage.getItem('lynqed_favs') || '[]'));

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  // --- Other Actions ---
  const markNotificationRead = async (id: string) => { await supabase.from('notifications').update({ is_read: true }).eq('id', id); };
  const deleteNotification = async (id: string) => { await supabase.from('notifications').delete().eq('id', id); };
  const uploadFile = async (file: File, folder: string) => {
    const name = `${Math.random().toString(36).substring(7)}_${Date.now()}`;
    const { data, error } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${name}`, file);
    if (error) return null;
    return supabase.storage.from('lynqed-assets').getPublicUrl(data.path).data.publicUrl;
  };

  const registerVendor = async (data: any) => {
    if (!currentUser) return { success: false };
    const { error } = await supabase.from('vendors').upsert({
      user_id: currentUser.id, store_name: data.storeName, store_description: data.storeDescription,
      location: data.location, contact_phone: data.contactPhone, store_avatar_url: data.storeAvatarUrl,
      vendor_id: `v-${currentUser.id.substring(0, 5)}`
    });
    if (!error) {
      if (!currentUser.roles.includes('vendor')) {
        await supabase.from('profiles').update({ roles: [...currentUser.roles, 'vendor'] }).eq('id', currentUser.id);
      }
      return { success: true };
    }
    return { success: false };
  };

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount,
    isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, switchRole, updateTheme, toggleThemeSwitching, updateProfile, 
    uploadFile, registerVendor, addToCart, updateCartQuantity, removeFromCart, clearCart, 
    placeOrder, updateOrderStatus, toggleFavorite, markNotificationRead, deleteNotification,
    requestNotificationPermission, refreshData: fetchGlobalData,
    addProduct: async () => true, // Placeholder to match type
    updateProduct: async () => {}, // Placeholder to match type
    updateProductStatus: async () => {}, // Placeholder to match type
    toggleTrendingStatus: async () => {}, // Placeholder to match type
    deleteProduct: async () => {}, // Placeholder to match type
    markAllNotificationsRead: async () => {}, // Placeholder
    sendNotification: async () => true, // Placeholder
    submitReview: async () => true, // Placeholder
    banUser: async () => {}, // Placeholder
    deleteUser: async () => {}, // Placeholder
    approveVendor: async () => {}, // Placeholder
    approveCourier: async () => {}, // Placeholder
    toggleDriverStatus: async () => {}, // Placeholder
    updateDriverLocation: async () => {}, // Placeholder
    submitContactMessage: async () => ({ success: true }), // Placeholder
    requestPayout: async () => ({ success: true }), // Placeholder
    registerCourier: async () => ({ success: true }), // Placeholder
    installApp: () => {}, // Placeholder
    showToast, hideToast, deferredPrompt, isIOS, isStandalone, isPushActive
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, favorites, toast, theme, isPushActive, addToCart, removeFromCart, updateCartQuantity, toggleFavorite, showToast, hideToast]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, AppNotification, Review } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE, UPSA_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: AppNotification[];
  reviews: Review[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;
  deferredPrompt: any; 
  isIOS: boolean;
  isStandalone: boolean;
  isPushActive: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<AppNotification>) => Promise<boolean>;

  submitReview: (review: Omit<Review, 'createdAt' | 'user'>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
  installApp: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`LocalStorage quota exceeded.`); }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

function urlBase64ToUint8Array(base64String: string) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/\-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) { outputArray[i] = rawData.charCodeAt(i); }
  return outputArray;
}

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Core States ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true); // Initial boot loading
  const [isDataLoading, setIsDataLoading] = useState<boolean>(false); // Data background loading
  const [connectionError, setConnectionError] = useState<boolean>(false);

  // --- Data States ---
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);

  // --- PERSISTENT DATA STATES (Moved up to fix "used before declaration" error) ---
  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('lynqed_cart') || '[]'));
  const [favorites, setFavorites] = useState<string[]>(() => JSON.parse(localStorage.getItem('lynqed_favs') || '[]'));

  // --- App States ---
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isPushActive, setIsPushActive] = useState(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const isStandalone = useMemo(() => window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone === true, []);
  const isIOS = useMemo(() => /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream, []);

  const [currentRole, setCurrentRole] = useState<Role>(() => (localStorage.getItem('lynqed_role') as Role) || 'guest');
  const [theme, setTheme] = useState<ThemeMode>(() => (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system');
  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => localStorage.getItem('lynqed_sys_theme_allowed') !== 'false');

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  // --- Theme Sync ---
  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (!isThemeSwitchingAllowed) root.classList.remove('dark');
    else isDark ? root.classList.add('dark') : root.classList.remove('dark');
  }, [theme, isThemeSwitchingAllowed]);

  // --- Data Fetchers ---
  const fetchGlobalData = useCallback(async () => {
    try {
      setIsDataLoading(true);
      const [pRes, vRes, oRes, cRes] = await Promise.all([
        supabase.from('products').select('*').order('created_at', { ascending: false }),
        supabase.from('vendors').select('*'),
        supabase.from('orders').select('*').order('created_at', { ascending: false }),
        supabase.from('couriers').select('*')
      ]);

      if (pRes.data) setProducts(pRes.data.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
      if (vRes.data) setVendors(vRes.data.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone, campus: v.campus })));
      if (oRes.data) setOrders(oRes.data.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
      if (cRes.data) setCouriers(cRes.data.map((d: any) => ({ ...d, userId: d.user_id, fullName: 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
    } catch (e) {
      console.error("Data fetch error", e);
    } finally {
      setIsDataLoading(false);
    }
  }, []);

  const fetchUserScopedData = useCallback(async (userId: string, role: Role) => {
    try {
      const [nRes, rRes] = await Promise.all([
        supabase.from('notifications').select('*').or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`).order('created_at', { ascending: false }),
        supabase.from('reviews').select('*, profiles(name, avatar_url)').order('created_at', { ascending: false })
      ]);

      if (nRes.data) {
        const filteredNotifs = nRes.data.filter(n => n.target_scope !== 'role' || n.target_role === role);
        setNotifications(filteredNotifs.map(n => ({
          ...n, userId: n.user_id, targetRole: n.target_role, targetScope: n.target_scope, 
          relatedId: n.related_id, isRead: n.is_read, createdAt: n.created_at
        })));
      }
      if (rRes.data) {
        setReviews(rRes.data.map(r => ({
          ...r, productId: r.product_id, vendorId: r.vendor_id, userId: r.user_id, createdAt: r.created_at,
          user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
        })));
      }
    } catch (e) { console.warn("Scoped fetch error", e); }
  }, []);

  const checkPushStatus = useCallback(async () => {
    if ('serviceWorker' in navigator && 'PushManager' in window) {
      try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();
        setIsPushActive(!!subscription);
      } catch (e) { console.warn("Push check failed", e); }
    }
  }, []);

  // --- Initial Boot Logic ---
  useEffect(() => {
    let isMounted = true;

    const bootApp = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && isMounted) {
          const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
          if (profile) {
            const user: User = { 
              ...profile, roles: profile.roles || ['buyer'], avatarUrl: profile.avatar_url, 
              phoneNumber: profile.phone_number, defaultLocation: profile.address, pushToken: profile.push_token 
            };
            setCurrentUser(user);
            fetchUserScopedData(user.id, currentRole);
          }
        }
        await fetchGlobalData();
        await checkPushStatus();
      } catch (e) {
        console.error("Boot error", e);
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };

    bootApp();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
        if (profile) {
          setCurrentUser({ ...profile, roles: profile.roles || ['buyer'], avatarUrl: profile.avatar_url });
          fetchUserScopedData(session.user.id, currentRole);
        }
      } else if (event === 'SIGNED_OUT') {
        setCurrentUser(null);
        setCurrentRole('guest');
        setNotifications([]);
      }
    });

    return () => {
      isMounted = false;
      subscription.unsubscribe();
    };
  }, []); // Run once on mount

  // --- Realtime Subscriptions ---
  useEffect(() => {
    if (isLoading) return;

    const channels = [
      supabase.channel('products-db').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, fetchGlobalData),
      supabase.channel('orders-db').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, fetchGlobalData),
      supabase.channel('vendors-db').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, fetchGlobalData),
      supabase.channel('reviews-db').on('postgres_changes', { event: '*', schema: 'public', table: 'reviews' }, () => currentUser && fetchUserScopedData(currentUser.id, currentRole)),
      supabase.channel('notifs-db').on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => currentUser && fetchUserScopedData(currentUser.id, currentRole))
    ];

    channels.forEach(c => c.subscribe());
    return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [isLoading, currentUser, currentRole, fetchGlobalData, fetchUserScopedData]);

  // --- Actions ---
  const login = async (email: string, pass: string) => {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
    if (error) return { success: false, error: error.message };
    if (data.user) {
      const { data: profile } = await supabase.from('profiles').select('*').eq('id', data.user.id).single();
      const roles = profile?.roles || ['buyer'];
      const roleToSet: Role = roles.includes('admin') ? 'admin' : (roles.includes('vendor') ? 'vendor' : 'buyer');
      setCurrentRole(roleToSet);
      safeSetItem('lynqed_role', roleToSet);
      return { success: true, role: roleToSet };
    }
    return { success: false };
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setCurrentRole('guest');
    localStorage.removeItem('lynqed_role');
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
    const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
    if (error) return { success: false, error: error.message };
    if (data.user) {
      await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
      return await login(email, password);
    }
    return { success: false };
  };

  // --- Added missing functions for password management ---
  const resetPassword = useCallback(async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/#/update-password`,
    });
    if (error) return { success: false, error: error.message };
    return { success: true };
  }, []);

  const updatePassword = useCallback(async (password: string) => {
    const { error } = await supabase.auth.updateUser({ password });
    if (error) return { success: false, error: error.message };
    return { success: true };
  }, []);

  const switchRole = (role: Role) => {
    if (currentUser?.roles.includes(role)) {
      setCurrentRole(role);
      safeSetItem('lynqed_role', role);
      showToast(`Switched to ${role} Mode`, 'info');
      if (currentUser) fetchUserScopedData(currentUser.id, role);
    }
  };

  // --- Added missing theme management functions ---
  const updateTheme = useCallback((t: ThemeMode) => {
    setTheme(t);
    safeSetItem('lynqed_theme_last', t);
  }, []);

  const toggleThemeSwitching = useCallback((allowed: boolean) => {
    setIsThemeSwitchingAllowed(allowed);
    safeSetItem('lynqed_sys_theme_allowed', allowed.toString());
  }, []);

  const updateProfile = async (data: Partial<User>) => {
    if (!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ 
      name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, 
      address: data.address, push_token: data.pushToken 
    }).eq('id', currentUser.id);
    if (!error) {
      setCurrentUser(prev => prev ? { ...prev, ...data } : null);
      showToast("Profile Updated", "success");
      return { success: true };
    }
    return { success: false };
  };

  const addToCart = useCallback((p: Product, q = 1) => {
    setCart(prev => {
      const ex = prev.find(i => i.productId === p.id);
      if (ex) return prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i);
      return [...prev, { productId: p.id, quantity: q, product: p }];
    });
    showToast(`Added ${p.title}`, 'success');
  }, [showToast]);

  const removeFromCart = useCallback((pid: string) => {
    setCart(prev => prev.filter(i => i.productId !== pid));
    showToast("Removed from cart", "info");
  }, [showToast]);

  const updateCartQuantity = useCallback((pid: string, qty: number) => {
    if (qty <= 0) removeFromCart(pid);
    else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  }, [removeFromCart]);

  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery' | 'pickup', fee = 0) => {
    if (!currentUser) return;
    const byVendor: any = {};
    cart.forEach(i => {
      if (!byVendor[i.product.vendorId]) byVendor[i.product.vendorId] = [];
      byVendor[i.product.vendorId].push(i);
    });

    try {
      for (const vid in byVendor) {
        const items = byVendor[vid];
        const subtotal = items.reduce((s: number, i: any) => s + i.product.price * i.quantity, 0);
        const { data: orderData, error } = await supabase.from('orders').insert({
          buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal + fee,
          delivery_fee: fee, status: 'placed', delivery_option: option,
          location_coordinates: resolveCoordinates(currentUser.address || 'campus')
        }).select().single();
        if (error) throw error;
      }
      showToast("Order Placed!", "success");
      clearCart();
    } catch (e) {
      showToast("Failed to place order", "error");
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    await supabase.from('orders').update({ status }).eq('id', orderId);
    showToast(`Order status: ${status}`, 'info');
    fetchGlobalData();
  };

  // --- Added missing assignDelivery function ---
  const assignDelivery = useCallback(async (orderId: string) => {
    if (!currentUser) return;
    const { error } = await supabase.from('orders').update({ 
      courier_id: currentUser.id, 
      status: 'courier_assigned' 
    }).eq('id', orderId);
    if (!error) {
      showToast("Delivery Assigned", "success");
      fetchGlobalData();
    } else {
      showToast("Failed to assign delivery", "error");
    }
  }, [currentUser, showToast, fetchGlobalData]);

  const toggleFavorite = useCallback((pid: string) => {
    const isRem = favorites.includes(pid);
    setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]);
    showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success');
  }, [favorites, showToast]);

  const requestNotificationPermission = async () => {
    if (!('Notification' in window)) return false;
    const permission = await Notification.requestPermission();
    if (permission === 'granted' && 'serviceWorker' in navigator) {
      const registration = await navigator.serviceWorker.ready;
      const vapidKey = 'BF1eh32QaHeoxYyO8O9HzxWKpjYo_UN72YDBxiPvfMRL9IfFQEKGwa0c3AtxSen25ueyko62rnDO1BX-_9d9QGQ';
      try {
        const subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(vapidKey)
        });
        if (currentUser) await updateProfile({ pushToken: JSON.stringify(subscription) });
        setIsPushActive(true);
        showToast("Push Active!", "success");
        return true;
      } catch (e) { console.error("Sub error", e); }
    }
    return false;
  };

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  // --- Other Actions ---
  const markNotificationRead = async (id: string) => { await supabase.from('notifications').update({ is_read: true }).eq('id', id); };
  const deleteNotification = async (id: string) => { await supabase.from('notifications').delete().eq('id', id); };
  const uploadFile = async (file: File, folder: string) => {
    const name = `${Math.random().toString(36).substring(7)}_${Date.now()}`;
    const { data, error } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${name}`, file);
    if (error) return null;
    return supabase.storage.from('lynqed-assets').getPublicUrl(data.path).data.publicUrl;
  };

  const registerVendor = async (data: any) => {
    if (!currentUser) return { success: false };
    const { error } = await supabase.from('vendors').upsert({
      user_id: currentUser.id, store_name: data.storeName, store_description: data.storeDescription,
      location: data.location, contact_phone: data.contactPhone, store_avatar_url: data.storeAvatarUrl,
      vendor_id: `v-${currentUser.id.substring(0, 5)}`
    });
    if (!error) {
      if (!currentUser.roles.includes('vendor')) {
        await supabase.from('profiles').update({ roles: [...currentUser.roles, 'vendor'] }).eq('id', currentUser.id);
      }
      return { success: true };
    }
    return { success: false };
  };

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount,
    isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching, updateProfile, 
    uploadFile, registerVendor, addToCart, updateCartQuantity, removeFromCart, clearCart, 
    placeOrder, updateOrderStatus, assignDelivery, toggleFavorite, markNotificationRead, deleteNotification,
    requestNotificationPermission, refreshData: fetchGlobalData,
    addProduct: async () => true, // Placeholder to match type
    updateProduct: async () => {}, // Placeholder to match type
    updateProductStatus: async () => {}, // Placeholder to match type
    toggleTrendingStatus: async () => {}, // Placeholder to match type
    deleteProduct: async () => {}, // Placeholder to match type
    markAllNotificationsRead: async () => {}, // Placeholder
    sendNotification: async () => true, // Placeholder
    submitReview: async () => true, // Placeholder
    banUser: async () => {}, // Placeholder
    deleteUser: async () => {}, // Placeholder
    approveVendor: async () => {}, // Placeholder
    approveCourier: async () => {}, // Placeholder
    toggleDriverStatus: async () => {}, // Placeholder
    updateDriverLocation: async () => {}, // Placeholder
    submitContactMessage: async () => ({ success: true }), // Placeholder
    requestPayout: async () => ({ success: true }), // Placeholder
    registerCourier: async () => ({ success: true }), // Placeholder
    installApp: () => {}, // Placeholder
    showToast, hideToast, deferredPrompt, isIOS, isStandalone, isPushActive
  }), [
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, 
    isLoading, isDataLoading, favorites, toast, theme, isPushActive, addToCart, removeFromCart, updateCartQuantity, 
    toggleFavorite, showToast, hideToast, fetchGlobalData, resetPassword, updatePassword, assignDelivery, 
    updateTheme, toggleThemeSwitching, deferredPrompt, isIOS, isStandalone
  ]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, Notification, Review } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE, UPSA_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  reviews: Review[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<Notification>) => Promise<boolean>;

  submitReview: (review: Omit<Review, 'createdAt' | 'user'>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded.`);
    }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Core Loading States
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(false);
  const [connectionError, setConnectionError] = useState<boolean>(false);

  // App/User States
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // UI States
  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });
  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  // Theme Sync
  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (!isThemeSwitchingAllowed) {
        root.classList.remove('dark');
    } else {
        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');
    }
  }, [theme, isThemeSwitchingAllowed]);

  // Persistent Storage Sync
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // --- Data Fetchers ---
  const fetchNotifications = useCallback(async (userId: string, role: Role) => {
      if (!userId) return;
      try {
          const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`)
            .order('created_at', { ascending: false });

          if (!error && data) {
              const filtered = data.filter(n => n.target_scope !== 'role' || n.target_role === role);
              setNotifications(filtered.map(n => ({
                  ...n, userId: n.user_id, targetRole: n.target_role,
                  targetScope: n.target_scope, relatedId: n.related_id,
                  isRead: n.is_read, createdAt: n.created_at
              })));
          }
      } catch (e) { console.warn("Notif fetch error", e); }
  }, []);

  const fetchReviews = useCallback(async () => {
    try {
        const { data, error } = await supabase
            .from('reviews')
            .select('*, profiles(name, avatar_url)')
            .order('created_at', { ascending: false });
        if (data && !error) {
            setReviews(data.map(r => ({
                ...r, productId: r.product_id, vendorId: r.vendor_id,
                userId: r.user_id, createdAt: r.created_at,
                user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
            })));
        }
    } catch (e) { console.warn("Review fetch error", e); }
  }, []);

  const fetchData = useCallback(async () => {
      try {
          setIsDataLoading(true);
          const [pData, vData, oData, cDataRaw, uData] = await Promise.all([
              supabase.from('products').select('*').order('created_at', { ascending: false }),
              supabase.from('vendors').select('*'),
              supabase.from('orders').select('*').order('created_at', { ascending: false }),
              supabase.from('couriers').select('*'),
              supabase.from('profiles').select('*')
          ]);

          if (pData.data) setProducts(pData.data.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
          if (vData.data) setVendors(vData.data.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone, campus: v.campus })));
          if (oData.data) setOrders(oData.data.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
          if (cDataRaw.data && uData.data) {
              const profileMap = new Map(uData.data.map((p: any) => [p.id, p]));
              setCouriers(cDataRaw.data.map((d: any) => ({ ...d, userId: d.user_id, fullName: (profileMap.get(d.user_id) as any)?.name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
          }
          if (uData.data) setUsers(uData.data as any);
      } catch (e) { 
          console.error("Data fetch error", e); 
      } finally { 
          setIsDataLoading(false); 
      }
  }, []);

  const fetchUserProfile = async (userId: string): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;
          if (data) {
              const user: User = { 
                  ...data, roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url, phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };
              setCurrentUser(user);
              return user;
          }
      } catch (e) { console.error("Profile fetch error", e); }
      return null;
  };

  // --- Boot Logic ---
  useEffect(() => {
    let isMounted = true;

    const initialize = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && isMounted) {
          const profile = await fetchUserProfile(session.user.id);
          if (profile) {
            fetchNotifications(session.user.id, currentRole);
          }
        }
        await Promise.all([fetchData(), fetchReviews()]);
      } catch (e) {
        console.error("Boot error", e);
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };

    initialize();

    // Listen for Auth Changes to update UI state globally
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' && session?.user) {
            const profile = await fetchUserProfile(session.user.id);
            if (profile) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                const finalRole: Role = (persistedRole && profile.roles.includes(persistedRole)) 
                    ? persistedRole 
                    : (profile.roles.includes('admin') ? 'admin' : (profile.roles.includes('vendor') ? 'vendor' : 'buyer'));
                setCurrentRole(finalRole);
                fetchNotifications(session.user.id, finalRole);
            }
        } else if (event === 'SIGNED_OUT') {
            setCurrentUser(null);
            setCurrentRole('guest');
            setNotifications([]);
        }
    });

    return () => {
      isMounted = false;
      subscription.unsubscribe();
    };
  }, []); // Run once on mount

  // Realtime Subscriptions
  useEffect(() => {
      if (isLoading) return;
      const channels = [
          supabase.channel('p-db').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, fetchData).subscribe(),
          supabase.channel('o-db').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, fetchData).subscribe(),
          supabase.channel('v-db').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, fetchData).subscribe(),
          supabase.channel('r-db').on('postgres_changes', { event: '*', schema: 'public', table: 'reviews' }, fetchReviews).subscribe()
      ];
      return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [isLoading, fetchData, fetchReviews]);

  // --- Methods ---

  const sendNotification = useCallback(async (payload: Partial<Notification>) => {
    try {
        const { error } = await supabase.from('notifications').insert({
            user_id: payload.userId || null,
            target_role: payload.targetRole || null,
            target_scope: payload.targetScope || 'individual',
            type: payload.type || 'system',
            title: payload.title || 'Notification',
            message: payload.message || '',
            related_id: payload.relatedId || null,
            priority: payload.priority || 'normal',
            is_read: false
        });
        if (error) throw error;
        return true;
    } catch (e: any) {
        console.error("Notification dispatch failed:", e.message || e);
        return false;
    }
  }, []);

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      return { success: true, role: currentRole }; // Role will be synced by onAuthStateChange
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
           return await login(email, password); 
      }
      return { success: false };
  };

  const logout = async () => { 
      await supabase.auth.signOut(); 
  };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) { 
          setCurrentRole(role); 
          safeSetItem('lynqed_role', role); 
          showToast(`Switched to ${role} Mode`, 'info'); 
          if (currentUser) fetchNotifications(currentUser.id, role);
      }
  };

  const updateProfile = async (data: Partial<User>) => {
    if(!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address }).eq('id', currentUser.id);
    if(!error) { showToast("Profile updated", "success"); fetchUserProfile(currentUser.id); return { success: true }; }
    return { success: false };
  };

  const updateTheme = (t: ThemeMode) => { setTheme(t); safeSetItem('lynqed_theme_last', t); };
  const toggleThemeSwitching = (allowed: boolean) => { setIsThemeSwitchingAllowed(allowed); safeSetItem('lynqed_sys_theme_allowed', String(allowed)); };
  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` });
      return { success: !error, error: error?.message };
  };
  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      return { success: !error, error: error?.message };
  };

  const addToCart = useCallback((p: Product, q = 1) => { setCart(prev => { const x = prev.find(i => i.productId === p.id); return x ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; }); showToast(`Added ${p.title}`, "success"); }, [showToast]);
  const removeFromCart = useCallback((pid: string) => { setCart(prev => prev.filter(i => i.productId !== pid)); showToast("Removed", "info"); }, [showToast]);
  const updateCartQuantity = useCallback((pid: string, qty: number) => { if(qty <= 0) removeFromCart(pid); else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } }, [removeFromCart]);
  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, 
                  delivery_fee: fee, status: 'placed', delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();
              if (error) throw error;
              if (vendor) await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order Received!', message: `New order for ₵${(subtotal+fee).toFixed(2)}.`, relatedId: data.id, priority: 'high' });
              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', orderId); 
      if (!error) {
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: ${status.replace('_', ' ')}.`, relatedId: orderId });
          }
          fetchData(); 
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); 
      if (!error) fetchData();
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type });
      if(!error) { fetchData(); return { success: true }; }
      return { success: false };
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { showToast('Upload failed', 'error'); return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;
      const { error } = await supabase.from('vendors').upsert({ vendor_id: vid, user_id: currentUser.id, store_name: data.store_name, store_description: data.store_description, location: data.location, contact_phone: data.contact_phone, store_avatar_url: data.store_avatar_url, is_approved: ex ? ex.isApproved : false, rating: ex ? ex.rating : 5.0, campus: data.campus }, { onConflict: 'user_id' });
      if (!error) {
          if (!currentUser.roles.includes('vendor')) await supabase.from('profiles').update({ roles: [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])] }).eq('id', currentUser.id);
          fetchData(); return { success: true };
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, campus: v.campus, contact_phone: prod.contact_phone });
      if (!error) { showToast("Submitted", "success"); fetchData(); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id); fetchData(); };
  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };
  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { await supabase.from('products').update({ is_trending: isTrending }).eq('id', id); fetchData(); };
  const toggleFavorite = useCallback((pid: string) => { const isRem = favorites.includes(pid); setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success'); }, [favorites, showToast]);
  const markNotificationRead = async (id: string) => { setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n)); await supabase.from('notifications').update({ is_read: true }).eq('id', id); };
  const markAllNotificationsRead = async () => { if (!currentUser) return; setNotifications(prev => prev.map(n => ({ ...n, isRead: true }))); await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id).eq('is_read', false); };
  const deleteNotification = async (id: string) => { setNotifications(prev => prev.filter(n => n.id !== id)); await supabase.from('notifications').delete().eq('id', id); };
  const submitReview = useCallback(async (review: Omit<Review, 'createdAt' | 'user'>) => { try { const { error } = await supabase.from('reviews').upsert({ id: review.id || undefined, product_id: review.productId, vendor_id: review.vendorId, user_id: review.userId, rating: review.rating, comment: review.comment, images: review.images }); if (error) throw error; showToast("Review submitted!", "success"); fetchReviews(); return true; } catch (e) { showToast("Failed to submit review", "error"); return false; } }, [showToast, fetchReviews]);
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); if (status === 'approved') { const profile = users.find(u => u.id === userId); if (profile) await supabase.from('profiles').update({ roles: [...new Set([...profile.roles, 'courier' as Role, 'buyer' as Role])] }).eq('id', userId); } fetchData(); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchData(); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); fetchData(); };
  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };
  const requestNotificationPermission = async () => true;

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData: fetchData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, submitReview, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast, requestNotificationPermission
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, addToCart, removeFromCart, updateCartQuantity, fetchData, sendNotification, submitReview, toggleFavorite]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, Notification, Review } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE, UPSA_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  reviews: Review[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<Notification>) => Promise<boolean>;

  submitReview: (review: Omit<Review, 'createdAt' | 'user'>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`LocalStorage quota exceeded.`); }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Core Loading States
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(false);
  const [connectionError, setConnectionError] = useState<boolean>(false);

  // App/User States
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // UI States
  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });
  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  // Theme Sync
  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (!isThemeSwitchingAllowed) {
        root.classList.remove('dark');
    } else {
        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');
    }
  }, [theme, isThemeSwitchingAllowed]);

  // Persistent Storage Sync
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // --- Data Fetchers ---
  const fetchNotifications = useCallback(async (userId: string, role: Role) => {
      if (!userId) return;
      try {
          const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`)
            .order('created_at', { ascending: false });

          if (!error && data) {
              const filtered = data.filter(n => n.target_scope !== 'role' || n.target_role === role);
              setNotifications(filtered.map(n => ({
                  ...n, userId: n.user_id, targetRole: n.target_role,
                  targetScope: n.target_scope, relatedId: n.related_id,
                  isRead: n.is_read, createdAt: n.created_at
              })));
          }
      } catch (e) { console.warn("Notif fetch error", e); }
  }, []);

  const fetchReviews = useCallback(async () => {
    try {
        const { data, error } = await supabase
            .from('reviews')
            .select('*, profiles(name, avatar_url)')
            .order('created_at', { ascending: false });
        if (data && !error) {
            setReviews(data.map(r => ({
                ...r, productId: r.product_id, vendorId: r.vendor_id,
                userId: r.user_id, createdAt: r.created_at,
                user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
            })));
        }
    } catch (e) { console.warn("Review fetch error", e); }
  }, []);

  const fetchData = useCallback(async () => {
      try {
          setIsDataLoading(true);
          const [pData, vData, oData, cDataRaw, uData] = await Promise.all([
              supabase.from('products').select('*').order('created_at', { ascending: false }),
              supabase.from('vendors').select('*'),
              supabase.from('orders').select('*').order('created_at', { ascending: false }),
              supabase.from('couriers').select('*'),
              supabase.from('profiles').select('*')
          ]);

          if (pData.data) setProducts(pData.data.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
          if (vData.data) setVendors(vData.data.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone, campus: v.campus })));
          if (oData.data) setOrders(oData.data.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
          if (cDataRaw.data && uData.data) {
              const profileMap = new Map(uData.data.map((p: any) => [p.id, p]));
              setCouriers(cDataRaw.data.map((d: any) => ({ ...d, userId: d.user_id, fullName: (profileMap.get(d.user_id) as any)?.name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
          }
          if (uData.data) setUsers(uData.data as any);
      } catch (e) { 
          console.error("Data fetch error", e); 
      } finally { 
          setIsDataLoading(false); 
      }
  }, []);

  const fetchUserProfile = async (userId: string): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;
          if (data) {
              const user: User = { 
                  ...data, roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url, phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };
              setCurrentUser(user);
              return user;
          }
      } catch (e) { console.error("Profile fetch error", e); }
      return null;
  };

  // --- Boot Logic ---
  useEffect(() => {
    let isMounted = true;

    const initialize = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && isMounted) {
          const profile = await fetchUserProfile(session.user.id);
          if (profile) {
            fetchNotifications(session.user.id, currentRole);
          }
        }
        await Promise.all([fetchData(), fetchReviews()]);
      } catch (e) {
        console.error("Boot error", e);
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };

    initialize();

    // Listen for Auth Changes to update UI state globally
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' && session?.user) {
            const profile = await fetchUserProfile(session.user.id);
            if (profile) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                const finalRole: Role = (persistedRole && profile.roles.includes(persistedRole)) 
                    ? persistedRole 
                    : (profile.roles.includes('admin') ? 'admin' : (profile.roles.includes('vendor') ? 'vendor' : 'buyer'));
                setCurrentRole(finalRole);
                fetchNotifications(session.user.id, finalRole);
            }
        } else if (event === 'SIGNED_OUT') {
            setCurrentUser(null);
            setCurrentRole('guest');
            setNotifications([]);
        }
    });

    return () => {
      isMounted = false;
      subscription.unsubscribe();
    };
  }, []); // Run once on mount

  // Realtime Subscriptions
  useEffect(() => {
      if (isLoading) return;
      const channels = [
          supabase.channel('p-db').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, fetchData).subscribe(),
          supabase.channel('o-db').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, fetchData).subscribe(),
          supabase.channel('v-db').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, fetchData).subscribe(),
          supabase.channel('r-db').on('postgres_changes', { event: '*', schema: 'public', table: 'reviews' }, fetchReviews).subscribe()
      ];
      return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [isLoading, fetchData, fetchReviews]);

  // --- Methods ---

  const sendNotification = useCallback(async (payload: Partial<Notification>) => {
    try {
        const { error } = await supabase.from('notifications').insert({
            user_id: payload.userId || null,
            target_role: payload.targetRole || null,
            target_scope: payload.targetScope || 'individual',
            type: payload.type || 'system',
            title: payload.title || 'Notification',
            message: payload.message || '',
            related_id: payload.relatedId || null,
            priority: payload.priority || 'normal',
            is_read: false
        });

        // Handle common backend configuration errors gracefully
        if (error) {
            // Code 42883 is "Undefined Function", usually meaning net.http_post extension is missing
            if (error.code === '42883') {
                console.warn("Backend Notification Trigger Error: 'pg_net' extension not enabled in Supabase. In-app notification saved, but external push failed.");
                return true; // Return true because the row was still inserted, only the trigger failed
            }
            throw error;
        }
        return true;
    } catch (e: any) {
        console.error("Notification dispatch failed:", e.message || e);
        return false;
    }
  }, []);

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      return { success: true, role: currentRole }; 
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
           return await login(email, password); 
      }
      return { success: false };
  };

  const logout = async () => { await supabase.auth.signOut(); };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) { 
          setCurrentRole(role); 
          safeSetItem('lynqed_role', role); 
          showToast(`Switched to ${role} Mode`, 'info'); 
          if (currentUser) fetchNotifications(currentUser.id, role);
      }
  };

  const updateProfile = async (data: Partial<User>) => {
    if(!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address }).eq('id', currentUser.id);
    if(!error) { showToast("Profile updated", "success"); fetchUserProfile(currentUser.id); return { success: true }; }
    return { success: false };
  };

  const updateTheme = (t: ThemeMode) => { setTheme(t); safeSetItem('lynqed_theme_last', t); };
  const toggleThemeSwitching = (allowed: boolean) => { setIsThemeSwitchingAllowed(allowed); safeSetItem('lynqed_sys_theme_allowed', String(allowed)); };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` });
      return { success: !error, error: error?.message };
  };

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      return { success: !error, error: error?.message };
  };

  const addToCart = useCallback((p: Product, q = 1) => { 
      setCart(prev => { 
          const x = prev.find(i => i.productId === p.id); 
          return x ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; 
      }); 
      showToast(`Added ${p.title}`, "success"); 
  }, [showToast]);

  const removeFromCart = useCallback((pid: string) => { 
      setCart(prev => prev.filter(i => i.productId !== pid)); 
      showToast("Removed", "info"); 
  }, [showToast]);

  const updateCartQuantity = useCallback((pid: string, qty: number) => { 
      if(qty <= 0) removeFromCart(pid); 
      else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } 
  }, [removeFromCart]);

  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, 
                  delivery_fee: fee, status: 'placed', delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();
              if (error) throw error;
              if (vendor) await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order Received!', message: `New order for ₵${(subtotal+fee).toFixed(2)}.`, relatedId: data.id, priority: 'high' });
              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', orderId); 
      if (!error) {
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: ${status.replace('_', ' ')}.`, relatedId: orderId });
          }
          fetchData(); 
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); 
      if (!error) fetchData();
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type });
      if(!error) { fetchData(); return { success: true }; }
      return { success: false };
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { showToast('Upload failed', 'error'); return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;
      const { error } = await supabase.from('vendors').upsert({ vendor_id: vid, user_id: currentUser.id, store_name: data.store_name, store_description: data.store_description, location: data.location, contact_phone: data.contact_phone, store_avatar_url: data.store_avatar_url, is_approved: ex ? ex.isApproved : false, rating: ex ? ex.rating : 5.0, campus: data.campus }, { onConflict: 'user_id' });
      if (!error) {
          if (!currentUser.roles.includes('vendor')) await supabase.from('profiles').update({ roles: [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])] }).eq('id', currentUser.id);
          fetchData(); return { success: true };
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, campus: v.campus, contact_phone: prod.contact_phone });
      if (!error) { showToast("Submitted", "success"); fetchData(); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id); fetchData(); };
  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };
  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { await supabase.from('products').update({ is_trending: isTrending }).eq('id', id); fetchData(); };
  const toggleFavorite = useCallback((pid: string) => { const isRem = favorites.includes(pid); setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success'); }, [favorites, showToast]);
  const markNotificationRead = async (id: string) => { setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n)); await supabase.from('notifications').update({ is_read: true }).eq('id', id); };
  const markAllNotificationsRead = async () => { if (!currentUser) return; setNotifications(prev => prev.map(n => ({ ...n, isRead: true }))); await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id).eq('is_read', false); };
  const deleteNotification = async (id: string) => { setNotifications(prev => prev.filter(n => n.id !== id)); await supabase.from('notifications').delete().eq('id', id); };
  const submitReview = useCallback(async (review: Omit<Review, 'createdAt' | 'user'>) => { try { const { error } = await supabase.from('reviews').upsert({ id: review.id || undefined, product_id: review.productId, vendor_id: review.vendorId, user_id: review.userId, rating: review.rating, comment: review.comment, images: review.images }); if (error) throw error; showToast("Review submitted!", "success"); fetchReviews(); return true; } catch (e) { showToast("Failed to submit review", "error"); return false; } }, [showToast, fetchReviews]);
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); if (status === 'approved') { const profile = users.find(u => u.id === userId); if (profile) await supabase.from('profiles').update({ roles: [...new Set([...profile.roles, 'courier' as Role, 'buyer' as Role])] }).eq('id', userId); } fetchData(); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchData(); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); fetchData(); };
  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };
  const requestNotificationPermission = async () => true;

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData: fetchData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, submitReview, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast, requestNotificationPermission
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, addToCart, removeFromCart, updateCartQuantity, fetchData, sendNotification, submitReview, toggleFavorite]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, Notification, Review } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE, UPSA_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  reviews: Review[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<Notification>) => Promise<boolean>;

  submitReview: (review: Omit<Review, 'createdAt' | 'user'>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`LocalStorage quota exceeded.`); }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Core Loading States
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(false);
  const [connectionError, setConnectionError] = useState<boolean>(false);

  // App/User States
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // UI States
  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });
  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  // Theme Sync
  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (!isThemeSwitchingAllowed) {
        root.classList.remove('dark');
    } else {
        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');
    }
  }, [theme, isThemeSwitchingAllowed]);

  // Persistent Storage Sync
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // --- Data Fetchers ---
  const fetchNotifications = useCallback(async (userId: string, role: Role) => {
      if (!userId) return;
      try {
          const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`)
            .order('created_at', { ascending: false });

          if (!error && data) {
              const filtered = data.filter(n => n.target_scope !== 'role' || n.target_role === role);
              setNotifications(filtered.map(n => ({
                  ...n, userId: n.user_id, targetRole: n.target_role,
                  targetScope: n.target_scope, relatedId: n.related_id,
                  isRead: n.is_read, createdAt: n.created_at
              })));
          }
      } catch (e) { console.warn("Notif fetch error", e); }
  }, []);

  const fetchReviews = useCallback(async () => {
    try {
        const { data, error } = await supabase
            .from('reviews')
            .select('*, profiles(name, avatar_url)')
            .order('created_at', { ascending: false });
        if (data && !error) {
            setReviews(data.map(r => ({
                ...r, productId: r.product_id, vendorId: r.vendor_id,
                userId: r.user_id, createdAt: r.created_at,
                user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
            })));
        }
    } catch (e) { console.warn("Review fetch error", e); }
  }, []);

  const fetchData = useCallback(async () => {
      try {
          setIsDataLoading(true);
          const [pData, vData, oData, cDataRaw, uData] = await Promise.all([
              supabase.from('products').select('*').order('created_at', { ascending: false }),
              supabase.from('vendors').select('*'),
              supabase.from('orders').select('*').order('created_at', { ascending: false }),
              supabase.from('couriers').select('*'),
              supabase.from('profiles').select('*')
          ]);

          if (pData.data) setProducts(pData.data.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
          if (vData.data) setVendors(vData.data.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone, campus: v.campus })));
          if (oData.data) setOrders(oData.data.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
          if (cDataRaw.data && uData.data) {
              const profileMap = new Map(uData.data.map((p: any) => [p.id, p]));
              setCouriers(cDataRaw.data.map((d: any) => ({ ...d, userId: d.user_id, fullName: (profileMap.get(d.user_id) as any)?.name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
          }
          if (uData.data) setUsers(uData.data as any);
      } catch (e) { 
          console.error("Data fetch error", e); 
      } finally { 
          setIsDataLoading(false); 
      }
  }, []);

  const fetchUserProfile = async (userId: string): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;
          if (data) {
              const user: User = { 
                  ...data, roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url, phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };
              setCurrentUser(user);
              return user;
          }
      } catch (e) { console.error("Profile fetch error", e); }
      return null;
  };

  // --- Boot Logic ---
  useEffect(() => {
    let isMounted = true;

    const initialize = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && isMounted) {
          const profile = await fetchUserProfile(session.user.id);
          if (profile) {
            fetchNotifications(session.user.id, currentRole);
          }
        }
        await Promise.all([fetchData(), fetchReviews()]);
      } catch (e) {
        console.error("Boot error", e);
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };

    initialize();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' && session?.user) {
            const profile = await fetchUserProfile(session.user.id);
            if (profile) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                const finalRole: Role = (persistedRole && profile.roles.includes(persistedRole)) 
                    ? persistedRole 
                    : (profile.roles.includes('admin') ? 'admin' : (profile.roles.includes('vendor') ? 'vendor' : 'buyer'));
                setCurrentRole(finalRole);
                fetchNotifications(session.user.id, finalRole);
            }
        } else if (event === 'SIGNED_OUT') {
            setCurrentUser(null);
            setCurrentRole('guest');
            setNotifications([]);
        }
    });

    return () => {
      isMounted = false;
      subscription.unsubscribe();
    };
  }, []); 

  // Realtime Subscriptions
  useEffect(() => {
      if (isLoading) return;
      const channels = [
          supabase.channel('p-db').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, fetchData).subscribe(),
          supabase.channel('o-db').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, fetchData).subscribe(),
          supabase.channel('v-db').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, fetchData).subscribe(),
          supabase.channel('notif-realtime').on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => {
              if (currentUser) fetchNotifications(currentUser.id, currentRole);
          }).subscribe(),
          supabase.channel('r-db').on('postgres_changes', { event: '*', schema: 'public', table: 'reviews' }, fetchReviews).subscribe()
      ];
      return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [isLoading, currentUser, currentRole, fetchData, fetchReviews, fetchNotifications]);

  // --- Methods ---

  const sendNotification = useCallback(async (payload: Partial<Notification>) => {
    try {
        const { error } = await supabase.from('notifications').insert({
            user_id: payload.userId || null,
            target_role: payload.targetRole || null,
            target_scope: payload.targetScope || 'individual',
            type: payload.type || 'system',
            title: payload.title || 'Notification',
            message: payload.message || '',
            related_id: payload.relatedId || null,
            priority: payload.priority || 'normal',
            is_read: false
        });
        if (error) throw error;
        return true;
    } catch (e: any) {
        console.error("In-app notification dispatch failed:", e.message);
        return false;
    }
  }, []);

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      return { success: true, role: currentRole }; 
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
           return await login(email, password); 
      }
      return { success: false };
  };

  const logout = async () => { await supabase.auth.signOut(); };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) { 
          setCurrentRole(role); 
          safeSetItem('lynqed_role', role); 
          showToast(`Switched to ${role} Mode`, 'info'); 
          if (currentUser) fetchNotifications(currentUser.id, role);
      }
  };

  const updateProfile = async (data: Partial<User>) => {
    if(!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address }).eq('id', currentUser.id);
    if(!error) { showToast("Profile updated", "success"); fetchUserProfile(currentUser.id); return { success: true }; }
    return { success: false };
  };

  const updateTheme = (t: ThemeMode) => { setTheme(t); safeSetItem('lynqed_theme_last', t); };
  const toggleThemeSwitching = (allowed: boolean) => { setIsThemeSwitchingAllowed(allowed); safeSetItem('lynqed_sys_theme_allowed', String(allowed)); };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` });
      return { success: !error, error: error?.message };
  };

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      return { success: !error, error: error?.message };
  };

  const addToCart = useCallback((p: Product, q = 1) => { 
      setCart(prev => { 
          const x = prev.find(i => i.productId === p.id); 
          return x ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; 
      }); 
      showToast(`Added ${p.title}`, "success"); 
  }, [showToast]);

  const removeFromCart = useCallback((pid: string) => { 
      setCart(prev => prev.filter(i => i.productId !== pid)); 
      showToast("Removed", "info"); 
  }, [showToast]);

  const updateCartQuantity = useCallback((pid: string, qty: number) => { 
      if(qty <= 0) removeFromCart(pid); 
      else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } 
  }, [removeFromCart]);

  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, 
                  delivery_fee: fee, status: 'placed', delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();
              if (error) throw error;
              if (vendor) await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order Received!', message: `New order for ₵${(subtotal+fee).toFixed(2)}.`, relatedId: data.id, priority: 'high' });
              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', orderId); 
      if (!error) {
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: ${status.replace('_', ' ')}.`, relatedId: orderId });
          }
          fetchData(); 
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); 
      if (!error) {
          const v = vendors.find(vend => vend.vendorId === vid);
          if (v) await sendNotification({ userId: v.userId, type: 'approval', title: 'Vendor Account Verified!', message: 'Your store is now live on LYNQED! You can start adding products.', priority: 'high' });
          fetchData();
      }
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type });
      if(!error) { fetchData(); return { success: true }; }
      return { success: false };
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { showToast('Upload failed', 'error'); return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;
      const { error } = await supabase.from('vendors').upsert({ vendor_id: vid, user_id: currentUser.id, store_name: data.store_name, store_description: data.store_description, location: data.location, contact_phone: data.contact_phone, store_avatar_url: data.store_avatar_url, is_approved: ex ? ex.isApproved : false, rating: ex ? ex.rating : 5.0, campus: data.campus }, { onConflict: 'user_id' });
      if (!error) {
          if (!currentUser.roles.includes('vendor')) await supabase.from('profiles').update({ roles: [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])] }).eq('id', currentUser.id);
          fetchData(); return { success: true };
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, campus: v.campus, contact_phone: prod.contact_phone });
      if (!error) { showToast("Submitted", "success"); fetchData(); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id); fetchData(); };
  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };
  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { await supabase.from('products').update({ is_trending: isTrending }).eq('id', id); fetchData(); };
  const toggleFavorite = useCallback((pid: string) => { const isRem = favorites.includes(pid); setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); showToast(isRem ? 'Removed from wishlist' : 'Added to wishlist', isRem ? 'info' : 'success'); }, [favorites, showToast]);
  const markNotificationRead = async (id: string) => { setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n)); await supabase.from('notifications').update({ is_read: true }).eq('id', id); };
  const markAllNotificationsRead = async () => { if (!currentUser) return; setNotifications(prev => prev.map(n => ({ ...n, isRead: true }))); await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id).eq('is_read', false); };
  const deleteNotification = async (id: string) => { setNotifications(prev => prev.filter(n => n.id !== id)); await supabase.from('notifications').delete().eq('id', id); };
  const submitReview = useCallback(async (review: Omit<Review, 'createdAt' | 'user'>) => { try { const { error } = await supabase.from('reviews').upsert({ id: review.id || undefined, product_id: review.productId, vendor_id: review.vendorId, user_id: review.userId, rating: review.rating, comment: review.comment, images: review.images }); if (error) throw error; showToast("Review submitted!", "success"); fetchReviews(); return true; } catch (e) { showToast("Failed to submit review", "error"); return false; } }, [showToast, fetchReviews]);
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); if (status === 'approved') { const profile = users.find(u => u.id === userId); if (profile) await supabase.from('profiles').update({ roles: [...new Set([...profile.roles, 'courier' as Role, 'buyer' as Role])] }).eq('id', userId); } fetchData(); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchData(); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); fetchData(); };
  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData: fetchData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, submitReview, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, addToCart, removeFromCart, updateCartQuantity, fetchData, sendNotification, submitReview, toggleFavorite]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Avatar, Spinner, Input } from '../components/UI';
import { Product, Review, Vendor } from '../types';
import { INITIAL_LOCATION_CACHE } from '../constants';

// --- Review Modal ---
export const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
    existingReview?: Review;
}> = ({ productId, vendorId, onClose, existingReview }) => {
    const { submitReview, currentUser, uploadFile } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [images, setImages] = useState<string[]>(existingReview?.images || []);
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setUploading(true);
            const files = Array.from(e.target.files);
            const uploaded: string[] = [];
            for (const file of files) {
                const url = await uploadFile(file, 'review-images');
                if (url) uploaded.push(url);
            }
            setImages(prev => [...prev, ...uploaded]);
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            id: existingReview?.id, productId, vendorId, userId: currentUser.id,
            rating, comment, images
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-w-lg rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white">{existingReview ? 'Edit Review' : 'Write a Review'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} type="button" onClick={() => setRating(star)} className={`text-3xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-200 dark:text-gray-700'}`}>
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>
                    <textarea
                        className="w-full rounded-2xl bg-gray-50 dark:bg-gray-900 p-4 text-sm h-32 outline-none border border-gray-100 dark:border-gray-800 dark:text-white"
                        placeholder="Tell us what you think..."
                        value={comment}
                        onChange={e => setComment(e.target.value)}
                        required
                    />
                    <div className="flex flex-wrap gap-2">
                        {images.map((img, i) => (
                            <img key={i} src={img} className="w-16 h-16 rounded-lg object-cover" alt="Review" />
                        ))}
                        {images.length < 3 && (
                            <button type="button" onClick={() => fileRef.current?.click()} className="w-16 h-16 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center text-gray-400 hover:border-primary hover:text-primary transition-colors">
                                {uploading ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-camera"></i>}
                            </button>
                        )}
                    </div>
                    <input type="file" ref={fileRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
                    <Button fullWidth size="lg" type="submit" disabled={submitting || uploading}>{submitting ? 'Posting...' : 'Submit Review'}</Button>
                </form>
            </Card>
        </div>
    );
};

// --- Store Page ---
export const StorePage: React.FC = () => {
    const { vendorId } = useParams();
    const navigate = useNavigate();
    const { vendors, products, reviews, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const storeProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');
    const storeReviews = reviews.filter(r => r.vendorId === vendorId);

    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstance = useRef<any>(null);

    const getBestCoords = (locationName: string): [number, number] => {
        const clean = locationName.toLowerCase().trim();
        if (INITIAL_LOCATION_CACHE[clean]) return INITIAL_LOCATION_CACHE[clean];
        const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k) || k.includes(clean));
        if (key) return INITIAL_LOCATION_CACHE[key];
        return [5.6506, -0.1962];
    };

    useEffect(() => {
        if (!vendor || !mapRef.current || !window.L || mapInstance.current) return;

        const coords = getBestCoords(vendor.location);
        const map = window.L.map(mapRef.current, {
            zoomControl: true,
            attributionControl: false,
            dragging: true,
            scrollWheelZoom: true,
            touchZoom: true,
            doubleClickZoom: true
        }).setView(coords, 17);

        if (map.zoomControl) {
            map.zoomControl.setPosition('topright');
        }

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        window.L.marker(coords, {
            icon: window.L.divIcon({
                className: 'custom-map-pin',
                html: `
                    <div class="relative flex flex-col items-center">
                        <div class="absolute -top-12 bg-gray-900 text-white text-[10px] font-black px-2.5 py-1 rounded-lg whitespace-nowrap shadow-xl border border-white/20 animate-bounce-slight uppercase tracking-widest z-50">
                            ${vendor.location}
                        </div>
                        <div class="w-12 h-12 bg-primary rounded-2xl border-4 border-white shadow-glow flex items-center justify-center text-white ring-4 ring-primary/20 pulse-ring">
                            <i class="fa-solid fa-store text-lg"></i>
                        </div>
                    </div>
                `,
                iconSize: [48, 48],
                iconAnchor: [24, 48]
            })
        }).addTo(map);

        mapInstance.current = map;
        setTimeout(() => map.invalidateSize(), 300);

        return () => {
            if (mapInstance.current) {
                mapInstance.current.remove();
                mapInstance.current = null;
            }
        };
    }, [vendor]);

    if (!vendor) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const handleShare = async () => {
        const shareData = {
            title: vendor.storeName,
            text: `Check out ${vendor.storeName} on LYNQED!`,
            url: `https://lynqed.vercel.app/#/store/${vendorId}`
        };

        if (navigator.share) {
            try {
                await navigator.share(shareData);
            } catch (err) {
                console.log('Share failed', err);
            }
        } else {
            navigator.clipboard.writeText(shareData.url);
            showToast("Store link copied!", "success");
        }
    };

    const handleWhatsApp = () => {
        if (!vendor.contactPhone) {
            showToast("Vendor contact info not found.", "error");
            return;
        }
        let cleanPhone = vendor.contactPhone.replace(/\D/g, '');
        if (cleanPhone.startsWith('0')) {
            cleanPhone = '233' + cleanPhone.substring(1);
        }
        const message = encodeURIComponent(`Hi ${vendor.storeName}, I'm reaching out to you via LYNQED.`);
        window.open(`https://wa.me/${cleanPhone}?text=${message}`, '_blank');
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            <div className="relative h-[420px] w-full overflow-hidden border-b border-gray-100 dark:border-gray-800">
                <div ref={mapRef} className="absolute inset-0 z-0 h-full w-full bg-gray-200 dark:bg-gray-800" />
                <div className="absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-black/30 via-black/10 to-transparent pointer-events-none z-10" />
                <div className="absolute inset-x-0 bottom-0 h-64 bg-gradient-to-t from-gray-50 via-gray-50/40 dark:from-darkBg dark:via-darkBg/40 to-transparent pointer-events-none z-10" />
                <button onClick={() => navigate(-1)} className="absolute top-6 left-6 z-20 w-12 h-12 rounded-full bg-white/95 dark:bg-darkSurface/95 shadow-xl flex items-center justify-center text-gray-900 dark:text-white backdrop-blur-md active:scale-90 transition-all border border-white/50 dark:border-white/10"><i className="fa-solid fa-arrow-left"></i></button>
                <div className="absolute bottom-0 left-0 right-0 z-20 px-6 pb-8 pointer-events-none">
                    <div className="flex items-end gap-6">
                        <div className="relative pointer-events-auto">
                            <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="xl" className="border-4 border-white dark:border-darkSurface shadow-[0_20px_50px_rgba(0,0,0,0.2)] rounded-[2.5rem]" />
                            <div className="absolute -bottom-1 -right-1 bg-green-500 w-8 h-8 rounded-full border-4 border-white dark:border-darkSurface flex items-center justify-center shadow-lg"><div className="w-2.5 h-2.5 bg-white rounded-full animate-pulse"></div></div>
                        </div>
                        <div className="flex-1 pb-1">
                            <div className="inline-flex items-center gap-2 px-2.5 py-1 bg-white/90 dark:bg-black/40 backdrop-blur-md rounded-lg mb-2 border border-white/20"><i className="fa-solid fa-location-dot text-red-500 text-[10px]"></i><span className="text-[10px] font-black uppercase text-gray-900 dark:text-white tracking-widest">{vendor.location}</span></div>
                            <h1 className="text-4xl font-display font-black text-gray-900 dark:text-white leading-none tracking-tight drop-shadow-sm">{vendor.storeName}</h1>
                            <div className="flex items-center gap-3 mt-3"><Badge color="violet" className="px-3 py-1 text-[9px] shadow-sm">Verified LYNQED Merchant</Badge><div className="flex items-center gap-1.5 text-xs font-black text-gray-700 dark:text-gray-300 bg-white/80 dark:bg-black/30 backdrop-blur-sm px-2.5 py-1 rounded-xl"><i className="fa-solid fa-star text-yellow-400"></i>{vendor.rating.toFixed(1)} ({storeReviews.length})</div></div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="px-6 mt-8 space-y-8 max-w-5xl mx-auto">
                <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <Button fullWidth icon="phone" size="lg" className="h-14 text-base" onClick={() => window.open(`tel:${vendor.contactPhone}`)}>Call Merchant</Button>
                        <button 
                            onClick={handleWhatsApp}
                            className="h-14 rounded-2xl bg-emerald-500 text-white flex items-center justify-center gap-3 font-bold shadow-lg shadow-emerald-500/20 active:scale-95 transition-all text-base"
                        >
                            <i className="fa-brands fa-whatsapp text-2xl"></i>
                            WhatsApp
                        </button>
                    </div>
                    <Button fullWidth variant="secondary" size="lg" className="h-14 text-base" icon="share-nodes" onClick={handleShare}>Share Store</Button>
                </div>
                <div>
