                    onClick={() => { switchRole('buyer'); navigate('/buyer/dashboard'); }}
                    className="block mx-auto mt-4 text-xs font-bold text-gray-400 hover:text-primary transition-colors"
                  >
                    Go back to shopping
                  </button>
             </div>
         );
    }

    const handleSubmit = async (data: any) => {
        setLoading(true);
        const success = await addProduct(data);
        setLoading(false);
        if (success) {
            navigate('/vendor/products');
        } 
    };

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-safe animate-fade-in">
            <div className="flex items-center mb-6">
                <button onClick={() => navigate(-1)} className="mr-4 w-10 h-10 bg-white dark:bg-darkSurface dark:text-white rounded-full shadow-sm flex items-center justify-center transition-all hover:scale-105 active:scale-95 border border-gray-100 dark:border-gray-800"><i className="fa-solid fa-arrow-left"></i></button>
                <h1 className="text-xl font-black text-gray-900 dark:text-white font-display uppercase">List New Item</h1>
            </div>
            <ProductForm onSubmit={handleSubmit} isLoading={loading} />
        </div>
    );
};

