                                <button 
                                    onClick={(e) => { e.stopPropagation(); toggleFavorite(product.id); }}
                                    className={`absolute top-3 right-3 w-9 h-9 rounded-full flex items-center justify-center transition-all duration-300 transform ${isFavorite ? 'bg-red-500 text-white shadow-lg scale-100 opacity-100' : 'bg-white/80 dark:bg-darkSurface/80 text-gray-400 hover:text-red-500 scale-90 opacity-0 group-hover:scale-100 group-hover:opacity-100'}`}
                                >
                                    <i className={`fa-${isFavorite ? 'solid' : 'regular'} fa-heart text-[12px]`}></i>
                                </button>

                                {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center backdrop-blur-[2px]"><span className="bg-black text-white text-[10px] px-3 py-1.5 rounded-full font-black uppercase tracking-widest shadow-xl">Sold Out</span></div>}
                            </div>
                            <div className="p-4 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-sm text-gray-900 dark:text-white font-bold leading-tight line-clamp-2">{product.title}</h3>
                                    <p className="text-[11px] text-gray-400 mt-1.5 font-bold uppercase tracking-tight">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-4">
                                    <span className="text-base font-black text-gray-900 dark:text-white">₵{product.price}</span>
                                    <button 
                                        className={`w-9 h-9 rounded-2xl flex items-center justify-center text-white transition-all shadow-sm ${isInCart ? 'bg-green-500 scale-105' : 'bg-slate-900 dark:bg-slate-100 dark:text-slate-900 active:scale-90 hover:shadow-lg'}`}
